INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "然而是说，后面的话和前面的不一样。", "primary_collocate": null, "pronunciation": "rán ér", "ipa": "ɻan˧˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "他很努力，然而成绩还是不好。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很冷，然而他只穿了一件衣服。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了很久，然而他没有来。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不难，然而做好不容易。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想去，然而家里有事。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不远，然而走起来很累。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都以为会下雨，然而天一直很好。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很好，然而做得不太好。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同意了，然而他还是不愿意。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很小，然而客人特别多。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "转折连词，后句与前句意思不同或相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然而", "is_correct": true, "explanation": "「然而」表示转折，引出与「很努力」相反的结果：成绩还是不好。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，与后句「还是不好」的转折意思矛盾。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」引出原因，「很努力」不能作为「成绩不好」的原因。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进补充，与「成绩还是不好」的转折语气不合。"}], "explanations": {"然而": "「然而」表示转折，引出与「很努力」相反的结果：成绩还是不好。", "所以": "语义：「所以」表示因果，与后句「还是不好」的转折意思矛盾。", "因为": "语义：「因为」引出原因，「很努力」不能作为「成绩不好」的原因。", "而且": "语义：「而且」表示递进补充，与「成绩还是不好」的转折语气不合。"}, "sentence_index": 0, "correct_answer": "然而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不仅聪明，然而很努力。", "explanation": "这里应该用〈而且〉。「不仅……而且……」表示递进，「然而」表示转折，不能与「不仅」配合。"}, {"text": "他打开门，然而看见了老师。", "explanation": "这里应该用〈于是〉。「然而」表示转折，这里前后是先后相继的动作，应用「于是」。"}, {"text": "天下雨了，然而比赛取消了。", "explanation": "这里应该用〈因此〉。「然而」表示转折，下雨和取消比赛是因果关系，应用「因此」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": true, "explanation": "「然而」表示转折：以为会下雨，结果天一直很好，前后正好相反。"}, {"text": "况且", "is_correct": false, "explanation": "语义：「况且」表示递进补充，与「以为会下雨」之后的转折不合。"}, {"text": "故此", "is_correct": false, "explanation": "语域：「故此」偏文言；语义：表示因果，与「以为会下雨」的落空语境不合。"}, {"text": "不然", "is_correct": false, "explanation": "语域：「不然」口语色彩较重；语义：表示假设，与前句的语境不合。"}], "explanations": {"然而": "「然而」表示转折：以为会下雨，结果天一直很好，前后正好相反。", "况且": "语义：「况且」表示递进补充，与「以为会下雨」之后的转折不合。", "故此": "语域：「故此」偏文言；语义：表示因果，与「以为会下雨」的落空语境不合。", "不然": "语域：「不然」口语色彩较重；语义：表示假设，与前句的语境不合。"}, "sentence_index": 6, "correct_answer": "然而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说的就是那本书，然而是我昨天买的那本。", "explanation": "这里应该用〈也就是〉。「然而」表示转折，这里是对前面内容的解释说明，应用「也就是」。"}, {"text": "这次会议很重要，然而我们还要讨论预算。", "explanation": "这里应该用〈另外〉。「然而」表示转折，这里是补充另一件事，不是相反的内容，应用「另外」。"}, {"text": "他每天都来图书馆，然而他很努力。", "explanation": "这里应该用〈可见〉。「然而」引出相反的内容，这里是由行为推出结论，应用「可见」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都练习，不然而比赛时还是紧张。", "corrected_sentence": "他每天都练习，然而比赛时还是紧张。", "error_description": "「不」不能加在「然而」前，「然而」是转折连词，前面不能加否定词；「不然」是另一个词，不能与「而」拼接。正确说法是「他每天都练习，然而比赛时还是紧张。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都很累，但是然而大家还在工作。", "corrected_sentence": "我们都很累，然而大家还在工作。", "error_description": "「但是」和「然而」都表示转折，不能叠用，只用其中一个。正确说法是「我们都很累，然而大家还在工作。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
