INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86660, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示转折，用来引出与前面意思相反的话。", "primary_collocate": null, "pronunciation": "rán ér", "ipa": "ɻan˧˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "她准备了很久，然而比赛时还是错了。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法看起来很好，然而没人愿意用。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前很有钱，然而现在什么都没有了。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打了三次电话，然而都没人接。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都觉得他会赢，然而他输了。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有名，然而我觉得不太好看。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很喜欢那只小狗，然而不能带回家。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想帮忙，然而没有时间。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说没事，然而他还是很担心。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山不高，然而风景很美。", "target_word": "然而", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示转折的连词，引出与上文相反的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6df74260-6b71-43b4-8f1f-e506de1537f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "然而", "is_correct": true, "explanation": "「然而」表示转折：准备了很久，比赛时却还是错了，前后意思相反。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果，与「还是错了」的意外语气不合。"}, {"text": "况且", "is_correct": false, "explanation": "语义：「况且」表示递进补充，与前句「准备了很久」的落空不合。"}, {"text": "不然", "is_correct": false, "explanation": "语域：「不然」口语色彩较重；语义：表示假设，与前句的语境不合。"}], "explanations": {"然而": "「然而」表示转折：准备了很久，比赛时却还是错了，前后意思相反。", "因此": "语义：「因此」表示因果，与「还是错了」的意外语气不合。", "况且": "语义：「况且」表示递进补充，与前句「准备了很久」的落空不合。", "不然": "语域：「不然」口语色彩较重；语义：表示假设，与前句的语境不合。"}, "sentence_index": 0, "correct_answer": "然而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会说英语，然而还会说法语。", "explanation": "这里应该用〈另外〉。「然而」表示转折，这里两件事是并列补充的关系，应用「另外」。"}, {"text": "他吃完饭，然而去了图书馆。", "explanation": "这里应该用〈接着〉。「然而」表示转折，这里是先后相继的动作，应用「接着」。"}, {"text": "天下雨了，然而比赛取消了。", "explanation": "这里应该用〈因此〉。「然而」表示转折，下雨和取消比赛是因果关系，应用「因此」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": true, "explanation": "「然而」表示转折：喜欢却不能带回家，前后意思相反。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进，与「不能带回家」的转折意思不合。"}, {"text": "故而", "is_correct": false, "explanation": "语域：「故而」偏书面文言；语义：表示因果，「喜欢」与「不能带回家」之间的因果说不通。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，「因为喜欢所以不能带回家」前后不通。"}], "explanations": {"然而": "「然而」表示转折：喜欢却不能带回家，前后意思相反。", "而且": "语义：「而且」表示递进，与「不能带回家」的转折意思不合。", "故而": "语域：「故而」偏书面文言；语义：表示因果，「喜欢」与「不能带回家」之间的因果说不通。", "所以": "语义：「所以」表示因果，「因为喜欢所以不能带回家」前后不通。"}, "sentence_index": 6, "correct_answer": "然而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是医生，然而他的工作是治病救人。", "explanation": "这里应该用〈也就是说〉。「然而」表示转折，这里是对前一分句的解释，前后没有相反的内容，应用「也就是说」。"}, {"text": "然而带了伞，我没有淋湿。", "explanation": "这里应该用〈幸亏〉。「然而」表示转折，这里表示因为带了伞而庆幸没有淋湿，应用「幸亏」。"}, {"text": "他每天都起得很早，然而他很勤奋。", "explanation": "这里应该用〈可见〉。「然而」引出相反的内容，这里是由行为推出结论，应用「可见」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份工作很累，但是然而我很喜欢。", "corrected_sentence": "这份工作很累，然而我很喜欢。", "error_description": "「但是」和「然而」都表示转折，不能叠用，只用其中一个。正确说法是「这份工作很累，然而我很喜欢。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想参加比赛，不然而身体不太好。", "corrected_sentence": "他想参加比赛，然而身体不太好。", "error_description": "「不」不能加在「然而」前，「然而」是转折连词，前面不能加否定词；「不然」是另一个词，不能与「而」拼接。正确说法是「他想参加比赛，然而身体不太好。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1560dc5-79cc-48f6-8e06-bb098543ca56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
