INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动力是让东西动起来的力量。", "primary_collocate": null, "pronunciation": "dòng lì", "ipa": "tʊŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这辆车的动力很大。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电动车用电作为动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风给小船提供了动力。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的动力来自电。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这艘船用太阳能做动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车没有动力，就走不了。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水车靠水的动力转动。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆卡车动力足，能爬很陡的山。", "target_word": "动力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的动力来自发动机。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发动机给汽车提供动力。", "target_word": "动力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "原动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词；让机器、车船等运转的力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力（dòng lì）：让机器、车辆运转的力量，是正确答案。"}, {"text": "冻梨", "is_correct": false, "explanation": "冻梨（dòng lí）与“动力”第二个音节的声调不同，意思是冻过的梨。"}, {"text": "冬梨", "is_correct": false, "explanation": "冬梨（dōng lí）两个音节的声调都与“动力”不同，意思是冬天成熟的梨。"}, {"text": "懂礼", "is_correct": false, "explanation": "懂礼（dǒng lǐ）两个音节的声调都与“动力”不同，意思是懂得礼节。"}], "explanations": {"动力": "动力（dòng lì）：让机器、车辆运转的力量，是正确答案。", "冻梨": "冻梨（dòng lí）与“动力”第二个音节的声调不同，意思是冻过的梨。", "冬梨": "冬梨（dōng lí）两个音节的声调都与“动力”不同，意思是冬天成熟的梨。", "懂礼": "懂礼（dǒng lǐ）两个音节的声调都与“动力”不同，意思是懂得礼节。"}, "sentence_index": null, "correct_answer": "动力"}, "level_3": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力：车的运转力量，说“动力很大”符合车辆的语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不说大小，与“很大”的搭配不合。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不用“大”来形容，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格通常说“高”或“低”，不说“很大”。"}], "explanations": {"动力": "动力：车的运转力量，说“动力很大”符合车辆的语境。", "颜色": "语义：颜色不说大小，与“很大”的搭配不合。", "名字": "语义：名字不用“大”来形容，句意不通。", "价格": "搭配：价格通常说“高”或“低”，不说“很大”。"}, "sentence_index": 0, "correct_answer": "动力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的动力很快，两秒就能加速到一百公里。", "explanation": "这里应该用〈速度〉。动力指使机器运转的力量，不说快慢；快慢要用“速度”。"}, {"text": "这辆车有一根动力，能爬很陡的山。", "explanation": "这里应该用〈股〉。动力是一股股的力，量词“根”用于细长的条状物，不能用来计量动力。"}, {"text": "这台机器的动力很香，闻起来很舒服。", "explanation": "这里应该用〈气味〉。动力指使机器运转的力量，没有香与不香之分，“香”描述的是气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力（dòng lì）：让机器运转的力量，是正确答案。"}, {"text": "重力", "is_correct": false, "explanation": "重力（zhòng lì）声母由 d 变为 zh，声调也不同，意思是地球对物体的吸引力。"}, {"text": "同理", "is_correct": false, "explanation": "同理（tóng lǐ）两个音节的声调都与“动力”不同，意思是道理相同。"}, {"text": "通力", "is_correct": false, "explanation": "通力（tōng lì）声母由 d 变为 t，声调也不同，意思是共同出力。"}], "explanations": {"动力": "动力（dòng lì）：让机器运转的力量，是正确答案。", "重力": "重力（zhòng lì）声母由 d 变为 zh，声调也不同，意思是地球对物体的吸引力。", "同理": "同理（tóng lǐ）两个音节的声调都与“动力”不同，意思是道理相同。", "通力": "通力（tōng lì）声母由 d 变为 t，声调也不同，意思是共同出力。"}, "sentence_index": null, "correct_answer": "动力"}, "level_3": {"options": [{"text": "动力", "is_correct": true, "explanation": "动力：水车转动的力量来自水的动力，与句意相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能推动水车转动，句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是书写用的液体，与水车的转动无关。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“靠……的尺寸”不成立，尺寸不能作为转动的动力来源。"}], "explanations": {"动力": "动力：水车转动的力量来自水的动力，与句意相合。", "味道": "语义：味道不能推动水车转动，句意不通。", "墨水": "语义：墨水是书写用的液体，与水车的转动无关。", "尺寸": "搭配：“靠……的尺寸”不成立，尺寸不能作为转动的动力来源。"}, "sentence_index": 6, "correct_answer": "动力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的动力很多，能做很多事。", "explanation": "这里应该用〈功能〉。功能可以多少，动力是运转的力量，不说多少。"}, {"text": "这辆车的动力很漂亮，远看很有气势。", "explanation": "这里应该用〈外观〉。动力指运转的力量，不指外形美观。"}, {"text": "这辆车的动力是鲜艳的红色，远看很醒目。", "explanation": "这里应该用〈颜色〉。动力没有鲜艳与否的属性，颜色才有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款车的动力足很，爬坡很轻松。", "corrected_sentence": "这款车的动力很足，爬坡很轻松。", "error_description": "位置错误：“很”应放在“足”前面，说“很足”，不说“足很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个电池能给电车提供一只动力。", "corrected_sentence": "这个电池能给电车提供一股动力。", "error_description": "量词错误：“动力”是一股股的力，应用量词“股”，不能用“只”。应说“提供一股动力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
