INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86665, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南部是在南边的地方。", "primary_collocate": null, "pronunciation": "nán bù", "ipa": "nan˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我的家在这个国家的南部。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部的冬天不太冷。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在中国南部工作了三年。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的南部有一座大山。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家北部很冷，南部很热。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天坐火车去中国南部。", "target_word": "南部", "complexity_tier": "T3", "furigana": "wǒ men míng tiān zuò huǒ chē qù zhōng guó nán bù", "sentence_source": "generated"}, {"text": "南部的人喜欢吃米饭。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座公园的南部有很多树。", "target_word": "南部", "complexity_tier": "T3", "furigana": "zhè zuò gōng yuán de nán bù yǒu hěn duō shù", "sentence_source": "generated"}, {"text": "他们住在学校的南部。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过南部的海边。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "南部地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体中靠南边的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86665, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“学生”指人，不能表示家所在的地方，“我的家在这个国家的学生”不通。"}, {"text": "东", "is_correct": false, "explanation": "搭配：单音节方位词“东”作定语要加“边”或“部”，“国家的东”不能直接作处所。"}, {"text": "南部", "is_correct": true, "explanation": "“南部”是地点名词，与“我的家在这个国家的”搭配，表示国家南面的地区。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是地点，不能表示家的位置。"}], "explanations": {"学生": "语义：“学生”指人，不能表示家所在的地方，“我的家在这个国家的学生”不通。", "东": "搭配：单音节方位词“东”作定语要加“边”或“部”，“国家的东”不能直接作处所。", "南部": "“南部”是地点名词，与“我的家在这个国家的”搭配，表示国家南面的地区。", "颜色": "语义：“颜色”不是地点，不能表示家的位置。"}, "sentence_index": 0, "correct_answer": "南部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的南部断了。", "explanation": "这里应该用〈南边〉。“南部”指地区的南面部分，不指物体的一侧；椅子的一侧要说“南边”。"}, {"text": "这块饼干的南部烤焦了。", "explanation": "这里应该用〈南边〉。“南部”只用于地区，不能指饼干的一面；饼干的一侧要说“南边”。"}, {"text": "他的南部很疼，所以去了医院。", "explanation": "这里应该用〈肚子〉。“南部”指地区的南面，不指人身上的部位；腹部疼要说“肚子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86665, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”指时间，不能作“……的人”的修饰语，“冬天的人”不通。"}, {"text": "西", "is_correct": false, "explanation": "搭配：单音节方位词“西”作定语要加“边”或“部”，不能说“西的人”。"}, {"text": "南部", "is_correct": true, "explanation": "“南部”是地区名词，可以修饰“人”，表示南方地区的人。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不能指地区的人。"}], "explanations": {"冬天": "语义：“冬天”指时间，不能作“……的人”的修饰语，“冬天的人”不通。", "西": "搭配：单音节方位词“西”作定语要加“边”或“部”，不能说“西的人”。", "南部": "“南部”是地区名词，可以修饰“人”，表示南方地区的人。", "手机": "语义：“手机”是物品，不能指地区的人。"}, "sentence_index": 6, "correct_answer": "南部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在明天的南部见面吧。", "explanation": "这里应该用〈南边〉。“南部”是地区名词，不能受“明天的”这类时间词修饰；见面的地点要说“在南边见面”。"}, {"text": "这首歌的南部很好听。", "explanation": "这里应该用〈旋律〉。“南部”只指地区的方位部分，歌曲没有方位，不能说“歌的南部”；说歌的部分要用“旋律”。"}, {"text": "妈妈的南部很大，我很喜欢。", "explanation": "这里应该用〈身材〉。“南部”指地区的方位部分，不指人身上的部位；说人的体型要用“身材”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86665, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐的学校城市的南部。", "corrected_sentence": "我姐姐的学校在城市的南部。", "error_description": "错误：“南部”作处所时，前面漏了介词“在”。正确说法是“学校在城市的南部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86665, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校南部在一个大操场。", "corrected_sentence": "我们学校南部有一个大操场。", "error_description": "错误：存在句中“有”误写作“在”。“在”不能直接带“一个大操场”作宾语，此处应用“有”。正确说法是“我们学校南部有一个大操场。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
