INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "南边的地区。", "primary_collocate": null, "pronunciation": "nán bù", "ipa": "nan˧˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "南部地区这几天下了大雨。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北部很冷，南部很暖和。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省的南部种了很多茶。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多游客想去云南南部玩。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部的天气比北部热。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在南部长大，不怕热。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部的路比北部的好走。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在南部有三个工厂。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，南部的雪比北部少。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南部一年能种两次水稻。", "target_word": "南部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "南部地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "南边的地区，常与北部相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冬天", "is_correct": false, "explanation": "语义：“冬天”指时间，不能与“地区”组成地点名词短语，“冬天地区”不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能作地区的名称，“椅子地区”不通。"}, {"text": "南部", "is_correct": true, "explanation": "“南部地区”指南边的地区，“南部”修饰“地区”，与句中语境相符。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”是物品，不能作地区的名称。"}], "explanations": {"冬天": "语义：“冬天”指时间，不能与“地区”组成地点名词短语，“冬天地区”不通。", "椅子": "语义：“椅子”是家具，不能作地区的名称，“椅子地区”不通。", "南部": "“南部地区”指南边的地区，“南部”修饰“地区”，与句中语境相符。", "电脑": "语义：“电脑”是物品，不能作地区的名称。"}, "sentence_index": 0, "correct_answer": "南部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的南部烂了。", "explanation": "这里应该用〈南边〉。“南部”指地区，不指西瓜的一侧；西瓜的一侧要说“南边”。"}, {"text": "这道数学题的南部很难。", "explanation": "这里应该用〈难点〉。“南部”指地区的方位部分，不能指题目的一部分；题目里难的地方要说“难点”。"}, {"text": "他的南部很疼，所以去了医院。", "explanation": "这里应该用〈肚子〉。“南部”指地区的南面，不指人身上的部位；腹部疼要说“肚子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香蕉", "is_correct": false, "explanation": "语义：“香蕉”是水果，不能指“……的路”的位置。"}, {"text": "西", "is_correct": false, "explanation": "搭配：单音节方位词“西”作定语要加“边”或“部”，不能说“西的路”。"}, {"text": "南部", "is_correct": true, "explanation": "“南部”指南边的地区，可以修饰“路”，表示那一带的路。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不能作地点修饰语，“手机的路”不通。"}], "explanations": {"香蕉": "语义：“香蕉”是水果，不能指“……的路”的位置。", "西": "搭配：单音节方位词“西”作定语要加“边”或“部”，不能说“西的路”。", "南部": "“南部”指南边的地区，可以修饰“路”，表示那一带的路。", "手机": "语义：“手机”是物品，不能作地点修饰语，“手机的路”不通。"}, "sentence_index": 6, "correct_answer": "南部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的南部破了，我要买一本新的。", "explanation": "这里应该用〈一边〉。“南部”指地区的方位部分，不指物体的一侧；说书的一侧要用“一边”。"}, {"text": "这道菜的南部很辣，大家都喜欢。", "explanation": "这里应该用〈口味〉。“南部”指地区的方位部分，不用于菜；说菜的味道要用“口味”。"}, {"text": "这次比赛的南部很精彩，大家都很兴奋。", "explanation": "这里应该用〈场地〉。“南部”指地区的方位部分，比赛本身没有方位；说比赛的地点要用“场地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次大雨主要南部地区出现。", "corrected_sentence": "这次大雨主要在南部地区出现。", "error_description": "错误：漏了介词“在”。“南部地区”作处所要用“在”引出，应说“主要在南部地区出现”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动在一条南部地区举办。", "corrected_sentence": "这次活动在一个南部地区举办。", "error_description": "错误：量词“条”用于细长的东西，不能修饰地区。应说“一个南部地区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身前往，与“与会”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是会上的活动，与“与会”不是反义词。"}, {"text": "结束", "is_correct": false, "explanation": "结束指事情或会议终止，与“与会”不是反义词。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。", "出发": "出发指动身前往，与“与会”没有反义关系。", "讨论": "讨论是会上的活动，与“与会”不是反义词。", "结束": "结束指事情或会议终止，与“与会”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。"}, {"text": "发言", "is_correct": false, "explanation": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。"}, {"text": "主持", "is_correct": false, "explanation": "主持指掌管会议的进行，与“与会”并不相反。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指出外游览，与“与会”没有反义关系。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（去参加会）相反。", "发言": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。", "主持": "主持指掌管会议的进行，与“与会”并不相反。", "旅行": "旅行指出外游览，与“与会”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "与会是去参加一个会。", "primary_collocate": null, "pronunciation": "yù huì", "ipa": "y˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我明天上午要与会，恐怕无法赴约。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事今天前往北京与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个月都要与会，工作很忙。", "target_word": "与会", "complexity_tier": "T3", "furigana": "yǔ huì", "sentence_source": "generated"}, {"text": "请问您下午是否与会？", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会很重要，大家都要与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我与同事一同与会，乘地铁前往。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有时间与会，请别人去了。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师正在与会，现在不能接电话。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天与会，会议持续了三个小时。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想与会，请你告诉我时间和地方。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与会者", "label": "复合"}, {"form": "与会人员", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词，指某人去参加某一次会，强调人到会场参加", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yǔ huì）指去参加会。"}, {"text": "预会", "is_correct": false, "explanation": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预会指预先召开的会，较少用。"}, {"text": "渔会", "is_correct": false, "explanation": "yú huì 与 yǔ huì 第一个音节声调不同（第二声与第三声），渔会指渔民的团体组织。"}, {"text": "余晖", "is_correct": false, "explanation": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}], "explanations": {"与会": "正确答案。与会（yǔ huì）指去参加会。", "预会": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预会指预先召开的会，较少用。", "渔会": "yú huì 与 yǔ huì 第一个音节声调不同（第二声与第三声），渔会指渔民的团体组织。", "余晖": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会表示去参加会，与“明天上午要……”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与“明天上午要”的安排不符，句子不通。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人不知去向，不能作为明天的安排，句子不通。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，句子不通。"}], "explanations": {"与会": "正确答案。与会表示去参加会，与“明天上午要……”的语境相符。", "出生": "语义：“出生”指人降生，与“明天上午要”的安排不符，句子不通。", "失踪": "语义：“失踪”指人不知去向，不能作为明天的安排，句子不通。", "融化": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，句子不通。"}, "sentence_index": 0, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天在河边与会了。", "explanation": "这里应该用〈散步〉。与会指去参加一个会，沿河走走要用散步。"}, {"text": "他傍晚在篮球场上与会。", "explanation": "这里应该用〈打球〉。与会指去参加一个会，打篮球要用打球。"}, {"text": "我们在教室里与会，听了一节课。", "explanation": "这里应该用〈旁听〉。与会指去参加一个会，听课要用旁听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yǔ huì）指去参加会。"}, {"text": "舞会", "is_correct": false, "explanation": "wǔ huì 与 yǔ huì 声母不同（w 与 y），舞会指跳舞的聚会。"}, {"text": "武会", "is_correct": false, "explanation": "wǔ huì 与 yǔ huì 声母不同，武会指旧时的比武聚会，不指会议。"}, {"text": "预汇", "is_correct": false, "explanation": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预汇指预先汇款，与会议无关。"}], "explanations": {"与会": "正确答案。与会（yǔ huì）指去参加会。", "舞会": "wǔ huì 与 yǔ huì 声母不同（w 与 y），舞会指跳舞的聚会。", "武会": "wǔ huì 与 yǔ huì 声母不同，武会指旧时的比武聚会，不指会议。", "预汇": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预汇指预先汇款，与会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会表示去参加会，与“没有时间……”的语境相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，不是能因“没有时间”而安排的事，句子不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指来得晚，与“请别人去了”的安排说不通。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”是及物动词，需要带宾语（如“购买东西”），这里裸用，句子不完整。"}], "explanations": {"与会": "正确答案。与会表示去参加会，与“没有时间……”的语境相符。", "生病": "语义：“生病”指身体不适，不是能因“没有时间”而安排的事，句子不通。", "迟到": "语义：“迟到”指来得晚，与“请别人去了”的安排说不通。", "购买": "配价：“购买”是及物动词，需要带宾语（如“购买东西”），这里裸用，句子不完整。"}, "sentence_index": 6, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网球比赛中与会。", "explanation": "这里应该用〈参赛〉。与会指去参加一个会，比赛要用参赛。"}, {"text": "他们中午在饭店玩扑克，都与会了。", "explanation": "这里应该用〈玩牌〉。与会指去参加一个会，玩扑克要用玩牌。"}, {"text": "我在项目组中与会。", "explanation": "这里应该用〈参与〉。与会指去参加一个会，参与项目要用参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_va