INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天不与会。", "corrected_sentence": "我昨天没与会。", "error_description": "错误在否定词。叙述过去的事，否定要用“没”，应说“没与会”，不能用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86669, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下周想与会会议，请你提前通知我。", "corrected_sentence": "我下周想与会，请你提前通知我。", "error_description": "错误在“会议”。“与会”已含“参加会”的意思，后面不能再带“会议”作宾语，应说“想与会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺席", "is_correct": true, "explanation": "正确答案。缺席指应当到场却没有到场，与“与会”（参加会议）相反。"}, {"text": "发言", "is_correct": false, "explanation": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。"}, {"text": "出发", "is_correct": false, "explanation": "出发指动身前往，与“与会”没有反义关系。"}, {"text": "结束", "is_correct": false, "explanation": "结束指事情或会议终止，与“与会”不是反义词。"}], "correct_answer": "缺席", "explanations": {"缺席": "正确答案。缺席指应当到场却没有到场，与“与会”（参加会议）相反。", "发言": "发言指在会上讲话，是会议中的一种行为，并不与“与会”构成反义。", "出发": "出发指动身前往，与“与会”没有反义关系。", "结束": "结束指事情或会议终止，与“与会”不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
