INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加会议。", "primary_collocate": null, "pronunciation": "yù huì", "ipa": "y˥˩ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天的会议，王经理将与会。", "target_word": "与会", "complexity_tier": "T3", "furigana": "yǔ huì", "sentence_source": "generated"}, {"text": "我明天要出差，不能与会了。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议有三十多位专家与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您下周三能与会吗？", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们都与会了，会议马上开始。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为生病，没有与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的大部分员工都要与会。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长也来与会，大家都很高兴。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请与会的同事先在门口签名。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想与会，可是时间太晚了。", "target_word": "与会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与会者", "label": "复合"}, {"form": "与会人员", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词，指参加会议，多用于正式场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX