INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yǔ huì）指参加会议。"}, {"text": "预汇", "is_correct": false, "explanation": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预汇指预先汇款，与会议无关。"}, {"text": "渔会", "is_correct": false, "explanation": "yú huì 与 yǔ huì 第一个音节声调不同（第二声与第三声），渔会指渔民的团体组织。"}, {"text": "余晖", "is_correct": false, "explanation": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}], "explanations": {"与会": "正确答案。与会（yǔ huì）指参加会议。", "预汇": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预汇指预先汇款，与会议无关。", "渔会": "yú huì 与 yǔ huì 第一个音节声调不同（第二声与第三声），渔会指渔民的团体组织。", "余晖": "yú huī 与 yǔ huì 两个音节声调都不同，余晖指落日的余光，与会议无关。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会是不及物动词，表示参加会议，可以直接用在句末。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“明天的会议”的安排相反，句子读来不合常理。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，与“明天的会议”无关，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与会议毫不相干，“明天的会议，王经理将结婚”意思不通。"}], "explanations": {"与会": "正确答案。与会是不及物动词，表示参加会议，可以直接用在句末。", "逃跑": "语义：“逃跑”与“明天的会议”的安排相反，句子读来不合常理。", "融化": "语义：“融化”指冰雪遇热变成液体，人不会“融化”，与“明天的会议”无关，句子不通。", "结婚": "语义：“结婚”与会议毫不相干，“明天的会议，王经理将结婚”意思不通。"}, "sentence_index": 0, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天在婚礼上与会了。", "explanation": "这里应该用〈出席〉。与会指参加会议，婚礼这类仪式要用出席。"}, {"text": "我们在这个项目中与会。", "explanation": "这里应该用〈参与〉。与会指参加会议，参与项目要用参与。"}, {"text": "周末我们在游泳池与会。", "explanation": "这里应该用〈游泳〉。与会指参加会议，去泳池要用游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会（yǔ huì）指参加会议。"}, {"text": "舞会", "is_correct": false, "explanation": "wǔ huì 与 yǔ huì 声母不同（w 与 y），舞会指跳舞的聚会。"}, {"text": "武会", "is_correct": false, "explanation": "wǔ huì 与 yǔ huì 声母不同，武会指旧时的比武聚会，不指会议。"}, {"text": "预会", "is_correct": false, "explanation": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预会指预先召开的会，较少用。"}], "explanations": {"与会": "正确答案。与会（yǔ huì）指参加会议。", "舞会": "wǔ huì 与 yǔ huì 声母不同（w 与 y），舞会指跳舞的聚会。", "武会": "wǔ huì 与 yǔ huì 声母不同，武会指旧时的比武聚会，不指会议。", "预会": "yù huì 与 yǔ huì 第一个音节声调不同（第四声与第三声），预会指预先召开的会，较少用。"}, "sentence_index": null, "correct_answer": "与会"}, "level_3": {"options": [{"text": "与会", "is_correct": true, "explanation": "正确答案。与会表示参加会议，与“公司员工都要……”的语境相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与公司员工的工作安排不符，句子不通。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人不知去向，与员工参加会议的要求相矛盾。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”是及物动词，需要带宾语（如“举办活动”），这里裸用，句子不完整。"}], "explanations": {"与会": "正确答案。与会表示参加会议，与“公司员工都要……”的语境相符。", "出生": "语义：“出生”指人降生，与公司员工的工作安排不符，句子不通。", "失踪": "语义：“失踪”指人不知去向，与员工参加会议的要求相矛盾。", "举办": "配价：“举办”是及物动词，需要带宾语（如“举办活动”），这里裸用，句子不完整。"}, "sentence_index": 6, "correct_answer": "与会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在篮球比赛中与会了。", "explanation": "这里应该用〈参赛〉。与会指参加会议，参加比赛要用参赛。"}, {"text": "他上课时在教室里与会。", "explanation": "这里应该用〈旁听〉。与会指参加会议，听课要用旁听。"}, {"text": "同学们晚上在饭店与会。", "explanation": "这里应该用〈聚会〉。与会指参加会议，同学聚餐要用聚会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天要与会会议。", "corrected_sentence": "我明天要与会。", "error_description": "错误在“与会会议”。“与会”本身已含“参加会议”的意思，后面不能再带“会议”作宾语，应说“我明天要与会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天与会过。", "corrected_sentence": "我昨天与会了。", "error_description": "错误在“过”。“过”表示经历，不能与“昨天”这样的具体时间连用，应说“我昨天与会了”，用“了”表示已经发生。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
