INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "重点是最要紧、最要注意的地方。", "primary_collocate": null, "pronunciation": "zhòng diǎn", "ipa": "ʈʂʊŋ˥˩ tjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "今天的重点是第三课。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这一页是重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书时要先找出重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我们先复习重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的重点在后面。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了很多，但我没听懂重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把重点写在本子上。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要有重点，不要太长。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次开会的重点是什么？", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用红笔画出了重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个重点", "label": "量词"}, {"form": "重点学校", "label": "复合"}, {"form": "重點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学习、讲话、文章中最要紧、最需要注意的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86675, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重点", "is_correct": true, "explanation": "正确答案。重点（zhòng diǎn）指最要紧、最要注意的地方。"}, {"text": "中点", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，中点意思是正中间的点。"}, {"text": "整点", "is_correct": false, "explanation": "zhěng（第三声）与 zhòng 韵母不同（eng 与 ong），整点意思是正好在钟点上。"}, {"text": "争点", "is_correct": false, "explanation": "zhēng（第一声）与 zhòng 韵母不同（eng 与 ong），争点意思是争论的焦点。"}, {"text": "站点", "is_correct": false, "explanation": "zhàn 与 zhòng 韵母不同（an 与 ong），站点意思是车站等服务地点。"}, {"text": "重担", "is_correct": false, "explanation": "dàn 与 diǎn 韵母不同（an 与 ian），重担意思是沉重的负担。"}], "explanations": {"重点": "正确答案。重点（zhòng diǎn）指最要紧、最要注意的地方。", "中点": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，中点意思是正中间的点。", "整点": "zhěng（第三声）与 zhòng 韵母不同（eng 与 ong），整点意思是正好在钟点上。", "争点": "zhēng（第一声）与 zhòng 韵母不同（eng 与 ong），争点意思是争论的焦点。", "站点": "zhàn 与 zhòng 韵母不同（an 与 ong），站点意思是车站等服务地点。", "重担": "dàn 与 diǎn 韵母不同（an 与 ian），重担意思是沉重的负担。"}, "sentence_index": null, "correct_answer": "重点"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气是天象，不能作为今天要学的内容。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来指课的内容。"}, {"text": "重点", "is_correct": true, "explanation": "正确。重点指最要紧的内容，与“今天的……是第三课”相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是情绪状态，不能是要学习的课程内容。"}], "explanations": {"天气": "语义：天气是天象，不能作为今天要学的内容。", "身材": "体貌：身材指人的体形，不能用来指课的内容。", "重点": "正确。重点指最要紧的内容，与“今天的……是第三课”相符。", "心情": "语义：心情是情绪状态，不能是要学习的课程内容。"}, "sentence_index": 0, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个不倒翁的重点很低。", "explanation": "这里应该用〈重心〉。重点指最要紧的部分；物体的平衡中心要说重心，不说重点。"}, {"text": "这座山的重点很高。", "explanation": "这里应该用〈高度〉。重点指最要紧的部分，山的高低要说高度，不能说重点。"}, {"text": "这辆车的重点很快。", "explanation": "这里应该用〈速度〉。重点不能表示车的快慢，车速要说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86675, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重点", "is_correct": true, "explanation": "正确答案。重点（zhòng diǎn）指最要紧、最要注意的地方。"}, {"text": "终点", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，终点意思是路线的尽头。"}, {"text": "正点", "is_correct": false, "explanation": "zhèng（第四声）与 zhòng 韵母不同（eng 与 ong），正点意思是按时、准时。"}, {"text": "中弹", "is_correct": false, "explanation": "dàn 与 diǎn 韵母不同（an 与 ian），中弹意思是被子弹击中。"}], "explanations": {"重点": "正确答案。重点（zhòng diǎn）指最要紧、最要注意的地方。", "终点": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，终点意思是路线的尽头。", "正点": "zhèng（第四声）与 zhòng 韵母不同（eng 与 ong），正点意思是按时、准时。", "中弹": "dàn 与 diǎn 韵母不同（an 与 ian），中弹意思是被子弹击中。"}, "sentence_index": null, "correct_answer": "重点"}, "level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不是可以写在本子上的内容。"}, {"text": "重点", "is_correct": true, "explanation": "正确。重点指要紧的内容，可以写在本子上。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时的器具，不能写在本子上。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的神情，不是可以写下来的内容。"}], "explanations": {"钥匙": "语义：钥匙是开锁的工具，不是可以写在本子上的内容。", "重点": "正确。重点指要紧的内容，可以写在本子上。", "闹钟": "语义：闹钟是计时的器具，不能写在本子上。", "脸色": "体貌：脸色指面部的神情，不是可以写下来的内容。"}, "sentence_index": 6, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这个月的重点增加了三公斤。", "explanation": "这里应该用〈体重〉。重点指最要紧的部分，不能用来说人的重量变化。"}, {"text": "他的重点有一米八。", "explanation": "这里应该用〈身高〉。重点不能表示人的高矮。"}, {"text": "他的重点是二十岁。", "explanation": "这里应该用〈年龄〉。重点不能表示人的岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, 