INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了三本重点。", "corrected_sentence": "我找到了三个重点。", "error_description": "「重点」的量词应为「个」。「本」用于书籍等，不能用来数「重点」。正确说法：我找到了三个重点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找到了一颗重点。", "corrected_sentence": "我找到了一个重点。", "error_description": "「重点」的量词应为「个」。「颗」用于圆粒状的东西，不能用来数「重点」。正确说法：我找到了一个重点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
