INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物中最主要、最关键的部分；特别着重的地方。", "primary_collocate": null, "pronunciation": "zhòng diǎn", "ipa": "ʈʂʊŋ˥˩ tjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "学校今年的工作重点是安全。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把市场当作工作的重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一课的教学重点是汉字的写法。", "target_word": "重点", "complexity_tier": "T3", "furigana": "zhè yí kè de jiào xué zhòng diǎn shì hàn zì de xiě fǎ", "sentence_source": "generated"}, {"text": "我们的重点是帮助老人。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题是整个计划的重点。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的演讲重点是新产品的优点。", "target_word": "重点", "complexity_tier": "T3", "furigana": "tā de yǎn jiǎng zhòng diǎn shì xīn chǎn pǐn de yōu diǎn", "sentence_source": "generated"}, {"text": "老师今天的讲课重点是语法。", "target_word": "重点", "complexity_tier": "T3", "furigana": "lǎo shī jīn tiān de jiǎng kè zhòng diǎn shì yǔ fǎ", "sentence_source": "generated"}, {"text": "这本书的重点是介绍中国历史。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的研究重点是中文教育。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书的重点，要用大字写出来。", "target_word": "重点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个重点", "label": "量词"}, {"form": "重点学校", "label": "复合"}, {"form": "重點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作、计划、研究中最主要、最关键、特别着重的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3410f726-dd8b-4348-a976-24df9c72ab9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86676, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重点", "is_correct": true, "explanation": "正确答案。重点（zhòng diǎn）指事物中最主要、最关键的部分。"}, {"text": "中点", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，中点意思是正中间的点。"}, {"text": "整点", "is_correct": false, "explanation": "zhěng（第三声）与 zhòng 韵母不同（eng 与 ong），整点意思是正好在钟点上。"}, {"text": "争点", "is_correct": false, "explanation": "zhēng（第一声）与 zhòng 韵母不同（eng 与 ong），争点意思是争论的焦点。"}, {"text": "站点", "is_correct": false, "explanation": "zhàn 与 zhòng 韵母不同（an 与 ong），站点意思是车站等服务地点。"}, {"text": "重担", "is_correct": false, "explanation": "dàn 与 diǎn 韵母不同（an 与 ian），重担意思是沉重的负担。"}], "explanations": {"重点": "正确答案。重点（zhòng diǎn）指事物中最主要、最关键的部分。", "中点": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，中点意思是正中间的点。", "整点": "zhěng（第三声）与 zhòng 韵母不同（eng 与 ong），整点意思是正好在钟点上。", "争点": "zhēng（第一声）与 zhòng 韵母不同（eng 与 ong），争点意思是争论的焦点。", "站点": "zhàn 与 zhòng 韵母不同（an 与 ong），站点意思是车站等服务地点。", "重担": "dàn 与 diǎn 韵母不同（an 与 ian），重担意思是沉重的负担。"}, "sentence_index": null, "correct_answer": "重点"}, "level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来指工作的内容。"}, {"text": "重点", "is_correct": true, "explanation": "正确。重点指工作中最主要的部分，与“学校今年的工作……是安全”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天象，不能作为工作的重点。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是个人的情绪，不能指学校工作的重点。"}], "explanations": {"身材": "体貌：身材指人的体形，不能用来指工作的内容。", "重点": "正确。重点指工作中最主要的部分，与“学校今年的工作……是安全”相符。", "天气": "语义：天气是天象，不能作为工作的重点。", "心情": "语义：心情是个人的情绪，不能指学校工作的重点。"}, "sentence_index": 0, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆卡车的重点很低。", "explanation": "这里应该用〈重心〉。重点指最要紧的部分；车辆的平衡中心要说重心。"}, {"text": "这块石头的重点很硬。", "explanation": "这里应该用〈硬度〉。重点指最要紧的部分，物体的软硬要说硬度。"}, {"text": "这座桥的重点很坚固。", "explanation": "这里应该说〈坚固〉。重点指最要紧的部分，不能用来描述建筑结实的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86676, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "重点", "is_correct": true, "explanation": "正确答案。重点（zhòng diǎn）指事物中最主要、最关键的部分。"}, {"text": "终点", "is_correct": false, "explanation": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，终点意思是路线的尽头。"}, {"text": "正点", "is_correct": false, "explanation": "zhèng（第四声）与 zhòng 韵母不同（eng 与 ong），正点意思是按时、准时。"}, {"text": "中弹", "is_correct": false, "explanation": "dàn 与 diǎn 韵母不同（an 与 ian），中弹意思是被子弹击中。"}], "explanations": {"重点": "正确答案。重点（zhòng diǎn）指事物中最主要、最关键的部分。", "终点": "声调不同：zhōng（第一声）与 zhòng（第四声）不同，终点意思是路线的尽头。", "正点": "zhèng（第四声）与 zhòng 韵母不同（eng 与 ong），正点意思是按时、准时。", "中弹": "dàn 与 diǎn 韵母不同（an 与 ian），中弹意思是被子弹击中。"}, "sentence_index": null, "correct_answer": "重点"}, "level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不是讲课的内容。"}, {"text": "重点", "is_correct": true, "explanation": "正确。重点指讲课中最主要的内容，与“老师今天的讲课……是语法”相符。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时的器具，不能作为讲课的内容。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色指面部的神情，不能指讲课的内容。"}], "explanations": {"钥匙": "语义：钥匙是开锁的工具，不是讲课的内容。", "重点": "正确。重点指讲课中最主要的内容，与“老师今天的讲课……是语法”相符。", "闹钟": "语义：闹钟是计时的器具，不能作为讲课的内容。", "脸色": "体貌：脸色指面部的神情，不能指讲课的内容。"}, "sentence_index": 6, "correct_answer": "重点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的重点是十公斤。", "explanation": "这里应该用〈重量〉。重点指最要紧的部分，不能用来说物体的分量。"}, {"text": "她的重点是一米六。", "explanation": "这里应该用〈身高〉。重点不能表示人的身高。"}, {"text": "这个词的重点是三个字。", "explanation": "这里应该用〈字数〉。重点指最要紧的部分，词有几个字要说字数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校的一座重点是安全教育。", "corrected_sentence": "学校的一个重点是安全教育。", "error_description": "「重点」的量词应为「个」。「座」用于山、房屋等大型固定的东西，不能用来数「重点」。正确说法：学校的一个重点是安全教育。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告有两条重点。", "corrected_sentence": "这份报告有两个重点。", "error_description": "「重点」的量词应为「个」。「条」用于细长的东西，不能用来数「重点」。正确说法：这份报告有两个重点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fec978a-81e6-4ea1-a989-64a4071cd0d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
