INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86677, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "咱们是我和你们，我们大家一起。", "primary_collocate": null, "pronunciation": "zán men", "ipa": "tsan˧˥ mən", "syllable_count": 2, "sentences": [{"text": "咱们一起去公园玩吧。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，咱们回家吧。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们今天吃什么？", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们都是好朋友。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天咱们早点儿出发。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事咱们一起想办法。", "target_word": "咱们", "complexity_tier": "T3", "furigana": "zhè jiàn shì zán men yì qǐ xiǎng bàn fǎ.", "sentence_source": "generated"}, {"text": "咱们班的同学都很热情。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别客气，咱们都是一家人。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们把房间打扫一下吧。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们先坐下来，慢慢聊。", "target_word": "咱们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咱", "label": "单数"}, {"form": "咱们俩", "label": "复合"}, {"form": "咱們", "label": "繁体"}], "register": "口语", "sense_fingerprint": "包括听话人在内的“我们”，大家一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b82dac-691c-4a8d-92f2-df09b4bddc7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86677, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "我", "is_correct": false, "explanation": "语义：「我」只指说话人一人，而「一起去公园玩吧」要求多人共同行动，「吧」的提议也包括听话人，「我」不包括听话人。"}, {"text": "咱们", "is_correct": true, "explanation": "正确。「咱们」包括说话人和听话人，「一起去公园玩吧」是对听话人的提议。"}, {"text": "他", "is_correct": false, "explanation": "语义：「他」指第三人称，不包括说话人和听话人，而「吧」的提议对象是听话人，与「他」不符。"}, {"text": "她", "is_correct": false, "explanation": "语义：「她」指第三人称单数，不包括说话人和听话人，与「吧」所含的提议对象不符。"}], "explanations": {"我": "语义：「我」只指说话人一人，而「一起去公园玩吧」要求多人共同行动，「吧」的提议也包括听话人，「我」不包括听话人。", "咱们": "正确。「咱们」包括说话人和听话人，「一起去公园玩吧」是对听话人的提议。", "他": "语义：「他」指第三人称，不包括说话人和听话人，而「吧」的提议对象是听话人，与「他」不符。", "她": "语义：「她」指第三人称单数，不包括说话人和听话人，与「吧」所含的提议对象不符。"}, "sentence_index": 0, "correct_answer": "咱们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你在家休息，咱们去超市买菜吧。", "explanation": "「咱们」包括听话人，这里却让听话人留在家里，前后矛盾。这种情况应改用「我们」。"}, {"text": "咱们一个人住在这里，很安静。", "explanation": "「咱们」指包括说话人和听话人在内的群体，不能只指说话人一人。这里只有说话人一人，应改用「我」。"}, {"text": "咱们都是学生，你是老师。", "explanation": "「咱们」包括听话人，这里听话人是老师、不是学生，应改用「我们」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86677, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "你们", "is_correct": false, "explanation": "语义：「你们」只指听话人一方，不包括说话人，与「咱们班」的包括关系不符。"}, {"text": "咱们", "is_correct": true, "explanation": "正确。「咱们班」指说话人和听话人所在的班级，「同学都很热情」与之相符。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：「大家」泛指全体，不能直接作「班」的定语，「大家班的同学」说法不成立。"}, {"text": "他们", "is_correct": false, "explanation": "语义：「他们」指第三方，不包括说话人和听话人，与「咱们班」不符。"}], "explanations": {"你们": "语义：「你们」只指听话人一方，不包括说话人，与「咱们班」的包括关系不符。", "咱们": "正确。「咱们班」指说话人和听话人所在的班级，「同学都很热情」与之相符。", "大家": "搭配：「大家」泛指全体，不能直接作「班」的定语，「大家班的同学」说法不成立。", "他们": "语义：「他们」指第三方，不包括说话人和听话人，与「咱们班」不符。"}, "sentence_index": 6, "correct_answer": "咱们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶，咱们俩昨天去买菜了，您没去吧？", "explanation": "「咱们俩」包括听话人奶奶，句中又说她没去，前后矛盾，应改用「我们俩」。"}, {"text": "我和小红昨天去超市了，你没去，咱们买了很多水果。", "explanation": "「咱们」包括听话人，句中说听话人没去超市，应改用「我们」。"}, {"text": "王经理，咱们请您先坐。", "explanation": "「咱们」把听话人算在内，「请您先坐」又把听话人当作被邀请的对象，二者冲突，应改用「我们」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86677, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咱们们一起研究一下这个方案吧。", "corrected_sentence": "咱们一起研究一下这个方案吧。", "error_description": "错误在「们」：「咱们」本身已表示复数，不能再加「们」。正确形式是「咱们」，应说「咱们一起研究一下这个方案吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86677, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咱们们三个都喜欢这部电影。", "corrected_sentence": "咱们三个都喜欢这部电影。", "error_description": "重复：「咱们」本身已表示复数，后面不能再加「们」；应说「咱们三个都喜欢这部电影」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
