INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "另外是除了说过的以外，还有别的。", "primary_collocate": null, "pronunciation": "lìng wài", "ipa": "lɪŋ˥˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这本书我看完了，另外一本还没看。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有两个朋友，一个是老师，另外一个是医生。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法不好，我们想想另外的办法。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天不在，请你另外找时间来。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路太远，我们走另外一条吧。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢红色，她喜欢另外的颜色。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三杯水，两杯是我的，另外一杯是你的。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很难，你问另外一位老师吧。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一部分学生去了公园，另外的学生留在教室。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换一个房间，另外那个房间更大。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指示代词，指已说的人或事物之外的其他的，常放在名词或数量词前，如“另外一个”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：指已说之外的另一本，与“一本”搭配，句意通顺。"}, {"text": "这个", "is_correct": false, "explanation": "搭配：“这个”与“一本”的量词不能同时出现，应说“这一本”。"}, {"text": "那个", "is_correct": false, "explanation": "搭配：“那个”的量词是“个”，不能直接接“一本”。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人，不能指书，与“一本”不合。"}], "explanations": {"另外": "另外：指已说之外的另一本，与“一本”搭配，句意通顺。", "这个": "搭配：“这个”与“一本”的量词不能同时出现，应说“这一本”。", "那个": "搭配：“那个”的量词是“个”，不能直接接“一本”。", "大家": "语义：“大家”指人，不能指书，与“一本”不合。"}, "sentence_index": 0, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个办法不好，我们想想这个另外的办法。", "explanation": "这里应该用〈其他的〉。“这个”指已说的办法，“另外”指其之外的，二者矛盾。"}, {"text": "这是唯一的办法，另外还有别的办法。", "explanation": "这里的“另外”表示已说范围之外还有别的，与“唯一的办法”的限定矛盾，不能用此义。"}, {"text": "这些书全都是我的，另外那一本是你的。", "explanation": "这里的“另外”指已说范围之外还有别的，与“全都是我的”自相矛盾，不能用此义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：指已说之外的另一杯，与“两杯”形成对比，句意通顺。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”表示疑问或不定指人，不能指“一杯水”。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指人，不能与数量词“一杯”直接组合。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个”后不接“一杯”，应说“每一杯”。"}], "explanations": {"另外": "另外：指已说之外的另一杯，与“两杯”形成对比，句意通顺。", "谁": "语义：“谁”表示疑问或不定指人，不能指“一杯水”。", "自己": "搭配：“自己”指人，不能与数量词“一杯”直接组合。", "每个": "搭配：“每个”后不接“一杯”，应说“每一杯”。"}, "sentence_index": 6, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我只住这一个房间，另外那个房间更大。", "explanation": "这里的“另外”指已说范围之外还有别的，与“只住这一个房间”的限定矛盾，不能用此义。"}, {"text": "所有房间都很小，另外那个房间更大。", "explanation": "这里的“另外”表示范围之外还有别的，但“所有房间都很小”已把那个房间包括在内，二者矛盾。"}, {"text": "我没有别的房间，另外那个房间更大。", "explanation": "这里的“另外”表示范围之外还有别的，与“没有别的房间”自相矛盾，不能用此义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了两本书，另外了一本是送给朋友的。", "corrected_sentence": "我买了两本书，另外一本是送给朋友的。", "error_description": "误加“了”：“另外”修饰“一本”时不能带“了”，应说“另外一本”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有三把伞，另外把是你的。", "corrected_sentence": "我有三把伞，另外一把是你的。", "error_description": "数量词缺失：“另外”后要接数量短语“一把”，应说“另外一把”，不能只说“另外把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
