INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在已说的范围之外，还有其他的。", "primary_collocate": null, "pronunciation": "lìng wài", "ipa": "lɪŋ˥˩ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我买了苹果，另外还买了一些香蕉。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说汉语，另外也会说日语。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天要做作业，另外还要复习课文。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖衣服，另外也卖鞋子。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我一本书，另外还给了我一支笔。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天我要上课，另外还要去医院。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天跑步，另外还游泳。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议在三点开始，另外请大家带着电脑。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去北京，另外也想去上海看看。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间不大，另外价格也有点儿高。", "target_word": "另外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在动词前或句首，表示在前面所说的事之外再补充别的事，常与“还”“也”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：表示在已说之外再补充，与“还”连用，句意通顺。"}, {"text": "很", "is_correct": false, "explanation": "搭配：程度副词“很”不能与“还买”组合，句意不通。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：程度副词“非常”不能修饰“还买”，句意不通。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限制，与“还买”的补充义矛盾。"}], "explanations": {"另外": "另外：表示在已说之外再补充，与“还”连用，句意通顺。", "很": "搭配：程度副词“很”不能与“还买”组合，句意不通。", "非常": "搭配：程度副词“非常”不能修饰“还买”，句意不通。", "只": "语义：“只”表示限制，与“还买”的补充义矛盾。"}, "sentence_index": 0, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店只卖衣服，另外也卖鞋子。", "explanation": "这里的“另外”指已说范围之外还有别的，与“只卖衣服”的限定矛盾，不能用此义。"}, {"text": "这家店从来不卖鞋子，另外也卖鞋子。", "explanation": "这里的“另外”表示范围之外还有别的，但“从来不卖鞋子”已否定了这一点，二者矛盾。"}, {"text": "这家店卖所有的商品，另外也卖鞋子。", "explanation": "这里的“另外”指已说范围之外还有别的，但“卖所有的商品”已把鞋子包括在内，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另外", "is_correct": true, "explanation": "另外：表示在已说之外再补充，与“还”连用，句意通顺。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：程度副词“比较”不能与“还游泳”组合，句意不通。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：程度副词“十分”不能修饰“还游泳”，句意不通。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示出乎意料，与“每天跑步”的习惯性句意不合。"}], "explanations": {"另外": "另外：表示在已说之外再补充，与“还”连用，句意通顺。", "比较": "搭配：程度副词“比较”不能与“还游泳”组合，句意不通。", "十分": "搭配：程度副词“十分”不能修饰“还游泳”，句意不通。", "突然": "语义：“突然”表示出乎意料，与“每天跑步”的习惯性句意不合。"}, "sentence_index": 6, "correct_answer": "另外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间房间唯一的床很大，另外还有两张床。", "explanation": "这里的“另外”指已说范围之外还有别的，与“唯一的床”的限定矛盾，不能用此义。"}, {"text": "房间不大，价格也低，另外也很高。", "explanation": "这里的“另外”表示补充，与前句“价格也低”形成矛盾，不能用来说明价格很高。"}, {"text": "房间不大，所有的费用都已经算清了，另外也有点儿高。", "explanation": "这里的“另外”表示范围之外还有别的，但“所有的费用都已经算清了”已把全部费用纳入，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他会打篮球，另外了也会游泳。", "corrected_sentence": "他会打篮球，另外也会游泳。", "error_description": "误加“了”：副词“另外”后不能加“了”，应说“另外也会游泳”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去了北京，很另外也去了上海。", "corrected_sentence": "我们去了北京，另外也去了上海。", "error_description": "修饰误用：副词“另外”不能被“很”修饰，“很”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
