INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86685, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "座是数大山、大房子这些大而稳的东西的词。", "primary_collocate": null, "pronunciation": "zuò", "ipa": "tsuo˥˩", "syllable_count": 1, "sentences": [{"text": "远处有一座大山。", "target_word": "座", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那座山很高。", "target_word": "座", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想在海边买一座大房子。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座房子很老，但是很漂亮。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们家住在山上的一座旧房子里。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们爬了一座很高的山，累极了。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外有一座山，山上全是绿色的树。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座大山是当地人最喜欢的地方。", "target_word": "座", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座山下面有一个小村子，村里的人都很热情。", "target_word": "座", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在山脚下盖了一座大房子，准备住在那里。", "target_word": "座", "complexity_tier": "T3", "furigana": "lǎo rén zài shān jiǎo xià gài le yí zuò dà fáng zi, zhǔn bèi zhù zài nà lǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "座座", "label": "重叠"}], "register": "中性", "sense_fingerprint": "量词：用于大山、大房子等大而稳的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b82dac-691c-4a8d-92f2-df09b4bddc7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86685, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "座", "is_correct": true, "explanation": "正确。读音 zuò（第四声），意思是用于大山、大房子等大而稳的东西的量词。"}, {"text": "错", "is_correct": false, "explanation": "cuò 与 zuò 声母不同（c 与 z），声调相同，意思是错误。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。"}, {"text": "醉", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是喝得神志不清。"}], "explanations": {"座": "正确。读音 zuò（第四声），意思是用于大山、大房子等大而稳的东西的量词。", "错": "cuò 与 zuò 声母不同（c 与 z），声调相同，意思是错误。", "左": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。", "醉": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是喝得神志不清。"}, "sentence_index": null, "correct_answer": "座"}, "level_3": {"options": [{"text": "幅", "is_correct": false, "explanation": "语义：「幅」用于画或布帛，「一幅大山」指的是画，不是真实的山。"}, {"text": "座", "is_correct": true, "explanation": "正确。「座」用于大山、大房子等大而稳的东西。"}, {"text": "所", "is_correct": false, "explanation": "语义：「所」用于学校、医院等机构，大山不是机构，「一所大山」不成立。"}, {"text": "只", "is_correct": false, "explanation": "搭配：「只」用于动物等，大山不能用「只」计量。"}], "explanations": {"幅": "语义：「幅」用于画或布帛，「一幅大山」指的是画，不是真实的山。", "座": "正确。「座」用于大山、大房子等大而稳的东西。", "所": "语义：「所」用于学校、医院等机构，大山不是机构，「一所大山」不成立。", "只": "搭配：「只」用于动物等，大山不能用「只」计量。"}, "sentence_index": 0, "correct_answer": "座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小猫很可爱。", "explanation": "「座」用于大而稳的物体，猫是动物，应用「只」计量，这里不能用「座」。"}, {"text": "我买了一座新手表。", "explanation": "「座」用于大而稳的物体，手表应用「块」或「只」计量，这里不能用「座」。"}, {"text": "车站门口停着一座小汽车。", "explanation": "「座」用于大而稳的物体，汽车应用「辆」计量，这里不能用「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86685, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "座", "is_correct": true, "explanation": "正确。读音 zuò（第四声），意思是用于大山、大房子等大而稳的东西的量词。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是最。"}, {"text": "昨", "is_correct": false, "explanation": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。"}, {"text": "所", "is_correct": false, "explanation": "suǒ（第三声）与 zuò（第四声）声母不同（s 与 z）且声调不同，意思是处所或机构的量词。"}], "explanations": {"座": "正确。读音 zuò（第四声），意思是用于大山、大房子等大而稳的东西的量词。", "最": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是最。", "昨": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。", "所": "suǒ（第三声）与 zuò（第四声）声母不同（s 与 z）且声调不同，意思是处所或机构的量词。"}, "sentence_index": null, "correct_answer": "座"}, "level_3": {"options": [{"text": "条", "is_correct": false, "explanation": "搭配：「条」用于细长的东西，山不能用「条」计量。"}, {"text": "座", "is_correct": true, "explanation": "正确。「座」用于大山等大而稳的东西。"}, {"text": "间", "is_correct": false, "explanation": "语义：「间」用于房屋、房间，山不是房间，「一间山」不成立。"}, {"text": "位", "is_correct": false, "explanation": "搭配：「位」用于人，山不能用「位」计量。"}], "explanations": {"条": "搭配：「条」用于细长的东西，山不能用「条」计量。", "座": "正确。「座」用于大山等大而稳的东西。", "间": "语义：「间」用于房屋、房间，山不是房间，「一间山」不成立。", "位": "搭配：「位」用于人，山不能用「位」计量。"}, "sentence_index": 6, "correct_answer": "座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人在山脚下种了一座小花。", "explanation": "「座」用于大而稳的物体，花应用「朵」计量，这里不能用「座」。"}, {"text": "老人在山脚下养了一座小鸡。", "explanation": "「座」不能用于小动物，鸡应用「只」计量，这里不能用「座」。"}, {"text": "老人在山脚下买了一座新衣服。", "explanation": "「座」不能计量衣服，衣服应用「件」计量，这里不能用「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "远处有一座雄伟的大海。", "corrected_sentence": "远处有一片雄伟的大海。", "error_description": "量词错误：大海应用「片」计量，「座」用于大山、大房子等大而稳的东西，不能用来计量大海。正确句是「远处有一片雄伟的大海」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86685, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村子后面有一座小河。", "corrected_sentence": "村子后面有一条小河。", "error_description": "量词错误：河应用「条」计量，「座」用于大而稳的东西，不能用来计量河。正确句是「村子后面有一条小河」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
