INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86686, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "座", "is_correct": true, "explanation": "正确。读音 zuò（第四声），意思是用于桥、楼、塔等较大或固定物体的量词。"}, {"text": "昨", "is_correct": false, "explanation": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。"}, {"text": "醉", "is_correct": false, "explanation": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是喝得神志不清。"}, {"text": "所", "is_correct": false, "explanation": "suǒ（第三声）与 zuò（第四声）声母不同（s 与 z）且声调不同，意思是处所或机构的量词。"}], "explanations": {"座": "正确。读音 zuò（第四声），意思是用于桥、楼、塔等较大或固定物体的量词。", "昨": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。", "醉": "zuì 与 zuò 韵母不同（-ì 与 -ò），意思是喝得神志不清。", "所": "suǒ（第三声）与 zuò（第四声）声母不同（s 与 z）且声调不同，意思是处所或机构的量词。"}, "sentence_index": null, "correct_answer": "座"}, "level_3": {"options": [{"text": "张", "is_correct": false, "explanation": "搭配：「张」用于桌子、纸等平面的东西，小庙不用「张」计量。"}, {"text": "座", "is_correct": true, "explanation": "正确。「座」用于庙、桥、楼、塔等较大或固定的物体。"}, {"text": "块", "is_correct": false, "explanation": "搭配：「块」用于块状或片状的东西，「小庙」不能用「块」计量。"}, {"text": "位", "is_correct": false, "explanation": "搭配：「位」用于人，小庙不能用「位」计量。"}], "explanations": {"张": "搭配：「张」用于桌子、纸等平面的东西，小庙不用「张」计量。", "座": "正确。「座」用于庙、桥、楼、塔等较大或固定的物体。", "块": "搭配：「块」用于块状或片状的东西，「小庙」不能用「块」计量。", "位": "搭配：「位」用于人，小庙不能用「位」计量。"}, "sentence_index": 6, "correct_answer": "座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一座小书包。", "explanation": "「座」用于较大或固定的物体，书包应用「个」计量，这里不能用「座」。"}, {"text": "桌上放着一座小手机。", "explanation": "「座」用于较大或固定的物体，手机应用「部」计量，这里不能用「座」。"}, {"text": "他送了我一座小花。", "explanation": "「座」不能计量花，花应用「朵」计量，这里不能用「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
