INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86700, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于文章、纸张等。", "primary_collocate": null, "pronunciation": "piān", "ipa": "pʰjɛn˥", "syllable_count": 1, "sentences": [{"text": "我昨天写了一篇作文。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们读了一篇短文。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章有一千个字。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看一篇报道。", "target_word": "篇", "complexity_tier": "T3", "furigana": "tā měi tiān kàn yī piān bào dào.", "sentence_source": "generated"}, {"text": "桌子上有一篇旧文章。", "target_word": "篇", "complexity_tier": "T3", "furigana": "zhuō zi shàng yǒu yī piān jiù wén zhāng.", "sentence_source": "generated"}, {"text": "请你把这篇课文再读一遍。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想写一篇关于家乡的文章。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一篇很有意思的散文。", "target_word": "篇", "complexity_tier": "T3", "furigana": "zhè shì yī piān hěn yǒu yì si de sǎn wén.", "sentence_source": "generated"}, {"text": "他在本子上写了一篇日记。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月她写了两篇文章。", "target_word": "篇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "篇章", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词，数文章、纸张等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "篇", "is_correct": true, "explanation": "piān（第一声）是篇，数文章、纸张的量词。"}, {"text": "片", "is_correct": false, "explanation": "piàn（第四声）与 piān（第一声）声调不同，意思是片（薄片）。"}, {"text": "骗", "is_correct": false, "explanation": "piàn（第四声）与 piān（第一声）声调不同，意思是骗（欺骗）。"}, {"text": "拼", "is_correct": false, "explanation": "pīn 与 piān 的韵母 in 与 an 不同，意思是拼（拼合）。"}, {"text": "天", "is_correct": false, "explanation": "tiān 与 piān 的声母不同（t 与 p），意思是天。"}, {"text": "千", "is_correct": false, "explanation": "qiān 与 piān 的声母不同（q 与 p），意思是千。"}], "explanations": {"篇": "piān（第一声）是篇，数文章、纸张的量词。", "片": "piàn（第四声）与 piān（第一声）声调不同，意思是片（薄片）。", "骗": "piàn（第四声）与 piān（第一声）声调不同，意思是骗（欺骗）。", "拼": "pīn 与 piān 的韵母 in 与 an 不同，意思是拼（拼合）。", "天": "tiān 与 piān 的声母不同（t 与 p），意思是天。", "千": "qiān 与 piān 的声母不同（q 与 p），意思是千。"}, "sentence_index": null, "correct_answer": "篇"}, "level_3": {"options": [{"text": "篇", "is_correct": true, "explanation": "与语境相符：“一篇作文”是完整的一篇文章。"}, {"text": "首", "is_correct": false, "explanation": "语义：“首”用于诗词、歌曲，不能数作文。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画作、字画，不能数作文。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、建筑等大型固定物，不能与作文搭配。"}], "explanations": {"篇": "与语境相符：“一篇作文”是完整的一篇文章。", "首": "语义：“首”用于诗词、歌曲，不能数作文。", "幅": "语义：“幅”用于画作、字画，不能数作文。", "座": "搭配：“座”用于山、桥、建筑等大型固定物，不能与作文搭配。"}, "sentence_index": 0, "correct_answer": "篇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一篇小狗。", "explanation": "这里应该用〈只〉。小狗是动物，量词用只；篇只用于文章、纸张。"}, {"text": "她买了一篇书。", "explanation": "这里应该用〈本〉。书用本，篇不能用来数书。"}, {"text": "我给妈妈买了一篇裙子。", "explanation": "这里应该用〈条〉。裙子用条或件，不用篇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "篇", "is_correct": true, "explanation": "piān（第一声）是篇，数文章、纸张的量词。"}, {"text": "边", "is_correct": false, "explanation": "biān 与 piān 的声母不同（b 与 p），意思是边（边缘）。"}, {"text": "先", "is_correct": false, "explanation": "xiān 与 piān 的声母不同（x 与 p），意思是先（先后）。"}, {"text": "间", "is_correct": false, "explanation": "jiān 与 piān 的声母不同（j 与 p），意思是间（房间）。"}], "explanations": {"篇": "piān（第一声）是篇，数文章、纸张的量词。", "边": "biān 与 piān 的声母不同（b 与 p），意思是边（边缘）。", "先": "xiān 与 piān 的声母不同（x 与 p），意思是先（先后）。", "间": "jiān 与 piān 的声母不同（j 与 p），意思是间（房间）。"}, "sentence_index": null, "correct_answer": "篇"}, "level_3": {"options": [{"text": "篇", "is_correct": true, "explanation": "与语境相符：“一篇关于家乡的文章”是完整的一篇文章。"}, {"text": "支", "is_correct": false, "explanation": "语义：“支”用于歌曲、笔、队伍等，不能数文章。"}, {"text": "场", "is_correct": false, "explanation": "搭配：“场”用于比赛、演出、雨等事件，不能数文章。"}, {"text": "串", "is_correct": false, "explanation": "搭配：“串”用于成串的东西，不能与“关于家乡的文章”搭配。"}], "explanations": {"篇": "与语境相符：“一篇关于家乡的文章”是完整的一篇文章。", "支": "语义：“支”用于歌曲、笔、队伍等，不能数文章。", "场": "搭配：“场”用于比赛、演出、雨等事件，不能数文章。", "串": "搭配：“串”用于成串的东西，不能与“关于家乡的文章”搭配。"}, "sentence_index": 6, "correct_answer": "篇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她家买了一篇桌子。", "explanation": "这里应该用〈张〉。桌子用张，篇不能用来数桌子。"}, {"text": "她唱了一篇歌。", "explanation": "这里应该用〈首〉。歌曲用首，这里不能用篇。"}, {"text": "河边停着一篇船。", "explanation": "这里应该用〈艘〉。船用艘或只，篇不能数船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
