INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上个月写了两篇的报道。", "corrected_sentence": "她上个月写了两篇报道。", "error_description": "错误形式：两篇的报道；正确形式：两篇报道。数量短语“两篇”直接修饰名词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86707, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断", "is_correct": true, "explanation": "“断”指断开、不再相连，与“通到”相对。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”与“通到”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”与“通到”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“通到”没有反义关系。"}], "correct_answer": "断", "explanations": {"断": "“断”指断开、不再相连，与“通到”相对。", "跳": "“跳”与“通到”没有反义关系。", "睡": "“睡”与“通到”没有反义关系。", "写": "“写”与“通到”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
