INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86719, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "足球是一种圆圆的球，用脚来踢。", "primary_collocate": null, "pronunciation": "zú qiú", "ipa": "tsu˧˥ tɕʰiu˧˥", "syllable_count": 2, "sentences": [{"text": "他送给我一个新足球。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个足球是圆的，很轻。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的足球破了一个洞。", "target_word": "足球", "complexity_tier": "T3", "furigana": "zú qiú", "sentence_source": "generated"}, {"text": "足球在桌子下面，你去拿一下。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的足球没有气了，要打气。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们抱着足球跑进了公园。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有红色的足球，也有蓝色的。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把足球放在了书包旁边。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个足球太旧了，我想买新的。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把足球踢到了树后面。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "足球队", "label": "复合"}, {"form": "足球赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指踢足球用的那个圆球本身，是具体的物品，量词用“个”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足球", "is_correct": true, "explanation": "正确答案。足球是可以送人的物品，“一个新足球”搭配自然。"}, {"text": "宾馆", "is_correct": false, "explanation": "语义：“宾馆”是住宿的地方，不能当作礼物送人，句子意思不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“送”的对象一般是物品，“天气”不能送，也不说“一个新天气”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是一种疾病，不是可以送给别人的东西，句子意思不通。"}], "explanations": {"足球": "正确答案。足球是可以送人的物品，“一个新足球”搭配自然。", "宾馆": "语义：“宾馆”是住宿的地方，不能当作礼物送人，句子意思不通。", "天气": "搭配：“送”的对象一般是物品，“天气”不能送，也不说“一个新天气”。", "感冒": "语义：“感冒”是一种疾病，不是可以送给别人的东西，句子意思不通。"}, "sentence_index": 0, "correct_answer": "足球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一根足球，很便宜。", "explanation": "这里应该用〈个〉。足球是球，量词用“个”，“根”多用于细长的东西。"}, {"text": "这本足球很新，我想买。", "explanation": "这里应该用〈个〉。足球是球，量词用“个”，“本”用于书和本子。"}, {"text": "他送了我一把足球。", "explanation": "这里应该用〈个〉。足球是球，量词用“个”，“把”多用于有柄的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": true, "explanation": "正确答案。商店里可以有红色、蓝色的足球，“红色的……，也有蓝色的”搭配自然。"}, {"text": "天空", "is_correct": false, "explanation": "语义：商店里不会有“红色的天空”，句子意思不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“红色的”修饰颜色明确的东西，不能修饰“声音”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：商店里不会陈列“红色的眼睛”，句子不合常理。"}], "explanations": {"足球": "正确答案。商店里可以有红色、蓝色的足球，“红色的……，也有蓝色的”搭配自然。", "天空": "语义：商店里不会有“红色的天空”，句子意思不通。", "声音": "搭配：“红色的”修饰颜色明确的东西，不能修饰“声音”。", "眼睛": "语义：商店里不会陈列“红色的眼睛”，句子不合常理。"}, "sentence_index": 6, "correct_answer": "足球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸在店里挑了一辆足球。", "explanation": "这里应该用〈个〉。足球是球，量词用“个”，“辆”只用于车。"}, {"text": "我在商店里看见一条足球。", "explanation": "这里应该用〈个〉。足球是球，量词用“个”，“条”多用于细长的东西。"}, {"text": "弟弟在桌上放了一张足球。", "explanation": "这里应该用〈个〉。足球是球，量词用“个”，“张”用于平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书包里有一块新足球。", "corrected_sentence": "书包里有一个新足球。", "error_description": "错误在量词。“足球”是球，量词用“个”，“块”用于块状的东西，应说“一个新足球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把足球吃了下去。", "corrected_sentence": "他把足球踢了下去。", "error_description": "搭配错误：“吃”不能用于足球，应说“踢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
