INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "球类运动项目，两队用脚踢球，把球踢进对方的球门。", "primary_collocate": null, "pronunciation": "zú qiú", "ipa": "tsu˧˥ tɕʰiu˧˥", "syllable_count": 2, "sentences": [{"text": "我很喜欢足球，每个周末都看比赛。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱踢足球。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球比赛有两个队，每队十一个人。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的足球队今天晚上有比赛。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥是学校足球队的队员。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球是世界上很受欢迎的运动。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "足球和篮球，你更喜欢哪一个？", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喜欢看足球，妈妈喜欢看电影。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天下午我们去公园玩足球。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢足球踢得很好，很多人都认识他。", "target_word": "足球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "足球队", "label": "复合"}, {"form": "足球赛", "label": "复合"}, {"form": "足球场", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，指两队比赛、用脚踢球进门的球类运动项目，如“踢足球”“看足球”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '128e6c3e-0b01-402e-9083-229985605fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "足球", "is_correct": true, "explanation": "正确答案。“喜欢足球，每个周末都看比赛”，足球是可以看比赛的运动。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“喜欢地震”不成立，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“喜欢垃圾”不成立，句意不通。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“喜欢病毒”不成立，句意不通。"}], "explanations": {"足球": "正确答案。“喜欢足球，每个周末都看比赛”，足球是可以看比赛的运动。", "地震": "语义：“喜欢地震”不成立，句意不通。", "垃圾": "语义：“喜欢垃圾”不成立，句意不通。", "病毒": "语义：“喜欢病毒”不成立，句意不通。"}, "sentence_index": 0, "correct_answer": "足球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看了一张足球。", "explanation": "这里应该用〈场〉。足球比赛的量词是“场”，“张”用于平面的东西。"}, {"text": "妹妹挥拍打足球。", "explanation": "这里应该用〈网球〉。挥拍是网球的动作，足球不用球拍。"}, {"text": "他晚上在家里下足球。", "explanation": "这里应该用〈象棋〉。“下”用于棋类，足球不能下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": true, "explanation": "正确答案。“足球和篮球”是两种并列的体育运动，可以比较喜欢哪一个。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是体育运动，无法与篮球并列比较喜欢哪一个。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不能作为选择的对象，句子不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”不能与“篮球”并列作为可以比较喜欢的对象，句子不通。"}], "explanations": {"足球": "正确答案。“足球和篮球”是两种并列的体育运动，可以比较喜欢哪一个。", "天空": "语义：天空不是体育运动，无法与篮球并列比较喜欢哪一个。", "感冒": "语义：感冒是疾病，不能作为选择的对象，句子不通。", "垃圾": "语义：“垃圾”不能与“篮球”并列作为可以比较喜欢的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "足球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个足球。", "explanation": "这里应该用〈运动员〉。足球是运动项目，不能直接表示人的身份。"}, {"text": "我喜欢一条足球运动。", "explanation": "这里应该用〈项〉。足球运动的量词是“项”，“条”多用于细长的东西。"}, {"text": "他在场上扣了一个足球。", "explanation": "这里应该用〈排球〉。“扣”是排球、篮球的动作，足球不能扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹喝了足球。", "corrected_sentence": "妹妹踢了足球。", "error_description": "搭配错误：“喝”不能用于足球，足球是运动项目，应说“踢了足球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天看了一把足球。", "corrected_sentence": "我昨天看了一场足球。", "error_description": "错误在量词。足球作为体育比赛时，量词用“场”；“把”用于有柄的东西，不能用来数足球，应说“看了一场足球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fbfd52f-1d5e-472f-921e-af4828133e19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
