INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家的政府所在地。", "primary_collocate": null, "pronunciation": "shǒu dū", "ipa": "ʂoʊ˨˩˦ tu˥", "syllable_count": 2, "sentences": [{"text": "北京是中国的首都。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法国的首都是巴黎。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府在首都的中心办公。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "日本的首都是东京。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "各国大使都住在首都。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "首都的机场非常大。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总统的办公室就在首都。", "target_word": "首都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐火车去首都开会。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "各个部门都设在首都。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "泰国的首都是曼谷。", "target_word": "首都", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个首都", "label": "量词"}, {"form": "首都机场", "label": "复合"}], "register": "中性", "sense_fingerprint": "一国政府所在的城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首都", "is_correct": true, "explanation": "正确：指国家的政府所在地，北京是中国的首都，句意通顺。"}, {"text": "总统", "is_correct": false, "explanation": "语义：总统是人，不是城市，“北京是中国的总统”句意不通。"}, {"text": "省会", "is_correct": false, "explanation": "语义：省会指省一级的行政中心，北京不是省会，不能称为中国的省会。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“是……的”后接的是城市本身，“面积”是量度，不能说“北京是中国的面积”。"}], "explanations": {"首都": "正确：指国家的政府所在地，北京是中国的首都，句意通顺。", "总统": "语义：总统是人，不是城市，“北京是中国的总统”句意不通。", "省会": "语义：省会指省一级的行政中心，北京不是省会，不能称为中国的省会。", "面积": "搭配：“是……的”后接的是城市本身，“面积”是量度，不能说“北京是中国的面积”。"}, "sentence_index": 0, "correct_answer": "首都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新疆的首都是乌鲁木齐。", "explanation": "这里应该用“首府”。首都指国家的政府所在地；新疆是自治区，它的政府所在地叫首府。"}, {"text": "湖南的首都是长沙。", "explanation": "这里应该用“省会”。首都指国家的政府所在地；湖南是省，它的政府所在地叫省会。"}, {"text": "这所大学的首都很大。", "explanation": "这里应该用“校园”。首都指国家的政府所在地，大学的占地要用校园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首都", "is_correct": true, "explanation": "正确：总统的办公室设在国家的政府所在地，句意通顺。"}, {"text": "墨水", "is_correct": false, "explanation": "配价：“就在”后要接处所，墨水不是处所，句子不成立。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是处所，但总统的办公室不会设在海洋里。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，办公室不会设在冰箱里，句意荒谬。"}], "explanations": {"首都": "正确：总统的办公室设在国家的政府所在地，句意通顺。", "墨水": "配价：“就在”后要接处所，墨水不是处所，句子不成立。", "海洋": "语义：海洋是处所，但总统的办公室不会设在海洋里。", "冰箱": "语义：冰箱是家电，办公室不会设在冰箱里，句意荒谬。"}, "sentence_index": 6, "correct_answer": "首都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的首都在上海。", "explanation": "这里应该用“总部”。首都指国家的政府所在地，公司的办事中心要用总部。"}, {"text": "我在那家书店的首都里工作过。", "explanation": "这里应该用“店里”。首都指国家的政府所在地，书店的内部要说店里。"}, {"text": "这家餐厅的首都很大。", "explanation": "这里应该用“店面”。首都指国家的政府所在地，餐厅的门面要说店面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去过美国的一条首都华盛顿。", "corrected_sentence": "我去过美国的首都华盛顿。", "error_description": "量词错误：“条”用于细长的东西，不能修饰首都；这里不需要量词，或者用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在首都在开会。", "corrected_sentence": "他在首都开会。", "error_description": "重复介词：“在首都”已用介词“在”引出处所，不能再加一个“在”；应为“他在首都开会。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
