INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度很高；很，非常。", "primary_collocate": null, "pronunciation": "shí fēn", "ipa": "ʂɻ̩˧˥ fən˥", "syllable_count": 2, "sentences": [{"text": "今天天气十分好。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜十分好吃。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的汉语说得十分流利。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我十分喜欢这个新同学。", "target_word": "十分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听到这个好消息，大家都十分高兴。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里十分安静，没有人说话。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他工作十分努力，老板常常夸他。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的比赛十分精彩，我们看得很开心。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好一门外语，每天练习十分重要。", "target_word": "十分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的服务十分周到，客人都很满意。", "target_word": "十分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词：表示程度很高，修饰形容词或心理动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b82dac-691c-4a8d-92f2-df09b4bddc7a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：十分（shí fēn），意思是程度很高，很，非常。"}, {"text": "失分", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）声调不同，意思是失去分数。"}, {"text": "十份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，意思是十份。"}, {"text": "石粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，意思是石头磨成的粉。"}, {"text": "十封", "is_correct": false, "explanation": "fēng 与 fēn 韵母不同（ng 与 n），意思是十封（信）。"}], "explanations": {"十分": "正确：十分（shí fēn），意思是程度很高，很，非常。", "失分": "shī（第一声）与 shí（第二声）声调不同，意思是失去分数。", "十份": "fèn（第四声）与 fēn（第一声）声调不同，意思是十份。", "石粉": "fěn（第三声）与 fēn（第一声）声调不同，意思是石头磨成的粉。", "十封": "fēng 与 fēn 韵母不同（ng 与 n），意思是十封（信）。"}, "sentence_index": null, "correct_answer": "十分"}, "level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：“十分”作程度副词，修饰“好”，表示天气非常好。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”指过去，与“今天”矛盾，“今天天气曾好”意思不通。"}, {"text": "已", "is_correct": false, "explanation": "语域：“已”是书面语，口语不说“今天天气已好”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”与天气无关，“今天天气唱好”搭配不当。"}], "explanations": {"十分": "正确：“十分”作程度副词，修饰“好”，表示天气非常好。", "曾": "语义：“曾”指过去，与“今天”矛盾，“今天天气曾好”意思不通。", "已": "语域：“已”是书面语，口语不说“今天天气已好”。", "唱": "搭配：“唱”与天气无关，“今天天气唱好”搭配不当。"}, "sentence_index": 0, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们十分利用了这次机会。", "explanation": "这里应该用〈充分〉。“十分”是程度副词，不修饰“利用”这样的动作，要说“充分利用”。"}, {"text": "我们十分早点出发吧。", "explanation": "这里应该用〈尽量〉。“十分”表示程度很高，不表示尽力去做，要说“尽量早点”。"}, {"text": "请你十分等一下，我马上就来。", "explanation": "这里应该用〈稍微〉。“十分”表示程度很高，不能用来表示略微等待，要说“稍微等一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十分", "is_correct": true, "explanation": "正确：“十分”修饰“努力”，表示程度很高。"}, {"text": "不", "is_correct": false, "explanation": "语义：“他工作不努力”与后半句“老板常常夸他”矛盾。"}, {"text": "没", "is_correct": false, "explanation": "语义：“他工作没努力”与“老板常常夸他”矛盾。"}, {"text": "未", "is_correct": false, "explanation": "语域：“未”是书面语，口语不说“他工作未努力”。"}], "explanations": {"十分": "正确：“十分”修饰“努力”，表示程度很高。", "不": "语义：“他工作不努力”与后半句“老板常常夸他”矛盾。", "没": "语义：“他工作没努力”与“老板常常夸他”矛盾。", "未": "语域：“未”是书面语，口语不说“他工作未努力”。"}, "sentence_index": 6, "correct_answer": "十分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想要十分快一点的车。", "explanation": "这里应该用〈更〉。“十分”不能与“一点”连用表示比较，要说“更快一点”。"}, {"text": "这个菜十分好吃了！", "explanation": "这里应该用〈太〉。“十分”不能与“了”搭配表示感叹，要说“太好吃了”。"}, {"text": "我们十分赶紧出发吧。", "explanation": "这里应该用〈赶紧〉。“十分”表示程度，不能表示催促，要说“赶紧出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房间打扫十分干净。", "corrected_sentence": "他把房间打扫得十分干净。", "error_description": "补语错误：程度补语前要加「得」，应说“打扫得十分干净”；“打扫十分干净”漏掉了“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个菜的味道很十分好，大家都吃了很多。", "corrected_sentence": "这个菜的味道十分好，大家都吃了很多。", "error_description": "“很”和“十分”都是程度副词，不能叠用，应只用“十分”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e15391d-37d2-4e95-bf43-afa1985183d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出去", "is_correct": true, "explanation": "反义：“出去”与“回来”相对，指离开原来的地方。"}, {"text": "洗澡", "is_correct": false, "explanation": "无反义关系：“洗澡”指清洁身体，与“回来”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指慢走活动，与“回来”没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "无反义关系：“看书”指阅读，与“回来”没有反义关系。"}], "correct_answer": "出去", "explanations": {"出去": "反义：“出去”与“回来”相对，指离开原来的地方。", "洗澡": "无反义关系：“洗澡”指清洁身体，与“回来”没有反义关系。", "散步": "无反义关系：“散步”指慢走活动，与“回来”没有反义关系。", "看书": "无反义关系：“看书”指阅读，与“回来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "离开", "is_correct": true, "explanation": "反义：“离开”与“回来”相对，指从某地走开。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发出乐声，与“回来”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "无反义关系：“跳舞”指舞蹈动作，与“回来”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "无反义关系：“画画”指绘画，与“回来”没有反义关系。"}], "correct_answer": "离开", "explanations": {"离开": "反义：“离开”与“回来”相对，指从某地走开。", "唱歌": "无反义关系：“唱歌”指发出乐声，与“回来”没有反义关系。", "跳舞": "无反义关系：“跳舞”指舞蹈动作，与“回来”没有反义关系。", "画画": "无反义关系：“画画”指绘画，与“回来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回来是从别的地方走到原来的地方。", "primary_collocate": null, "pronunciation": "huí lái", "ipa": "xuei˧˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "她下班回来，先洗手。", "target_word": "回来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师出去开会，下午回来。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟踢完球，满头大汗地回来了。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了带钥匙，要回来拿。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷每天早上出去散步，八点回来。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们去旅行了，下个星期回来。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把伞忘在家里了，所以回来拿。", "target_word": "回来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人在外面，早点回来吧。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出差回来后，大家一起吃了饭。", "target_word": "回来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐在国外住着，很少回来。", "target_word": "回来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "回来了", "label": "体标"}, {"form": "回来过", "label": "体标"}, {"form": "回不来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "从外面走回原来的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回来", "is_correct": true, "explanation": "与语境相符：她下班后回到家，然后先洗手。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“下班睡觉”与“先洗手”的动作顺序和语境都不协调。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”是及物动词，后面需要宾语，不能单独作谓语。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”不是下班后的日常动作，与语境冲突。"}], "explanations": {"回来": "与语境相符：她下班后回到家，然后先洗手。", "睡觉": "语义：“下班睡觉”与“先洗手”的动作顺序和语境都不协调。", "修理": "配价：“修理”是及物动词，后面需要宾语，不能单独作谓语。", "结婚": "语义：“结婚”不是下班后的日常动作，与语境冲突。"}, "sentence_index": 0, "correct_answer": "回来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这孩子还没出过门，就回来了。", "explanation": "这里应该用〈来〉。回来表示走回原来待过的地方，孩子还没出过门，不能说回来。"}, {"text": "妹妹从没离开过宿舍，今天才回来。", "explanation": "这里应该用〈在〉。妹妹一直在宿舍，从没离开过，不存在返回，应说一直在宿舍。"}, {"text": "我还没离开教室，就已经回来了。", "explanation": "这里应该用〈在〉。我还没离开教室，不存在返回，应说还在教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回来", "is_correct": true, "explanation": "与语境相符：伞忘在家里，所以回到家里去拿。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”是及物动词，这里缺少宾语，“所以打扫拿”不成立。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧与“忘在家里的伞”的取回动作无关，语境冲突。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业与“取伞”的动作无关，语境冲突。"}], "explanations": {"回来": "与语境相符：伞忘在家里，所以回到家里去拿。", "打扫": "配价：“打扫”是及物动词，这里缺少宾语，“所以打扫拿”不成立。", "发烧": "语义：发烧与“忘在家里的伞”的取回动作无关，语境冲突。", "毕业": "语义：毕业与“取伞”的动作无关，语境冲突。"}, "sentence_index": 6, "correct_answer": "回来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶一辈子住在乡下，从没去过城里，昨天刚回来。", "explanation": "这里应该用〈到〉。回来要求先离开过原来的地方；奶奶从没去过城里，不存在返回，应说昨天刚到城里。"}, {"text": "老师一直在办公室，从没出去过，刚才回来。", "explanation": "这里应该用〈待〉。回来要求先离开过原来的地方；老师一直待在办公室，没有出去过，应说待在办公室。"}, {"text": "小狗在院子里玩，还没出过门，就回来了。", "explanation": "这里应该用〈来〉。小狗还没出过门，不能说回来，应说来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下午三点就回来了过。", "corrected_sentence": "他下午三点就回来了。", "error_description": "错误形式：回来了过；正确形式：回来了。“过”不能放在“了”之后；且“下午三点就”说的是已完成的具体事件，只用“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年出国，今年终于的回来了。", "corrected_sentence": "他去年出国，今年终于回来了。", "error_description": "错误形式：终于的回来；正确形式：终于回来。“终于”是副词，直接修饰动词，中间不加结构助词“的”，应删去“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
