INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86739, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人民币是中国的钱。", "primary_collocate": null, "pronunciation": "rén mín bì", "ipa": "ʐən˧˥ min˧˥ pi˥˩", "syllable_count": 3, "sentences": [{"text": "我去银行换了一千元人民币。", "target_word": "人民币", "complexity_tier": "T3", "furigana": "wǒ qù yínháng huàn le yì qiān yuán rénmínbì.", "sentence_source": "generated"}, {"text": "这家店只收人民币，不收美元。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一美元可以换多少人民币？", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我钱包里有两百块人民币。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把人民币放在红包里。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国买东西可以用人民币。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民币上印着很多漂亮的图案。", "target_word": "人民币", "complexity_tier": "T3", "furigana": "rénmínbì shàng yìnzhe hěn duō piàoliang de tú''àn.", "sentence_source": "generated"}, {"text": "我想用人民币买一张火车票。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回国后，她把美元换成了人民币。", "target_word": "人民币", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用人民币买的这个包一百块，不贵。", "target_word": "人民币", "complexity_tier": "T3", "furigana": "wǒ yòng rénmínbì mǎi de zhège bāo yì bǎi kuài, bú guì.", "sentence_source": "generated"}], "morphological_forms": [{"form": "人民幣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "中国使用的钱，买东西、换钱时用的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67a56d63-f4af-48ab-bef5-25a06a44575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86739, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人民币", "is_correct": true, "explanation": "正确：银行兑换的是货币，“一千元人民币”是中国的钱，与“换了”搭配自然。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不是货币，银行不能用“一千元”兑换面包。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸不是货币，“换了一千元”的对象应是钱。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“一千元”修饰的是货币，“钥匙”不能与“一千元”构成银行兑换的对象。"}], "explanations": {"人民币": "正确：银行兑换的是货币，“一千元人民币”是中国的钱，与“换了”搭配自然。", "面包": "语义：面包不是货币，银行不能用“一千元”兑换面包。", "报纸": "语义：报纸不是货币，“换了一千元”的对象应是钱。", "钥匙": "搭配：“一千元”修饰的是货币，“钥匙”不能与“一千元”构成银行兑换的对象。"}, "sentence_index": 0, "correct_answer": "人民币"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他钱包里有一只人民币。", "explanation": "这里应该用〈张〉。纸币按“张”计数，“只”多用于动物或成对的器物，不用于人民币。"}, {"text": "这个西瓜重两人民币。", "explanation": "语义：人民币是货币，不是重量单位，不能用来计量西瓜的重量。这里应该说“重两斤”之类。"}, {"text": "我明天去人民币旅游。", "explanation": "语义：人民币是货币，不是地点，不能说“去人民币”。这里应该说“去中国”之类的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86739, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民币", "is_correct": true, "explanation": "正确：纸币上可以印图案，“人民币上印着很多漂亮的图案”符合常识。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的，不能在上面印图案。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水体，不能作为印刷图案的平面。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“印着”搭配的是纸张、布料等平面，“月亮”不能被印着图案。"}], "explanations": {"人民币": "正确：纸币上可以印图案，“人民币上印着很多漂亮的图案”符合常识。", "空气": "语义：空气是无形的，不能在上面印图案。", "河流": "语义：河流是水体，不能作为印刷图案的平面。", "月亮": "搭配：“印着”搭配的是纸张、布料等平面，“月亮”不能被印着图案。"}, "sentence_index": 6, "correct_answer": "人民币"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天吃了一块人民币。", "explanation": "语义：人民币是货币，不能吃，“吃”的对象应是食物。"}, {"text": "我每天晚上给人民币讲故事。", "explanation": "语义：“讲故事”的对象应是能听的人，人民币不能作为听众。"}, {"text": "他会说一点人民币。", "explanation": "语义：人民币是货币，不是语言，不能说“会说一点人民币”。这里应该用〈汉语〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在银行换了两千个人民币。", "corrected_sentence": "我在银行换了两千块人民币。", "error_description": "量词错误：“人民币”作纸币计量时应说“两千块人民币”或“两千元人民币”，不能用“个”。正确形式是“两千块人民币”，“个”不用于纸币。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他人民币存进了银行。", "corrected_sentence": "他把人民币存进了银行。", "error_description": "把字句错误：“把”字句中必须用“把”引出受事“人民币”，应说“他把人民币存进了银行”；漏掉“把”的“他人民币存进了银行”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
