INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "志趣相同的人为社交、娱乐等活动组成的团体或场所。", "primary_collocate": null, "pronunciation": "jù lè bù", "ipa": "tɕy˥˩ lɤ˥˩ pu˥˩", "syllable_count": 3, "sentences": [{"text": "她参加了学校的俱乐部，每个星期都很开心。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "tā cān jiā le xué xiào de jù lè bù， měi gè xīng qī dōu hěn kāi xīn", "sentence_source": "generated"}, {"text": "俱乐部每个月都有一次活动。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想加入一个俱乐部，认识更多朋友。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "wǒ xiǎng jiā rù yí gè jù lè bù， rèn shi gèng duō péng you", "sentence_source": "generated"}, {"text": "这个俱乐部有二十多个会员。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俱乐部的会员每年交两百块钱。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这个俱乐部的老会员。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "tā shì zhè ge jù lè bù de lǎo huì yuán", "sentence_source": "generated"}, {"text": "俱乐部组织大家去海边玩了一天。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的俱乐部欢迎新朋友参加。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一个俱乐部里当过组长。", "target_word": "俱乐部", "complexity_tier": "T3", "furigana": "tā zài yí gè jù lè bù lǐ dāng guo zǔ zhǎng", "sentence_source": "generated"}, {"text": "俱乐部的成员常常一起旅行。", "target_word": "俱乐部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "足球俱乐部", "label": "复合"}, {"form": "俱樂部", "label": "繁体"}], "register": "中性", "sense_fingerprint": "志趣相同的人为社交、娱乐等组成的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：食堂是吃饭的地方，不是可以参加的团体，与“参加”搭配不当。"}, {"text": "俱乐部", "is_correct": true, "explanation": "俱乐部指志趣相同的人为娱乐活动组成的团体，参加它符合词义。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库用来存放货物，不能参加，也和“每个星期都很开心”的语境无关。"}, {"text": "宫殿", "is_correct": false, "explanation": "语域：“宫殿”是书面、庄重的说法，与日常学校活动的语境不搭。"}], "explanations": {"食堂": "语义：食堂是吃饭的地方，不是可以参加的团体，与“参加”搭配不当。", "俱乐部": "俱乐部指志趣相同的人为娱乐活动组成的团体，参加它符合词义。", "仓库": "语义：仓库用来存放货物，不能参加，也和“每个星期都很开心”的语境无关。", "宫殿": "语域：“宫殿”是书面、庄重的说法，与日常学校活动的语境不搭。"}, "sentence_index": 0, "correct_answer": "俱乐部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我开着俱乐部去上班。", "explanation": "这里“俱乐部”被当作交通工具，但它是团体或场所，开的应该是〈汽车〉。"}, {"text": "我家阳台上种着俱乐部。", "explanation": "这里“俱乐部”被当作植物，但它是团体或场所，阳台上种的应该是〈花〉。"}, {"text": "我昨天读完了俱乐部。", "explanation": "这里“俱乐部”被当作可以读的东西，但它是团体或场所，读的应该是〈书〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "盒子", "is_correct": false, "explanation": "语义：盒子是装东西的容器，不能组织大家去海边玩。"}, {"text": "俱乐部", "is_correct": true, "explanation": "俱乐部是有组织能力的团体，能组织成员出游，符合句意。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所是方便的地方，无法组织活动，与“去海边玩”的语境矛盾。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只能报时，不能组织大家去海边玩，与句意矛盾。"}], "explanations": {"盒子": "语义：盒子是装东西的容器，不能组织大家去海边玩。", "俱乐部": "俱乐部是有组织能力的团体，能组织成员出游，符合句意。", "厕所": "语义：厕所是方便的地方，无法组织活动，与“去海边玩”的语境矛盾。", "闹钟": "语义：闹钟只能报时，不能组织大家去海边玩，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "俱乐部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家俱乐部生产手机。", "explanation": "这里“俱乐部”被当作生产产品的企业，但它是团体或场所，生产产品应该用〈公司〉。"}, {"text": "俱乐部判了他三年徒刑。", "explanation": "这里“俱乐部”被当作司法机关，但它是团体或场所，不能判刑，判刑应该用〈法院〉。"}, {"text": "这家俱乐部每天接收很多病人。", "explanation": "这里“俱乐部”被当作接收病人的医疗机构，但它是团体或场所，接收病人应该用〈医院〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在学校参加了一只俱乐部，每个星期都很开心。", "corrected_sentence": "她在学校参加了一家俱乐部，每个星期都很开心。", "error_description": "量词错误：“俱乐部”作团体时量词用“家”，不能用“只”。“只”多用于动物，应把“一只俱乐部”改为“一家俱乐部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这位俱乐部欢迎新会员加入。", "corrected_sentence": "我们这家俱乐部欢迎新会员加入。", "error_description": "量词错误：“俱乐部”应使用量词“家”。“位”只用于人，不能修饰俱乐部，应把“这位俱乐部”改为“这家俱乐部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年来是说从过去到现在的这些年。", "primary_collocate": null, "pronunciation": "nián lái", "ipa": "njɛn˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "三年来，我一直住在这个城市，到现在也没有搬走。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年来，这里的变化很大。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五年来，他每天早上都跑步。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两年来，我们家没有搬过家。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，她一直在帮助老人。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八年来，我没有回过老家。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "四年来，他学了很多汉字。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "六年来，这家饭馆的菜一直很好吃。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几年来，我的汉语越来越好。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二十年来，妈妈每天都早起做饭。", "target_word": "年来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "数字加年来，从过去到现在的这些年，三年来、十年来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd32340c-cb3c-465f-9316-a2d78f46c512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年来", "is_correct": true, "explanation": "“年来”指从过去到现在的这些年，与“三年”和“一直住”的持续意义相合。"}, {"text": "年后", "is_correct": false, "explanation": "语义：“年后”指某个时间之后，与“一直住在这个城市”所说的持续到现在不符。"}, {"text": "年底", "is_correct": false, "explanation": "搭配：“三年底”不能表示三年这一段时间，“年底”只指某一年的年末。"}, {"text": "年初", "is_correct": false, "explanation": "语义：“年初”指某一年开头的时间点，不能与表示持续的“一直”搭配。"}], "explanations": {"年来": "“年来”指从过去到现在的这些年，与“三年”和“一直住”的持续意义相合。", "年后": "语义：“年后”指某个时间之后，与“一直住在这个城市”所说的持续到现在不符。", "年底": "搭配：“三年底”不能表示三年这一段时间，“年底”只指某一年的年末。", "年初": "语义：“年初”指某一年开头的时间点，不能与表示持续的“一直”搭配。"}, "sentence_index": 0, "correct_answer": "年来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次假期年来，我一直在家休息。", "explanation": "这里应该用〈近来〉。年来指若干年以来，不能用于“这次假期”这样不到一年的时段；说最近一段时间应用近来。"}, {"text": "我这个星期年来一直很忙。", "explanation": "这里应该用〈近来〉。年来指若干年以来，不能修饰“这个星期”这样的短时段；说一个星期内的情况应用近来。"}, {"text": "这一天年来，我的心情一直很好。", "explanation": "这里应该用〈近来〉。年来只用于几年、若干年的跨度，不能指“这一天”这样很短的时间；说近期的情况应用近来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年来", "is_correct": true, "explanation": "“年来”指过去到现在的这段时间，与“四年”和“学了很多汉字”的累积结果相合。"}, {"text": "年终", "is_correct": false, "explanation": "语义：“年终”指一年的末尾，是时间点，与“四年”的时间跨度不符。"}, {"text": "年末", "is_correct": false, "explanation": "语义：“年末”指年底这一时点，与“四年”里持续学习的过程不符。"}, {"text": "年尾", "is_correct": false, "explanation": "搭配：“四年尾”不能表示一段时间，“年尾”只指一年的末段。"}], "explanations": {"年来": "“年来”指过去到现在的这段时间，与“四年”和“学了很多汉字”的累积结果相合。", "年终": "语义：“年终”指一年的末尾，是时间点，与“四年”的时间跨度不符。", "年末": "语义：“年末”指年底这一时点，与“四年”里持续学习的过程不符。", "年尾": "搭配：“四年尾”不能表示一段时间，“年尾”只指一年的末段。"}, "sentence_index": 6, "correct_answer": "年来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我计划三年来去北京旅行。", "explanation": "这里应该用〈三年后〉。年来指过去到现在的若干年，不能指将来；说将来的时间应用“三年后”。"}, {"text": "我们家这个学期年来没有搬过家。", "explanation": "这里应该用〈近来〉。年来指若干年以来，不能用于“这个学期”这样不到一年的时段；说一个学期内的情况应用近来。"}, {"text": "我这两天年来很累。", "explanation": "这里应该用〈近来〉。年来指若干年以来，不能用于“这两天”这样很短的时段；说近期的状况应用近来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这五个年来，他一直在学习中文。", "corrected_sentence": "这五年来，他一直在学习中文。", "error_description": "错误：“五”和“年来”之间多加了量词“个”。正确说法是“这五年来”，数词直接与“年”组成时间跨度。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "十年来的，我们城市的变化很大。", "corrected_sentence": "十年来，我们城市的变化很大。", "error_description": "错误：“十年来”后多加了助词“的”，后面没有被修饰的名词，应去掉“的”。正确说法是“十年来，我们城市的变化很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内中是在里面。", "primary_collocate": null, "pronunciation": "nèi zhōng", "ipa": "nei˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "盒盖掀开，内中放着一封信。", "target_word": "内中", "complexity_tier": "T3", "furigana": "hé gài xiān kāi， nèi zhōng fàng zhe yì fēng xìn", "sentence_source": "generated"}, {"text": "屋外下着大雪，内中却很暖和。", "target_word": "内中", "complexity_tier": "T3", "furigana": "wū wài xià zhe dà xuě， nèi zhōng què hěn nuǎn huo", "sentence_source": "generated"}, {"text": "这座楼外面很旧，内中却很新。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子打开，内中装满了旧书。", "target_word": "内中", "complexity_tier": "T3", "furigana": "xiāng zi dǎ kāi， nèi zhōng zhuāng mǎn le jiù shū", "sentence_source": "generated"}, {"text": "他把钱收好，内中还夹着一张照片。", "target_word": "内中", "complexity_tier": "T3", "furigana": "tā bǎ qián shōu hǎo， nèi zhōng hái jiā zhe yì zhāng zhào piàn", "sentence_source": "generated"}, {"text": "洞外阳光明亮，内中却传来水声。", "target_word": "内中", "complexity_tier": "T3", "furigana": "dòng wài yáng guāng míng liàng， nèi zhōng què chuán lái shuǐ shēng", "sentence_source": "generated"}, {"text": "瓶子晃了晃，内中还剩半瓶水。", "target_word": "内中", "complexity_tier": "T3", "furigana": "píng zi huàng le huàng， nèi zhōng hái shèng bàn píng shuǐ", "sentence_source": "generated"}, {"text": "房子外面有灯，内中没有人，门却开着。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面吵吵闹闹，内中却很安静。", "target_word": "内中", "complexity_tier": "T3", "furigana": "wài miàn chāo chao nào nao， nèi zhōng què hěn ān jìng", "sentence_source": "generated"}, {"text": "包拉开，内中还有一把伞。", "target_word": "内中", "complexity_tier": "T3", "furigana": "bāo lā kāi， nèi zhōng hái yǒu yì bǎ sǎn", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "内中：事物的里面，指空间的内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的房间，盒子掀开后不会放在厨房里，句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中指物体的里面。“盒盖掀开，内中放着一封信”说的是盒子里面放着信，符合词义。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是运动场地，不能用来放信，与“盒盖掀开”的语境矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能用来放信，与“盒盖掀开”的语境矛盾。"}], "explanations": {"厨房": "语义：厨房是做饭的房间，盒子掀开后不会放在厨房里，句意不通。", "内中": "内中指物体的里面。“盒盖掀开，内中放着一封信”说的是盒子里面放着信，符合词义。", "操场": "语义：操场是运动场地，不能用来放信，与“盒盖掀开”的语境矛盾。", "天空": "语义：天空不能用来放信，与“盒盖掀开”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个箱子内中放着一只猫。", "explanation": "这里应该用〈中间〉。内中指一个物体的里面，两个物体之间的位置要用中间。"}, {"text": "他吃饭内中接了一个电话。", "explanation": "这里“内中”被当作时间范围，但它只表示空间的里面，吃饭的时间应该用〈期间〉。"}, {"text": "桌面内中有一本书。", "explanation": "这里“内中”被当作物体的表面，但桌面没有里面，书在桌面的上方，应该用〈上面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地板", "is_correct": false, "explanation": "语义：地板不能盛水，“瓶子晃了晃”后说“地板还剩半瓶水”，句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中指物体的里面。“瓶子晃了晃，内中还剩半瓶水”说的是瓶子里面还有水，符合词义。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不是盛水的空间，与“瓶子晃了晃”的语境搭配不当。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：天花板是房顶，不能盛水，与句意矛盾。"}], "explanations": {"地板": "语义：地板不能盛水，“瓶子晃了晃”后说“地板还剩半瓶水”，句意不通。", "内中": "内中指物体的里面。“瓶子晃了晃，内中还剩半瓶水”说的是瓶子里面还有水，符合词义。", "窗户": "搭配：窗户不是盛水的空间，与“瓶子晃了晃”的语境搭配不当。", "天花板": "语义：天花板是房顶，不能盛水，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两把椅子内中放着一盆花。", "explanation": "这里应该用〈中间〉。内中指物体的里面，两把椅子之间的位置要用中间。"}, {"text": "他跑步内中出了一身汗。", "explanation": "这里“内中”被当作活动过程中的时间，但它只表示空间的里面，跑步期间应该用〈期间〉。"}, {"text": "墙内中挂着一幅画。", "explanation": "这里“内中”被当作墙面上的位置，但画是挂在墙面上，而不是墙的里面，应该用〈墙上〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抽屉拉开，内中了还有几封信。", "corrected_sentence": "抽屉拉开，内中还有几封信。", "error_description": "用法错误：「内中」是方位词，后面不能加「了」；应说「内中还有几封信」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "杯子晃了晃，内中了还剩一点水。", "corrected_sentence": "杯子晃了晃，内中还剩一点水。", "error_description": "用法错误：「内中」是方位词，后面不能加「了」；应说「内中还剩一点水」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "里头；其中。", "primary_collocate": null, "pronunciation": "nèi zhōng", "ipa": "nei˥˩ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "事情的经过很复杂，内中原因很多。", "target_word": "内中", "complexity_tier": "T3", "furigana": "shì qing de jīng guò hěn fù zá， nèi zhōng yuán yīn hěn duō", "sentence_source": "generated"}, {"text": "内中的情况，我不太清楚。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人，内中有一个是我同学。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了五本书，内中两本是送人的。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司有三个部门，内中的问题不少。", "target_word": "内中", "complexity_tier": "T3", "furigana": "zhè jiā gōng sī yǒu sān gè bù mén， nèi zhōng de wèn tí bù shǎo", "sentence_source": "generated"}, {"text": "这件事看起来简单，内中却不简单。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外人不知道内中的缘由。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有两百个学生，内中一半是外地人。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内中的道理，你慢慢想吧。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事内中有人暗中帮忙，他才成功了。", "target_word": "内中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "内中：其中，指事情的内情或总数之中的一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能作为事情的原因，“事情的经过很复杂，椅子原因很多”句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中表示其中，指事情内部的情况。“内中原因很多”说的是事情的内情，符合词义。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能成为事情的原因，与句意矛盾。"}, {"text": "宫殿", "is_correct": false, "explanation": "语域：“宫殿”是书面、庄重的说法，与叙述事情经过的语境不搭，且指建筑，无法指原因。"}], "explanations": {"椅子": "语义：椅子不能作为事情的原因，“事情的经过很复杂，椅子原因很多”句意不通。", "内中": "内中表示其中，指事情内部的情况。“内中原因很多”说的是事情的内情，符合词义。", "厨房": "语义：厨房是房间，不能成为事情的原因，与句意矛盾。", "宫殿": "语域：“宫殿”是书面、庄重的说法，与叙述事情经过的语境不搭，且指建筑，无法指原因。"}, "sentence_index": 0, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两座山内中有一条河。", "explanation": "这里“内中”被当作两山之间的空隙，但它只表示范围里面或其中的一部分，两座山之间应该用〈之间〉。"}, {"text": "吃完饭内中，我去散步。", "explanation": "这里“内中”被当作时间的先后，但它表示里头或其中，不表示先后，吃完饭之后应该用〈之后〉。"}, {"text": "三天内中完成了任务。", "explanation": "这里“内中”被当作时间范围，但它不表示时间段，三天之内应该用〈之内〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是事情的缘由，“外人不知道冰箱的缘由”句意不通。"}, {"text": "内中", "is_correct": true, "explanation": "内中表示内情，“外人不知道内中的缘由”说的是事情内部的缘由，符合词义。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车不是事情的缘由，“外人不知道公交车的缘由”句意不通。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌不是事情的缘由，“外人不知道书桌的缘由”句意不通。"}], "explanations": {"冰箱": "语义：冰箱不是事情的缘由，“外人不知道冰箱的缘由”句意不通。", "内中": "内中表示内情，“外人不知道内中的缘由”说的是事情内部的缘由，符合词义。", "公交车": "语义：公交车不是事情的缘由，“外人不知道公交车的缘由”句意不通。", "书桌": "语义：书桌不是事情的缘由，“外人不知道书桌的缘由”句意不通。"}, "sentence_index": 6, "correct_answer": "内中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天内中有一只鸟。", "explanation": "这里“内中”被当作天空里面的位置，但鸟在天的上方，不在里面，应该用〈天上〉。"}, {"text": "他的脸内中有一颗痣。", "explanation": "这里“内中”被当作脸的里面，但痣长在脸的表面，应该用〈脸上〉。"}, {"text": "他的手表内中很亮。", "explanation": "这里“内中”被当作表面，但手表的亮光在表面，应该用〈表面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "事情的经过很复杂，内中了的原因不少。", "corrected_sentence": "事情的经过很复杂，内中的原因不少。", "error_description": "用法错误：「内中」是方位词，不能带「了」；应说「内中的原因不少」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班上有四十个学生，的内中一半是女生。", "corrected_sentence": "班上有四十个学生，内中一半是女生。", "error_description": "位置错误：「的」不能放在「内中」前面；应说「内中一半是女生」，「内中」直接放在数量短语「一半」之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
