INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86752, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示非常接近；差不多。", "primary_collocate": null, "pronunciation": "jī hū", "ipa": "tɕi˥ xu˥", "syllable_count": 2, "sentences": [{"text": "我几乎每天都喝咖啡。", "target_word": "几乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的人几乎都会说英语。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里几乎没有人。", "target_word": "几乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他花掉了几乎所有的钱。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西几乎都很便宜。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她几乎一整天都在看书。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这里几乎不下雨。", "target_word": "几乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子的身高几乎一样。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话我几乎都听懂了。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班几乎所有人都去了。", "target_word": "几乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾乎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几乎：表示数量或程度非常接近，差不多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd32340c-cb3c-465f-9316-a2d78f46c512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "几乎", "is_correct": true, "explanation": "“几乎”表示接近、差不多，与“每天都”所说的大致频率相合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未如此，与“每天都”的习惯相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“每天都”的经常性冲突。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，不能表示“每天都”这种经常性的习惯。"}], "explanations": {"几乎": "“几乎”表示接近、差不多，与“每天都”所说的大致频率相合。", "从来": "语义：“从来”表示从未如此，与“每天都”的习惯相矛盾。", "偶尔": "语义：“偶尔”表示不常发生，与“每天都”的经常性冲突。", "已经": "体貌：“已经”表示动作已经完成，不能表示“每天都”这种经常性的习惯。"}, "sentence_index": 0, "correct_answer": "几乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜几乎太好吃了。", "explanation": "“简直”是强调程度的副词，用来说“太好吃了”。这里应换用“简直”，“几乎”表示接近，不表达强调的程度。"}, {"text": "我几乎正好三十岁。", "explanation": "这里应该用〈恰好〉。几乎表示接近，与“正好”所表示的确定数量相矛盾，不能同时使用。"}, {"text": "我们班几乎有很多人都去了。", "explanation": "这里应该用〈大部分〉。几乎表示接近，与“很多人”这种泛指的数量不相配，不能用来修饰多数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "几乎", "is_correct": true, "explanation": "“几乎”表示接近、差不多，与“不下雨”的大致情况相合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰程度，不能修饰“不下雨”这样的否定动作。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“冬天这里”所描述的常态不符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生的变化，与“冬天这里”所描述的常态不符。"}], "explanations": {"几乎": "“几乎”表示接近、差不多，与“不下雨”的大致情况相合。", "非常": "搭配：“非常”修饰程度，不能修饰“不下雨”这样的否定动作。", "立刻": "语义：“立刻”表示马上发生，与“冬天这里”所描述的常态不符。", "忽然": "语义：“忽然”表示突然发生的变化，与“冬天这里”所描述的常态不符。"}, "sentence_index": 6, "correct_answer": "几乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班几乎正好三十人都去了。", "explanation": "这里应该用〈差不多〉。几乎表示接近，与“正好”所确定的数量相矛盾，两者不能一起用。"}, {"text": "你们班几乎有多少人？", "explanation": "这里不能用〈几乎〉。问具体人数应直接用“多少”或〈大约〉，几乎表示接近，不能用于询问确切数量。"}, {"text": "我们班几乎正好有一个人没去。", "explanation": "这里应该用〈恰好〉。几乎表示接近，与“正好有一个人”这样确定的数量相矛盾，不能同时使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几乎的每天都在学习。", "corrected_sentence": "我们几乎每天都在学习。", "error_description": "错误：副词“几乎”后多加了“的”。正确说法是“我们几乎每天都在学习”，“几乎”直接修饰后面的“每天都”，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们班几乎几乎所有人都通过了考试。", "corrected_sentence": "他们班几乎所有人都通过了考试。", "error_description": "错误：副词“几乎”重复了一次。正确说法是只用一个“几乎”，放在“所有人”之前，修饰整个名词短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
