INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供汽车等行驶的道路，通常在城市之间。", "primary_collocate": null, "pronunciation": "gōng lù", "ipa": "kʊŋ˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这条公路连着两个城市。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从北京到天津有一条新公路。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路修好后，两个城市近多了。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开车走公路去上海。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条公路穿过山，通向海边的小城。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去外地的公路在城外面。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐长途汽车走公路要五个小时。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要修一条新公路到那个小县城。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路把山里的村子和城市连起来。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末去城外的车很多，公路上堵得厉害。", "target_word": "公路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "高速公路", "label": "复合"}, {"form": "公路网", "label": "复合"}], "register": "中性", "sense_fingerprint": "连接城市与城市、城乡之间的道路，强调交通连接", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5c59a7b-8344-40ee-b9d9-79947b58f882') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86754, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：连接城市之间、供汽车行驶的道路，即正确答案。"}, {"text": "通路", "is_correct": false, "explanation": "g 与 t 声母不同，通路指通行的途径，不是连接城市的公路。"}, {"text": "功利", "is_correct": false, "explanation": "lù 与 lì 韵母不同（u 与 i），功利指追求实际利益。"}, {"text": "公墓", "is_correct": false, "explanation": "l 与 m 声母不同，公墓指供埋葬用的墓地。"}, {"text": "中路", "is_correct": false, "explanation": "g 与 zh 声母不同，中路指中间的路线。"}], "explanations": {"公路": "公路：连接城市之间、供汽车行驶的道路，即正确答案。", "通路": "g 与 t 声母不同，通路指通行的途径，不是连接城市的公路。", "功利": "lù 与 lì 韵母不同（u 与 i），功利指追求实际利益。", "公墓": "l 与 m 声母不同，公墓指供埋葬用的墓地。", "中路": "g 与 zh 声母不同，中路指中间的路线。"}, "sentence_index": null, "correct_answer": "公路"}, "level_3": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：连接两个城市的道路，符合句意。"}, {"text": "项链", "is_correct": false, "explanation": "语义：项链不能连接城市，“连着”只用于道路、铁路等。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾不能连接城市，句中是交通连接的意思。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”的量词是“本”，不能用“条”来量。"}], "explanations": {"公路": "公路：连接两个城市的道路，符合句意。", "项链": "语义：项链不能连接城市，“连着”只用于道路、铁路等。", "围巾": "语义：围巾不能连接城市，句中是交通连接的意思。", "书": "搭配：“书”的量词是“本”，不能用“条”来量。"}, "sentence_index": 0, "correct_answer": "公路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车沿着公路去上海。", "explanation": "这里应该用〈铁路〉。火车只能沿铁路行驶，公路供汽车等车辆通行。"}, {"text": "货船沿着公路去上海。", "explanation": "这里应该用〈航道〉。货船走水路，要沿航道航行，公路是陆地上供车辆行驶的道路。"}, {"text": "这只公路连着两个城市。", "explanation": "这里应该用〈条〉。公路的量词是“条”，“只”不能量公路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86754, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：连接城市之间、供汽车行驶的道路，即正确答案。"}, {"text": "空路", "is_correct": false, "explanation": "g 与 k 声母不同，空路指空中航线，不是地面道路。"}, {"text": "功率", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），功率指做功的快慢。"}, {"text": "公寓", "is_correct": false, "explanation": "l 与零声母不同（lù 与 yù），公寓指居住的楼房单元。"}, {"text": "公诉", "is_correct": false, "explanation": "l 与 s 声母不同，公诉指检察机关向法院提起诉讼。"}], "explanations": {"公路": "公路：连接城市之间、供汽车行驶的道路，即正确答案。", "空路": "g 与 k 声母不同，空路指空中航线，不是地面道路。", "功率": "lù 与 lǜ 韵母不同（u 与 ü），功率指做功的快慢。", "公寓": "l 与零声母不同（lù 与 yù），公寓指居住的楼房单元。", "公诉": "l 与 s 声母不同，公诉指检察机关向法院提起诉讼。"}, "sentence_index": null, "correct_answer": "公路"}, "level_3": {"options": [{"text": "公路", "is_correct": true, "explanation": "公路：长途汽车行驶的道路，符合句意。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：长途汽车不能走铁路，铁路供火车行驶。"}, {"text": "航道", "is_correct": false, "explanation": "搭配：“走”后面接道路，“航道”是船只航行的水道，搭配不当。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不供汽车通行，汽车不能走河流。"}], "explanations": {"公路": "公路：长途汽车行驶的道路，符合句意。", "铁路": "语义：长途汽车不能走铁路，铁路供火车行驶。", "航道": "搭配：“走”后面接道路，“航道”是船只航行的水道，搭配不当。", "河流": "语义：河流不供汽车通行，汽车不能走河流。"}, "sentence_index": 6, "correct_answer": "公路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天坐公路回了老家。", "explanation": "这里应该用〈走〉。公路是路，不是交通工具，不能说“坐公路”。"}, {"text": "孩子们在公路上写作业。", "explanation": "这里应该用〈教室〉。写作业要在教室或家里进行，公路是供车辆行驶的路，不是写作业的地方。"}, {"text": "这条公路每天跑三百公里。", "explanation": "这里的主语应该是〈车〉。公路不会跑，是车在公路上跑，公路不能做“跑”的主语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县城新修了一只公路通到海边。", "corrected_sentence": "县城新修了一条公路通到海边。", "error_description": "错误：“一只公路”；正确：“一条公路”。公路的量词用“条”，“只”多用于动物，不能量公路。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沿着这条公路们，我们开到了城外。", "corrected_sentence": "沿着这条公路，我们开到了城外。", "error_description": "错误：“公路们”；正确：“公路”。“们”一般只用于指人的名词，不能加在无生命的“公路”后面表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f4bd203-d9af-4135-9ebf-8410d93a6e85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
