INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86760, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "男性的；人类两性中与“女”相对的一方。", "primary_collocate": null, "pronunciation": "nán", "ipa": "nan˧˥", "syllable_count": 1, "sentences": [{"text": "我们学校新来了一位男老师。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的男医生不多，女医生比较多。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的男同事在银行工作。", "target_word": "男", "complexity_tier": "T3", "furigana": "tā de nán tóng shì zài yín háng gōng zuò。", "sentence_source": "generated"}, {"text": "这部电影的男演员很年轻。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是班上唯一的男同学。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男乘客在楼梯的左边排队。", "target_word": "男", "complexity_tier": "T3", "furigana": "nán chéng kè zài lóu tī de zuǒ biān pái duì。", "sentence_source": "generated"}, {"text": "那位男歌手的声音很好听。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的男顾客比女顾客少。", "target_word": "男", "complexity_tier": "T3", "furigana": "zhè jiā shāng diàn de nán gù kè bǐ nǚ gù kè shǎo。", "sentence_source": "generated"}, {"text": "小王是个男护士，他很会照顾病人。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车的男司机帮她拿了行李。", "target_word": "男", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "男人", "label": "复合"}, {"form": "男孩", "label": "复合"}], "register": "中性", "sense_fingerprint": "男：男性的，只用来修饰人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd32340c-cb3c-465f-9316-a2d78f46c512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男”读 nán，修饰人时指男性，与“女”相对。"}, {"text": "蓝", "is_correct": false, "explanation": "声母不同：lán 与 nán 声母不同（l 与 n），意思是蓝色。"}, {"text": "懒", "is_correct": false, "explanation": "声母与声调不同：lǎn（第三声）与 nán（第二声）声母不同（l 与 n），意思是懒。"}, {"text": "嫩", "is_correct": false, "explanation": "韵母不同：nèn 与 nán 韵母不同（en 与 an），意思是嫩。"}, {"text": "拿", "is_correct": false, "explanation": "韵母不同：ná 与 nán 韵母不同（a 与 an），意思是拿。"}], "explanations": {"男": "正确：“男”读 nán，修饰人时指男性，与“女”相对。", "蓝": "声母不同：lán 与 nán 声母不同（l 与 n），意思是蓝色。", "懒": "声母与声调不同：lǎn（第三声）与 nán（第二声）声母不同（l 与 n），意思是懒。", "嫩": "韵母不同：nèn 与 nán 韵母不同（en 与 an），意思是嫩。", "拿": "韵母不同：ná 与 nán 韵母不同（a 与 an），意思是拿。"}, "sentence_index": null, "correct_answer": "男"}, "level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男老师”指男性教师，修饰“老师”通顺。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”描述形状，不能用来修饰人的性别。"}, {"text": "沉", "is_correct": false, "explanation": "搭配：“沉老师”不是常见搭配，“沉”不能修饰“老师”。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”描述物体的厚度，不能用来修饰老师。"}], "explanations": {"男": "正确：“男老师”指男性教师，修饰“老师”通顺。", "圆": "语义：“圆”描述形状，不能用来修饰人的性别。", "沉": "搭配：“沉老师”不是常见搭配，“沉”不能修饰“老师”。", "厚": "语义：“厚”描述物体的厚度，不能用来修饰老师。"}, "sentence_index": 0, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只男孔雀很漂亮。", "explanation": "这里应该用〈雄〉。“男”修饰人，孔雀的雄性说“雄孔雀”。"}, {"text": "这个男花瓶很漂亮。", "explanation": "这个用法不对：“男”只修饰人，花瓶没有性别，不能说“男花瓶”。"}, {"text": "这把男雨伞很结实。", "explanation": "这个用法不对：“男”只指人的性别，雨伞没有性别，不能说“男雨伞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86760, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男”读 nán，修饰人时指男性，与“女”相对。"}, {"text": "拦", "is_correct": false, "explanation": "声母不同：lán 与 nán 声母不同（l 与 n），意思是拦住。"}, {"text": "烂", "is_correct": false, "explanation": "声母与声调不同：làn 与 nán 声母不同（l 与 n）且声调不同，意思是烂。"}, {"text": "念", "is_correct": false, "explanation": "韵母与声调不同：niàn 与 nán 韵母不同（ian 与 an）且声调不同，意思是读。"}, {"text": "满", "is_correct": false, "explanation": "声母与声调不同：mǎn 与 nán 声母不同（m 与 n）且声调不同，意思是满。"}], "explanations": {"男": "正确：“男”读 nán，修饰人时指男性，与“女”相对。", "拦": "声母不同：lán 与 nán 声母不同（l 与 n），意思是拦住。", "烂": "声母与声调不同：làn 与 nán 声母不同（l 与 n）且声调不同，意思是烂。", "念": "韵母与声调不同：niàn 与 nán 韵母不同（ian 与 an）且声调不同，意思是读。", "满": "声母与声调不同：mǎn 与 nán 声母不同（m 与 n）且声调不同，意思是满。"}, "sentence_index": null, "correct_answer": "男"}, "level_3": {"options": [{"text": "男", "is_correct": true, "explanation": "正确：“男歌手”指男性歌手，修饰“歌手”通顺。"}, {"text": "白", "is_correct": false, "explanation": "搭配：“白歌手”不是常见搭配，“白”不能修饰“歌手”。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”描述距离，不能用来修饰歌手的性别。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“薄”描述厚度，与“歌手”不相配。"}], "explanations": {"男": "正确：“男歌手”指男性歌手，修饰“歌手”通顺。", "白": "搭配：“白歌手”不是常见搭配，“白”不能修饰“歌手”。", "远": "语义：“远”描述距离，不能用来修饰歌手的性别。", "薄": "语义：“薄”描述厚度，与“歌手”不相配。"}, "sentence_index": 6, "correct_answer": "男"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只男狗很可爱。", "explanation": "这里应该用〈公〉。“男”修饰人，狗的雄性说“公狗”。"}, {"text": "这把男椅子很舒服。", "explanation": "这个用法不对：“男”只修饰人，椅子没有性别，不能说“男椅子”。"}, {"text": "那只男老鼠很机灵。", "explanation": "这里应该用〈雄〉。“男”不用于动物，老鼠的雄性说“雄鼠”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只男演员很年轻。", "corrected_sentence": "那位男演员很年轻。", "error_description": "“男演员”指人，量词应用“位”或“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个的男护士很会照顾病人。", "corrected_sentence": "那个男护士很会照顾病人。", "error_description": "“的”的位置错误：不能插在“那个”和“男护士”之间，应说“那个男护士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
