INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "若是说“如果”，意思是假如这样。", "primary_collocate": null, "pronunciation": "ruò", "ipa": "ʐwo˥˩", "syllable_count": 1, "sentences": [{"text": "你若不想去，可以留在家里。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我若有钱，就买一间大房子。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他若来了，请让他等我一下。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家若有问题，可以随时问我。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你若累了，就先回家休息吧。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天若黑了，我们就别走山路了。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子若生病了，要马上去医院。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们若努力，就一定能成功。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你若喜欢这本书，我就送给你。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他若知道这件事，一定会很高兴。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假若", "label": "复合"}, {"form": "倘若", "label": "复合"}, {"form": "若是", "label": "复合"}], "register": "书面语", "sense_fingerprint": "放在主语之后引出假设，意思是如果、假如", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a666923a-00f0-43ce-9ee1-f1406e0ad8d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "若", "is_correct": true, "explanation": "若：ruò（第四声），连词，意思是如果、假如。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。"}, {"text": "挪", "is_correct": false, "explanation": "nuó（第二声）与 ruò 声母不同（n 与 r），声调也不同，意思是挪动。"}, {"text": "锐", "is_correct": false, "explanation": "ruì（第四声）与 ruò 韵母不同（ui 与 uo），意思是锐利。"}], "explanations": {"若": "若：ruò（第四声），连词，意思是如果、假如。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。", "挪": "nuó（第二声）与 ruò 声母不同（n 与 r），声调也不同，意思是挪动。", "锐": "ruì（第四声）与 ruò 韵母不同（ui 与 uo），意思是锐利。"}, "sentence_index": null, "correct_answer": "若"}, "level_3": {"options": [{"text": "若", "is_correct": true, "explanation": "若：书面语连词，放在主语之后引出假设，意思是如果，可以填入。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示先后动作，不表示假设，「你然后不想去」不成立。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进或并列，不引出假设条件，「你而且不想去」不成立。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：「所以」要接在原因之后，「你所以不想去」不能说，也不能引出条件。"}], "explanations": {"若": "若：书面语连词，放在主语之后引出假设，意思是如果，可以填入。", "然后": "语义：「然后」表示先后动作，不表示假设，「你然后不想去」不成立。", "而且": "语义：「而且」表示递进或并列，不引出假设条件，「你而且不想去」不成立。", "所以": "搭配：「所以」要接在原因之后，「你所以不想去」不能说，也不能引出条件。"}, "sentence_index": 0, "correct_answer": "若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛我们若取得了好成绩，多亏了大家的努力。", "explanation": "这里应该用〈因为〉。若表示假设，不能用来说明已经取得的成绩是由什么原因造成的。"}, {"text": "雨下得很大，若比赛就取消了。", "explanation": "这里应该用〈所以〉。若表示假设，不能用来引出已经发生的结果。"}, {"text": "我先洗了澡，若去看了书，最后睡觉了。", "explanation": "这里应该用〈然后〉。若表示假设，不能用来表示动作的先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "若", "is_correct": true, "explanation": "若：ruò（第四声），连词，意思是如果、假如。"}, {"text": "诺", "is_correct": false, "explanation": "nuò（第四声）与 ruò 声母不同（n 与 r），声调相同，意思是答应。"}, {"text": "罗", "is_correct": false, "explanation": "luó（第二声）与 ruò 声母不同（l 与 r），声调也不同，意思是网、罗列。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），声调相同，意思是落下。"}], "explanations": {"若": "若：ruò（第四声），连词，意思是如果、假如。", "诺": "nuò（第四声）与 ruò 声母不同（n 与 r），声调相同，意思是答应。", "罗": "luó（第二声）与 ruò 声母不同（l 与 r），声调也不同，意思是网、罗列。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），声调相同，意思是落下。"}, "sentence_index": null, "correct_answer": "若"}, "level_3": {"options": [{"text": "若", "is_correct": true, "explanation": "若：书面语连词，引出假设，与后面的「要马上」相配合，可以填入。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，句中没有前后对立，「孩子但是生病了」不通。"}, {"text": "不过", "is_correct": false, "explanation": "搭配：「不过」前面需要有前文的对比或让步，句中单独用于「孩子生病了」不成立。"}, {"text": "并且", "is_correct": false, "explanation": "语义：「并且」表示并列或递进，不引出假设条件，「孩子并且生病了」不成立。"}], "explanations": {"若": "若：书面语连词，引出假设，与后面的「要马上」相配合，可以填入。", "但是": "语义：「但是」表示转折，句中没有前后对立，「孩子但是生病了」不通。", "不过": "搭配：「不过」前面需要有前文的对比或让步，句中单独用于「孩子生病了」不成立。", "并且": "语义：「并且」表示并列或递进，不引出假设条件，「孩子并且生病了」不成立。"}, "sentence_index": 6, "correct_answer": "若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是老师，若是学生。", "explanation": "这里应该用〈而是〉。若是表示假设，不能用来表示对立的另一种情况。"}, {"text": "这个房间很小，若已经住了五个人。", "explanation": "这里应该用〈其实〉。若表示假设，不能用来说明实际情况。"}, {"text": "他很努力，若成绩却不好。", "explanation": "这里应该用〈但是〉。若表示假设，不能引出与前文相反的转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你若渴了，就若先喝点水吧。", "corrected_sentence": "你若渴了，就先喝点水吧。", "error_description": "错误：「若」被多加在主句「就先喝点水」中，写成「就若先喝点水」。正确写法是「你若渴了，就先喝点水吧」，「若」只放在条件分句的主语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我是若有空，就去看你。", "corrected_sentence": "我若有空，就去看你。", "error_description": "错误：「是」被放在了「若」前面，写成「是若有空」。「若」前不能加「是」，正确写法是「我若有空，就去看你」，「若」应放在主语之后、条件分句之前，表示假设。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
