INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，如果，假如。", "primary_collocate": null, "pronunciation": "ruò", "ipa": "ʐwo˥˩", "syllable_count": 1, "sentences": [{"text": "若明天下雨，我们就不去公园了。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若你有空，请给我打个电话。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若天气好，我们便去爬山。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若人人都帮忙，这件事很快就能做完。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若今晚不睡觉，明天就会很累。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若遇到困难，请马上告诉老师。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若路上堵车，我们就坐地铁去。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若他同意，我们就可以开始了。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若时间不够，这个计划就先放一放。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "若车票卖完了，我们就明天再走。", "target_word": "若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "假若", "label": "复合"}, {"form": "倘若", "label": "复合"}, {"form": "若是", "label": "复合"}], "register": "书面语", "sense_fingerprint": "放在分句开头引出假设条件，后面常接就、便、则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a666923a-00f0-43ce-9ee1-f1406e0ad8d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "若", "is_correct": true, "explanation": "若：ruò（第四声），连词，意思是如果、假如。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。"}, {"text": "诺", "is_correct": false, "explanation": "nuò（第四声）与 ruò 声母不同（n 与 r），意思是答应。"}, {"text": "挪", "is_correct": false, "explanation": "nuó（第二声）与 ruò 声母不同（n 与 r），声调也不同，意思是挪动。"}, {"text": "罗", "is_correct": false, "explanation": "luó（第二声）与 ruò 声母不同（l 与 r），声调也不同，意思是网、罗列。"}], "explanations": {"若": "若：ruò（第四声），连词，意思是如果、假如。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），意思是落下。", "诺": "nuò（第四声）与 ruò 声母不同（n 与 r），意思是答应。", "挪": "nuó（第二声）与 ruò 声母不同（n 与 r），声调也不同，意思是挪动。", "罗": "luó（第二声）与 ruò 声母不同（l 与 r），声调也不同，意思是网、罗列。"}, "sentence_index": null, "correct_answer": "若"}, "level_3": {"options": [{"text": "若", "is_correct": true, "explanation": "若：书面语连词，引出假设条件，与后面的「就」相呼应，可以填入。"}, {"text": "然后", "is_correct": false, "explanation": "语义：「然后」表示先后顺序，不表示假设，「然后明天下雨」不成立。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：「虽然」表示让步，通常与后文的转折相呼应；此句「就不去公园了」是顺承，前后不构成让步，不能引出假设。"}, {"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进或并列，不引出假设条件，「而且明天下雨」不成立。"}], "explanations": {"若": "若：书面语连词，引出假设条件，与后面的「就」相呼应，可以填入。", "然后": "语义：「然后」表示先后顺序，不表示假设，「然后明天下雨」不成立。", "虽然": "语义：「虽然」表示让步，通常与后文的转折相呼应；此句「就不去公园了」是顺承，前后不构成让步，不能引出假设。", "而且": "语义：「而且」表示递进或并列，不引出假设条件，「而且明天下雨」不成立。"}, "sentence_index": 0, "correct_answer": "若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次我们若取得了胜利，都是大家共同努力的结果。", "explanation": "这里应该用〈由于〉或〈因为〉。若表示假设，不能用来说明已经取得的结果是由什么原因造成的。"}, {"text": "天气很冷，若我们就不出门了。", "explanation": "这里应该用〈所以〉。若表示假设，不能用来表示已经发生的结果。"}, {"text": "他若有很多钱，所以买了一套房子。", "explanation": "这里应该用〈因为〉。若表示假设，不能引出已经发生的原因，与「所以」搭配也前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "若", "is_correct": true, "explanation": "若：ruò（第四声），连词，意思是如果。"}, {"text": "锐", "is_correct": false, "explanation": "ruì（第四声）与 ruò 韵母不同（ui 与 uo），意思是锐利。"}, {"text": "挪", "is_correct": false, "explanation": "nuó（第二声）与 ruò 声母不同（n 与 r），声调也不同，意思是挪动。"}, {"text": "入", "is_correct": false, "explanation": "rù（第四声）与 ruò 韵母不同（u 与 uo），声调相同，意思是进入。"}, {"text": "落", "is_correct": false, "explanation": "luò（第四声）与 ruò 声母不同（l 与 r），声调相同，意思是落下。"}], "explanations": {"若": "若：ruò（第四声），连词，意思是如果。", "锐": "ruì（第四声）与 ruò 韵母不同（ui 与 uo），意思是锐利。", "挪": "nuó（第二声）与 ruò 声母不同（n 与 r），声调也不同，意思是挪动。", "入": "rù（第四声）与 ruò 韵母不同（u 与 uo），声调相同，意思是进入。", "落": "luò（第四声）与 ruò 声母不同（l 与 r），声调相同，意思是落下。"}, "sentence_index": null, "correct_answer": "若"}, "level_3": {"options": [{"text": "若", "is_correct": true, "explanation": "若：书面语连词，引出假设，与后面的「就」相呼应，可以填入。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果结果，句首没有前因，不能引出假设条件，「因此路上堵车」不成立。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，句中前后没有对立，「但是路上堵车」不成立。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：「然而」需要承接前文的转折，放在句首单独引出「路上堵车」，语意不通。"}], "explanations": {"若": "若：书面语连词，引出假设，与后面的「就」相呼应，可以填入。", "因此": "语义：「因此」表示因果结果，句首没有前因，不能引出假设条件，「因此路上堵车」不成立。", "但是": "语义：「但是」表示转折，句中前后没有对立，「但是路上堵车」不成立。", "然而": "搭配：「然而」需要承接前文的转折，放在句首单独引出「路上堵车」，语意不通。"}, "sentence_index": 6, "correct_answer": "若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去了超市，若买了一些水果，就回家了。", "explanation": "这里应该用〈然后〉。若表示假设，不能用来表示动作的先后顺序。"}, {"text": "他看起来很年轻，若已经四十岁了。", "explanation": "这里应该用〈其实〉。若表示假设，不能用来说明实际情况。"}, {"text": "他学习很努力，若成绩却很差。", "explanation": "这里应该用〈但是〉。若表示假设，不能引出与前文相反的转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你若有空，若就来帮忙吧。", "corrected_sentence": "你若有空，就来帮忙吧。", "error_description": "错误：「若」在条件分句「你若有空」之后又多写了一个，主句「就来帮忙」前写成「若就来帮忙」。正确写法是「你若有空，就来帮忙吧」，主句前不需要再加「若」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "是若路上下雨，我们就坐车去。", "corrected_sentence": "若是路上下雨，我们就坐车去。", "error_description": "错误：「是」放在了「若」前面，写成「是若」。正确写法是「若是」，「若是」是固定的假设说法，「是」必须紧跟在「若」后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
