INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家长是小朋友的爸爸妈妈。", "primary_collocate": null, "pronunciation": "jiā zhǎng", "ipa": "tɕja˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小明的家长今天来接他回家。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园门口站着很多家长。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长们都想让孩子吃得好一点。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友的家长常常给老师送水果。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天幼儿园请家长来，爸爸妈妈都要来。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位家长很爱孩子，每天陪他玩。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子画了画，家长高兴地拍了照片。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长们在教室外面等孩子下课。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是小朋友的家长，常来幼儿园帮忙。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好家长要多听孩子说话。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家長", "label": "繁体"}, {"form": "家长们", "label": "复数"}, {"form": "家长会", "label": "复合"}], "register": "中性", "sense_fingerprint": "小朋友的爸爸妈妈，常在幼儿园和学校出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67a56d63-f4af-48ab-bef5-25a06a44575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家长", "is_correct": true, "explanation": "正确：“来接……回家”的人是孩子的父母或监护人，与“小明的家长”相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能来接小朋友回家。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物件，不能来接人回家。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“来接……回家”的主语应是人，“作业”不能作为接人的主语。"}], "explanations": {"家长": "正确：“来接……回家”的人是孩子的父母或监护人，与“小明的家长”相符。", "小狗": "语义：小狗不能来接小朋友回家。", "书包": "语义：书包是物件，不能来接人回家。", "作业": "搭配：“来接……回家”的主语应是人，“作业”不能作为接人的主语。"}, "sentence_index": 0, "correct_answer": "家长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的家长每天给学生上数学课。", "explanation": "语义：“家长”指小朋友的爸爸妈妈，不是给学生上课的老师。这里应该用〈老师〉。"}, {"text": "我的家长昨天考试得了第一名。", "explanation": "语义：“考试”的参与者是学生，家长不参加考试，这里的“家长”不能作考生。"}, {"text": "门口站着一棵家长。", "explanation": "这里应该用〈位〉。“棵”用于树木，人用“位”或“个”，不用“棵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家长", "is_correct": true, "explanation": "正确：“拍照片”的主体是人，家长高兴地给孩子的画拍了照。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是物件，不能拍照片，也不能“高兴地”行动。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能拍照片，也不会“高兴地”行动。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“高兴地拍了照片”的主语应是人，“树叶”不能作为拍照的主语。"}], "explanations": {"家长": "正确：“拍照片”的主体是人，家长高兴地给孩子的画拍了照。", "花瓶": "语义：花瓶是物件，不能拍照片，也不能“高兴地”行动。", "天空": "语义：天空不能拍照片，也不会“高兴地”行动。", "树叶": "搭配：“高兴地拍了照片”的主语应是人，“树叶”不能作为拍照的主语。"}, "sentence_index": 6, "correct_answer": "家长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我工作以后，我的家长每周都打电话来问候我。", "explanation": "这里应该用〈父母〉。“家长”专指孩子的父母或监护人，成年人谈自己的父母一般说“父母”。"}, {"text": "我成年以后，我的家长每天都去公园跳舞。", "explanation": "这里应该用〈父母〉。“家长”指孩子的监护人，成年人谈自己的父母时说“父母”。"}, {"text": "我成年以后，我的家长在公司里开会。", "explanation": "这里应该用〈父母〉。成年人的父母不是孩子的监护人，这里应说“父母”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼儿园的家长都们来开会了。", "corrected_sentence": "幼儿园的家长们都来开会了。", "error_description": "复数错误：“家长们”的“们”应紧跟“家长”，写成“家长们都”；“家长都们”中“们”的位置错误，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校请三位家长们来开会。", "corrected_sentence": "学校请三位家长来开会。", "error_description": "“们”不能与数量词连用，应说“三位家长”，不能说“三位家长们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
