INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "子女的父母或其他监护人。", "primary_collocate": null, "pronunciation": "jiā zhǎng", "ipa": "tɕja˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷是孩子的家长，每天送他上学。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子没有父母，奶奶是他的家长。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请每位家长在表上写名字。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长要在文件上签字。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，老师请家长留下来。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家长住在外地，不能来学校。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个家长都应该关心孩子的学习。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病了，老师马上给家长打电话。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请让家长看看你的成绩单。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校通知家长，下周不上课。", "target_word": "家长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家長", "label": "繁体"}, {"form": "家长会", "label": "复合"}], "register": "中性", "sense_fingerprint": "孩子的父母或其他监护人，负责孩子的事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67a56d63-f4af-48ab-bef5-25a06a44575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家长", "is_correct": true, "explanation": "正确：“爷爷”作为孩子的监护人，承担送孩子上学的责任，与“家长”的定义相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在校学习的人，爷爷不是孩子的学生。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”指同龄同校的人，爷爷与孩子的年龄不相符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“是孩子的”后应接指人的名词，“作业”不能指人，也不能送孩子上学。"}], "explanations": {"家长": "正确：“爷爷”作为孩子的监护人，承担送孩子上学的责任，与“家长”的定义相符。", "学生": "语义：“学生”指在校学习的人，爷爷不是孩子的学生。", "同学": "语义：“同学”指同龄同校的人，爷爷与孩子的年龄不相符。", "作业": "搭配：“是孩子的”后应接指人的名词，“作业”不能指人，也不能送孩子上学。"}, "sentence_index": 0, "correct_answer": "家长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师是学生的家长。", "explanation": "语义：老师不是学生的父母或监护人，不能称为学生的家长。这里应该说“学生的老师”。"}, {"text": "学校门口站着一只家长。", "explanation": "这里应该用〈位〉。“只”多用于动物或成对器官，人用“位”或“个”，不用“只”。"}, {"text": "我们医院的家长每天给病人看病。", "explanation": "语义：“家长”指子女的父母或监护人，不是给病人看病的医生。这里应该用〈医生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家长", "is_correct": true, "explanation": "正确：“关心孩子的学习”的主体应是孩子的父母或监护人，与“每个家长”相符。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是物件，不能关心孩子的学习。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能关心孩子的学习。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“关心”需要指人的主语，“房子”不能作“关心”的主语。"}], "explanations": {"家长": "正确：“关心孩子的学习”的主体应是孩子的父母或监护人，与“每个家长”相符。", "家具": "语义：家具是物件，不能关心孩子的学习。", "窗户": "语义：窗户是物件，不能关心孩子的学习。", "房子": "搭配：“关心”需要指人的主语，“房子”不能作“关心”的主语。"}, "sentence_index": 6, "correct_answer": "家长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个家长今年才三岁，还不会走路。", "explanation": "语义：“家长”指子女的父母或监护人，不是三岁还不会走路的孩子。这里应该用〈孩子〉。"}, {"text": "我们班的家长每天都在考试。", "explanation": "语义：“考试”的参与者是学生，家长不参加考试，这里的“家长”不能作考生。"}, {"text": "这个家长每天要玩积木，不会写字。", "explanation": "语义：“家长”指子女的父母或监护人，不是玩积木、不会写字的小孩。这里应该用〈孩子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校请两位家长们在表上写名字。", "corrected_sentence": "学校请两位家长在表上写名字。", "error_description": "“们”不能与数量词连用，应说“两位家长”，不能说“两位家长们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校请每家长来参加会议。", "corrected_sentence": "学校请每位家长来参加会议。", "error_description": "量词缺失：“每”后要用量词“位”，应说“每位家长”；“每家长”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2428a259-5675-47b3-9d7e-8992fe0d86d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
