INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86779, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意外是出乎意料、没有想到的，令人吃惊。", "primary_collocate": null, "pronunciation": "yì wài", "ipa": "i˥˩ wai̯˥˩", "syllable_count": 2, "sentences": [{"text": "这个意外的消息让大家很激动。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "这场意外的大雨让比赛暂停了。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "这是一个意外的发现，大家都很惊喜。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "在机场遇到一个意外的好消息，我很开心。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "比赛结果太意外了。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "他的回答很意外，没人想到。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "那次意外的成功让他有点骄傲。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "这场意外的胜利让全队都很兴奋。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "他这次考试的意外高分，让老师很惊喜。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}, {"text": "这位意外的访客让我很惊讶。", "target_word": "意外", "complexity_tier": "T3", "furigana": "yì wài", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "意外：出乎意料，没想到，令人吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86779, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。意外（yì wài）指没想到、出乎意料。"}, {"text": "以外", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，“以外”指某个范围之外。"}, {"text": "意味", "is_correct": false, "explanation": "wèi 与 wài 韵母不同（ei 与 ai），“意味”指含义、意思。"}, {"text": "义卖", "is_correct": false, "explanation": "mài 与 wài 声母不同，“义卖”指为公益而卖东西募款。"}, {"text": "地外", "is_correct": false, "explanation": "dì 与 yì 声母不同，“地外”指地球以外，如“地外文明”。"}], "explanations": {"意外": "正确。意外（yì wài）指没想到、出乎意料。", "以外": "yǐ（第三声）与 yì（第四声）声调不同，“以外”指某个范围之外。", "意味": "wèi 与 wài 韵母不同（ei 与 ai），“意味”指含义、意思。", "义卖": "mài 与 wài 声母不同，“义卖”指为公益而卖东西募款。", "地外": "dì 与 yì 声母不同，“地外”指地球以外，如“地外文明”。"}, "sentence_index": null, "correct_answer": "意外"}, "level_3": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。“意外”修饰“消息”，指出乎意料的消息，与“大家很激动”搭配。"}, {"text": "平静", "is_correct": false, "explanation": "语义：“平静”与“激动”意思相反，平静的消息不会让大家激动。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多修饰环境或人，不修饰“消息”。"}, {"text": "乏味", "is_correct": false, "explanation": "语义：“乏味”表示无趣，乏味的消息不会让大家激动。"}], "explanations": {"意外": "正确。“意外”修饰“消息”，指出乎意料的消息，与“大家很激动”搭配。", "平静": "语义：“平静”与“激动”意思相反，平静的消息不会让大家激动。", "安静": "搭配：“安静”多修饰环境或人，不修饰“消息”。", "乏味": "语义：“乏味”表示无趣，乏味的消息不会让大家激动。"}, "sentence_index": 0, "correct_answer": "意外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们按照计划，每天都会有一场意外的会议。", "explanation": "这里的“意外”表示没想到，但“按照计划，每天都会有”说明早已安排，二者矛盾。"}, {"text": "这件事早在他的意外之中，他并不吃惊。", "explanation": "这里应该用〈预料〉。“在…之中”搭配“预料”，说“在预料之中”；“意外”指没想到，不能说“在意外之中”。"}, {"text": "我昨天就知道了这个结果，这对我来说是一个意外。", "explanation": "这里误把“意外”用成〈早有预料〉的意思，但“昨天就知道”说明早有预料，应改用〈预料之中〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86779, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。意外（yì wài）指没想到、出乎意料。"}, {"text": "异味", "is_correct": false, "explanation": "wèi 与 wài 韵母不同（ei 与 ai），“异味”指奇怪的气味。"}, {"text": "系外", "is_correct": false, "explanation": "xì 与 yì 声母不同，“系外”指太阳系以外，如“系外行星”。"}, {"text": "意在", "is_correct": false, "explanation": "zài 与 wài 声母不同，“意在”指意图、目的在于。"}, {"text": "治外", "is_correct": false, "explanation": "zhì 与 yì 声母不同，“治外”多见于“治外法权”，指一国管辖范围以外。"}], "explanations": {"意外": "正确。意外（yì wài）指没想到、出乎意料。", "异味": "wèi 与 wài 韵母不同（ei 与 ai），“异味”指奇怪的气味。", "系外": "xì 与 yì 声母不同，“系外”指太阳系以外，如“系外行星”。", "意在": "zài 与 wài 声母不同，“意在”指意图、目的在于。", "治外": "zhì 与 yì 声母不同，“治外”多见于“治外法权”，指一国管辖范围以外。"}, "sentence_index": null, "correct_answer": "意外"}, "level_3": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。“意外”修饰“成功”，指出乎意料的成功，与“让他有点骄傲”相合。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”多形容质地或做工，不能修饰“成功”。"}, {"text": "可悲", "is_correct": false, "explanation": "语义：“可悲”表示令人痛心，与“骄傲”的情感相冲突。"}, {"text": "轻浮", "is_correct": false, "explanation": "搭配：“轻浮”形容人的态度，不修饰“成功”。"}], "explanations": {"意外": "正确。“意外”修饰“成功”，指出乎意料的成功，与“让他有点骄傲”相合。", "粗糙": "搭配：“粗糙”多形容质地或做工，不能修饰“成功”。", "可悲": "语义：“可悲”表示令人痛心，与“骄傲”的情感相冲突。", "轻浮": "搭配：“轻浮”形容人的态度，不修饰“成功”。"}, "sentence_index": 6, "correct_answer": "意外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天就通知了这位意外的访客，他今天会按时来。", "explanation": "这里误把“意外”用成〈预先知道〉的意思，但“意外”指没想到，与“昨天就通知”矛盾。"}, {"text": "这场比赛的结果大家早就料定了，所以大家都觉得很意外。", "explanation": "这里误把“意外”用成〈早有预料〉的意思，但“早就料定”与“没想到”矛盾，应改用〈预料之中〉。"}, {"text": "这位访客是我的老朋友，我们每周都见面，所以他的到来让我很意外。", "explanation": "这里误把“意外”用成〈习以为常〉的意思，但“意外”指没想到，与“每周都见面”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他意外的跑进了教室。", "corrected_sentence": "他意外地跑进了教室。", "error_description": "错误：“意外”修饰动词“跑进”时要用“地”，写成“的”是错误。正确：“意外地跑进了教室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个意外地电话让我很惊讶。", "corrected_sentence": "那个意外的电话让我很惊讶。", "error_description": "错误：“意外”修饰名词“电话”时要用“的”，写成“地”是错误；“地”用于修饰动词或形容词。正确：“那个意外的电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "没有料到的情况或事故。", "primary_collocate": null, "pronunciation": "yì wài", "ipa": "i˥˩ wai̯˥˩", "syllable_count": 2, "sentences": [{"text": "路上发生了一个意外。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一次意外中受了伤。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个意外，不是他的错。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防止意外，请系好安全带。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里出了意外，大家都很担心。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万一有意外，请马上打电话给我。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次意外让他失去了一条腿。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场意外发生得太快了。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机说，这只是个小意外。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不幸在意外中去世了。", "target_word": "意外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "意外：没有料到的不幸事件，事故", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。意外（yì wài）指不幸的事故。"}, {"text": "以外", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，“以外”指某个范围之外。"}, {"text": "意味", "is_correct": false, "explanation": "wèi 与 wài 韵母不同（ei 与 ai），“意味”指含义、意思。"}, {"text": "义卖", "is_correct": false, "explanation": "mài 与 wài 声母不同，“义卖”指为公益而卖东西募款。"}, {"text": "地外", "is_correct": false, "explanation": "dì 与 yì 声母不同，“地外”指地球以外，如“地外文明”。"}], "explanations": {"意外": "正确。意外（yì wài）指不幸的事故。", "以外": "yǐ（第三声）与 yì（第四声）声调不同，“以外”指某个范围之外。", "意味": "wèi 与 wài 韵母不同（ei 与 ai），“意味”指含义、意思。", "义卖": "mài 与 wài 声母不同，“义卖”指为公益而卖东西募款。", "地外": "dì 与 yì 声母不同，“地外”指地球以外，如“地外文明”。"}, "sentence_index": null, "correct_answer": "意外"}, "level_3": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。“意外”指不幸的事故，可以在路上发生。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“风景”不能与“发生”搭配，路上发生的应是事件。"}, {"text": "节日", "is_correct": false, "explanation": "语义：“节日”是日子，不是能在路上发生的事件。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“礼物”是物品，不会在路上“发生”。"}], "explanations": {"意外": "正确。“意外”指不幸的事故，可以在路上发生。", "风景": "搭配：“风景”不能与“发生”搭配，路上发生的应是事件。", "节日": "语义：“节日”是日子，不是能在路上发生的事件。", "礼物": "语义：“礼物”是物品，不会在路上“发生”。"}, "sentence_index": 0, "correct_answer": "意外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试犯了一个意外，把题目看错了。", "explanation": "这里应该用〈错误〉。“犯”搭配“错误”，“意外”指没料到的情况或事故，不能说“犯意外”。"}, {"text": "他随口开了一个意外，大家都笑了。", "explanation": "这里应该用〈玩笑〉。“开”搭配“玩笑”，“意外”指没料到的情况或事故，不能说“开意外”。"}, {"text": "我们按计划每天都会安排一次意外。", "explanation": "这里误把“意外”用成〈惊喜〉的意思，但它指没料到的情况或事故，不能按计划安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。意外（yì wài）指不幸的事故。"}, {"text": "异味", "is_correct": false, "explanation": "wèi 与 wài 韵母不同（ei 与 ai），“异味”指奇怪的气味。"}, {"text": "系外", "is_correct": false, "explanation": "xì 与 yì 声母不同，“系外”指太阳系以外，如“系外行星”。"}, {"text": "意在", "is_correct": false, "explanation": "zài 与 wài 声母不同，“意在”指意图、目的在于。"}, {"text": "治外", "is_correct": false, "explanation": "zhì 与 yì 声母不同，“治外”多见于“治外法权”，指一国管辖范围以外。"}], "explanations": {"意外": "正确。意外（yì wài）指不幸的事故。", "异味": "wèi 与 wài 韵母不同（ei 与 ai），“异味”指奇怪的气味。", "系外": "xì 与 yì 声母不同，“系外”指太阳系以外，如“系外行星”。", "意在": "zài 与 wài 声母不同，“意在”指意图、目的在于。", "治外": "zhì 与 yì 声母不同，“治外”多见于“治外法权”，指一国管辖范围以外。"}, "sentence_index": null, "correct_answer": "意外"}, "level_3": {"options": [{"text": "意外", "is_correct": true, "explanation": "正确。“意外”指不幸的事故，能造成失去肢体的后果。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是好事，不会让人失去一条腿。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”不会造成身体伤残。"}, {"text": "荣誉", "is_correct": false, "explanation": "配价：“让……失去一条腿”需要一个事件作致因，“荣誉”不能充当这样的致因。"}], "explanations": {"意外": "正确。“意外”指不幸的事故，能造成失去肢体的后果。", "奖励": "语义：“奖励”是好事，不会让人失去一条腿。", "表扬": "语义：“表扬”不会造成身体伤残。", "荣誉": "配价：“让……失去一条腿”需要一个事件作致因，“荣誉”不能充当这样的致因。"}, "sentence_index": 6, "correct_answer": "意外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真地复习了一个意外，考试成绩很好。", "explanation": "这里应该用〈功课〉。“复习”的对象是功课，“意外”指没料到的情况或事故，不能复习。"}, {"text": "这次旅行的路线是我们精心设计的，每一站都有一次意外。", "explanation": "这里误把“意外”用成〈巧遇〉的意思，但它指没料到的情况或事故，与“精心设计”的路线矛盾。"}, {"text": "他对这个意外感到很满足。", "explanation": "这里应该用〈结局〉。“意外”指没料到的情况或事故，不能说对它感到满足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是一只意外，幸好没人受伤。", "corrected_sentence": "那是一场意外，幸好没人受伤。", "error_description": "错误：“意外”作名词时应用量词“场”，写成“只”是错误，“只”用于动物等。正确：“一场意外”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在那条意外中受了伤。", "corrected_sentence": "他在那场意外中受了伤。", "error_description": "错误：“意外”作名词时应用量词“场”或“次”，“条”用于细长的东西，不能修饰“意外”。正确：“那场意外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "唯一是只有一个，没有别的。", "primary_collocate": null, "pronunciation": "wéi yī", "ipa": "wei˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "这是我唯一的手机。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是我唯一的朋友。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学好汉语的唯一办法是多说。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是他唯一一次迟到。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈是家里唯一会做饭的人。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店是小镇上唯一的商店。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我唯一担心的是你的身体。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把唯一的一张票给了我。", "target_word": "唯一", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天是我唯一能休息的一天。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路是去山顶唯一的路。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "唯一的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "数量上只有一个，没有其他选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "唯一", "is_correct": true, "explanation": "唯一（wéi yī）是目标词，意思是只有一个，没有别的。"}, {"text": "卫衣", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，卫衣指一种带帽子的上衣，意思不同。"}, {"text": "位移", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）、yí（第二声）与 yī（第一声）声调都不同，位移指位置的变化。"}, {"text": "尾翼", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）、yì（第四声）与 yī（第一声）声调都不同，尾翼指飞机尾部的翼片。"}], "explanations": {"唯一": "唯一（wéi yī）是目标词，意思是只有一个，没有别的。", "卫衣": "wèi（第四声）与 wéi（第二声）声调不同，卫衣指一种带帽子的上衣，意思不同。", "位移": "wèi（第四声）与 wéi（第二声）、yí（第二声）与 yī（第一声）声调都不同，位移指位置的变化。", "尾翼": "wěi（第三声）与 wéi（第二声）、yì（第四声）与 yī（第一声）声调都不同，尾翼指飞机尾部的翼片。"}, "sentence_index": null, "correct_answer": "唯一"}, "level_3": {"options": [{"text": "公共", "is_correct": false, "explanation": "语义：“公共”指属于大家的东西，与“我的”表示的专属关系相矛盾。"}, {"text": "唯一", "is_correct": true, "explanation": "“唯一”表示只有一个，填入后意思是“我只有这一部手机”，符合语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的外形，不能用来形容手机。"}, {"text": "集体", "is_correct": false, "explanation": "搭配：“集体”修饰大家共有的事物，不能与“我的”搭配。"}], "explanations": {"公共": "语义：“公共”指属于大家的东西，与“我的”表示的专属关系相矛盾。", "唯一": "“唯一”表示只有一个，填入后意思是“我只有这一部手机”，符合语境。", "高大": "体貌：“高大”形容人或建筑的外形，不能用来形容手机。", "集体": "搭配：“集体”修饰大家共有的事物，不能与“我的”搭配。"}, "sentence_index": 0, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校有很多唯一的学生。", "explanation": "这里应该用〈各不相同的〉。唯一表示只有一个，不能与表示多数的“很多”一起修饰“学生”；说许多学生各有特点时用〈各不相同的〉。"}, {"text": "这几个孩子都是唯一的学生。", "explanation": "这里应该用〈各不相同〉。唯一表示只有一个，不能用于几个人同时作主语；说几个人各有特点时用〈各不相同〉。"}, {"text": "这三张照片都是唯一的底片。", "explanation": "这里应该用〈都是正确的〉。唯一表示只有一个，与“这三张”的多数相矛盾；说几样东西都符合要求时用〈都是正确的〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共同", "is_correct": false, "explanation": "搭配：“共同”要求多个主体一起做某事，而句子的主语是“我”一个人，不能搭配。"}, {"text": "唯一", "is_correct": true, "explanation": "“唯一”表示只有这一件事让我担心，与后面“担心的是你的身体”相合，符合语境。"}, {"text": "分别", "is_correct": false, "explanation": "搭配：“分别”强调各自去做，需要多个主体，与单独的“我”不搭配。"}, {"text": "特此", "is_correct": false, "explanation": "语域：“特此”是公文或通知中的书面用语，不适用于口语中的表达。"}], "explanations": {"共同": "搭配：“共同”要求多个主体一起做某事，而句子的主语是“我”一个人，不能搭配。", "唯一": "“唯一”表示只有这一件事让我担心，与后面“担心的是你的身体”相合，符合语境。", "分别": "搭配：“分别”强调各自去做，需要多个主体，与单独的“我”不搭配。", "特此": "语域：“特此”是公文或通知中的书面用语，不适用于口语中的表达。"}, "sentence_index": 6, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好几位同学是唯一的班长。", "explanation": "这里应该用〈同为〉。唯一表示只有一个，不能与“好几位”这样的多人搭配；说几个人同任一个职务时用〈同为〉。"}, {"text": "班里的同学都是唯一的男生。", "explanation": "这里应该用〈各是〉。唯一表示只有一个，不能用来说多人都是“唯一”的；说每个人各属其类时用〈各是〉。"}, {"text": "我们班唯一的同学都到了。", "explanation": "这里应该用〈全部〉。唯一表示只有一个，与“都到了”的多数矛盾；说全班同学都到齐时用〈全部〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是他很唯一的梦想。", "corrected_sentence": "这是他唯一的梦想。", "error_description": "“唯一”表示只有一个，是区别词，前面不能加程度副词“很”；正确说法是“这是他唯一的梦想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是学校里唯一个图书馆。", "corrected_sentence": "这是学校里唯一的图书馆。", "error_description": "“唯一”修饰名词时要用结构助词“的”，不能用量词“个”；正确说法是“唯一的图书馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
