INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86782, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只有一个的；独一无二的。", "primary_collocate": null, "pronunciation": "wéi yī", "ipa": "wei˧˥ i˥", "syllable_count": 2, "sentences": [{"text": "这是世界上唯一的一幅画。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是班里唯一的男生。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是我们学校唯一的获奖者。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子是爷爷奶奶唯一的孙子。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是河上唯一的桥。", "target_word": "唯一", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她是公司里唯一的女经理。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是爸爸留给我唯一的礼物。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他唯一的爱好就是看书。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是我认识的唯一的外国人。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试，他是唯一拿到满分的人。", "target_word": "唯一", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "唯一的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "同类中仅此一个，独一无二", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "众多", "is_correct": false, "explanation": "语义：“众多”说数量很多，与“一幅”的单数形式矛盾。"}, {"text": "唯一", "is_correct": true, "explanation": "“唯一”表示同类中只有这一幅，与“世界上”的范围相合，符合语境。"}, {"text": "大量", "is_correct": false, "explanation": "搭配：“大量”修饰数量很大的事物，不能与“一幅”搭配。"}, {"text": "相同", "is_correct": false, "explanation": "语义：“相同”需要两个或以上的对象相比，不能只指“一幅画”。"}], "explanations": {"众多": "语义：“众多”说数量很多，与“一幅”的单数形式矛盾。", "唯一": "“唯一”表示同类中只有这一幅，与“世界上”的范围相合，符合语境。", "大量": "搭配：“大量”修饰数量很大的事物，不能与“一幅”搭配。", "相同": "语义：“相同”需要两个或以上的对象相比，不能只指“一幅画”。"}, "sentence_index": 0, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几个孩子都是爷爷奶奶唯一的孙子。", "explanation": "这里应该用〈的〉代替〈唯一〉。唯一表示同类中仅此一个，几个孩子不可能各自都是同一对老人的唯一孙子；说几人同为一对老人的孙子时用〈的〉。"}, {"text": "班里有很多唯一的男生。", "explanation": "这里应该用〈各不相同〉。唯一表示只有一个，不能与“很多”一起修饰“男生”；说许多男生各有特点时用〈各不相同〉。"}, {"text": "这三位老师都是唯一的班主任。", "explanation": "这里应该用〈都担任〉。唯一表示只有一个，与“这三位”的多数矛盾；说几位老师都担任某一职务时用〈都担任〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共有", "is_correct": false, "explanation": "语义：“共有”指大家一起拥有，与“留给我”表示只属于我的礼物相矛盾。"}, {"text": "唯一", "is_correct": true, "explanation": "“唯一”表示只有这一份礼物是爸爸留给我的，符合语境。"}, {"text": "集体", "is_correct": false, "explanation": "搭配：“集体”修饰大家共有的事物，不能用来修饰留给个人的礼物。"}, {"text": "公共", "is_correct": false, "explanation": "语义：“公共”指属于大家的，与“留给我”表示的个人归属相矛盾。"}], "explanations": {"共有": "语义：“共有”指大家一起拥有，与“留给我”表示只属于我的礼物相矛盾。", "唯一": "“唯一”表示只有这一份礼物是爸爸留给我的，符合语境。", "集体": "搭配：“集体”修饰大家共有的事物，不能用来修饰留给个人的礼物。", "公共": "语义：“公共”指属于大家的，与“留给我”表示的个人归属相矛盾。"}, "sentence_index": 6, "correct_answer": "唯一"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班同学都拿到了唯一的满分。", "explanation": "这里应该用〈同样的〉。唯一表示只有一个，与“全班同学都”的多数矛盾；说大家都得到同样的成绩时用〈同样的〉。"}, {"text": "他们三人都是唯一的满分得主。", "explanation": "这里应该用〈并列的〉。唯一表示只有一个，不能用于“三人”这样的多数；说几个人并列获奖时用〈并列的〉。"}, {"text": "这三位同学都是唯一的及格者。", "explanation": "这里应该用〈都是〉。唯一表示只有一个，与“这三位”的多数矛盾；说几位同学都符合某一条件时用〈都是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是世界上很唯一的古城。", "corrected_sentence": "这是世界上唯一的古城。", "error_description": "“唯一”是表示仅此一个的区别词，前面不能加程度副词“很”；正确说法是“这是世界上唯一的古城”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们村唯一个小学。", "corrected_sentence": "这是我们村唯一的小学。", "error_description": "“唯一”修饰名词时要用结构助词“的”，不能用量词“个”；正确说法是“唯一的小学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
