INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "没什么是说不要紧、不算什么，不必在意。", "primary_collocate": null, "pronunciation": "méi shén me", "ipa": "mei̯˧˥ ʂən˧˥ mə", "syllable_count": 3, "sentences": [{"text": "没什么，你不用担心。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说对不起，我说没什么。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小伤没什么，过几天就好了。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摔了一下没什么，别哭了。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迟到五分钟没什么大不了。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问我怎么了？没什么，只是有点累。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点困难没什么，我们能解决。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说没什么，可是脸色很不好。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没什么可怕的，我陪着你。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误没什么，下次注意就行。", "target_word": "没什么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "没什么：不要紧，不算什么，不必在意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没什么", "is_correct": true, "explanation": "正确。“没什么”表示不要紧，用于安慰对方。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，不能表示“不要紧”的安慰。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“多少”是数量疑问，不能单独作句首语表示“不要紧”。"}, {"text": "怎么", "is_correct": false, "explanation": "语义：“怎么”表示询问方式，不表示安慰。"}], "explanations": {"没什么": "正确。“没什么”表示不要紧，用于安慰对方。", "什么": "语义：“什么”是疑问代词，不能表示“不要紧”的安慰。", "多少": "搭配：“多少”是数量疑问，不能单独作句首语表示“不要紧”。", "怎么": "语义：“怎么”表示询问方式，不表示安慰。"}, "sentence_index": 0, "correct_answer": "没什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故造成了三人死亡，没什么，大家不用太在意。", "explanation": "这里的“没什么”表示〈不要紧〉，与“造成三人死亡”的严重后果矛盾，不能用来轻描淡写。"}, {"text": "这笔钱全都被偷了，没什么，你不用去报警。", "explanation": "这里的“没什么”表示〈不要紧〉，但“全都被偷了”十分严重，二者矛盾。"}, {"text": "我们班没什么同学，所以很热闹。", "explanation": "这里的“没什么”表示“没有多少”，与“很热闹”矛盾，不是“不要紧”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没什么", "is_correct": true, "explanation": "正确。“没什么”作谓语，表示困难不大。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“这点”限定困难很小，“巨大”与之矛盾。"}, {"text": "严重", "is_correct": false, "explanation": "语义：“严重”表示程度高，与“这点”矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“这点”限定困难很小，“沉重”与之矛盾。"}], "explanations": {"没什么": "正确。“没什么”作谓语，表示困难不大。", "巨大": "语义：“这点”限定困难很小，“巨大”与之矛盾。", "严重": "语义：“严重”表示程度高，与“这点”矛盾。", "沉重": "语义：“这点”限定困难很小，“沉重”与之矛盾。"}, "sentence_index": 6, "correct_answer": "没什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市没什么人，街上却非常热闹。", "explanation": "这里的“没什么”表示“没有多少”，与“非常热闹”矛盾，不是“不要紧”的意思。"}, {"text": "孩子的病情越来越重了，你却说没什么，不用去看医生。", "explanation": "这里的“没什么”表示〈不要紧〉，但“病情越来越重”十分严重，二者矛盾。"}, {"text": "书架上没什么书，因为我每天都买很多新书。", "explanation": "这里的“没什么”表示“没有多少”，与“每天都买很多新书”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这点雨不没什么，我们继续走吧。", "corrected_sentence": "这点雨没什么，我们继续走吧。", "error_description": "错误：“没什么”本身已表示否定，前面不能再加“不”，形成双重否定。正确：“这点雨没什么”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次失误很没什么，我们下次注意。", "corrected_sentence": "这次失误没什么，我们下次注意。", "error_description": "错误：“没什么”前面不能加程度副词“很”。正确：“这次失误没什么”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
