INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86793, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "通常所说的；用在名词前，引出大家这样叫的说法。", "primary_collocate": null, "pronunciation": "suǒ wèi", "ipa": "swɔ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这就是大家所谓的“幸福”。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是人们所谓的“好天气”。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的所谓“办法”，我不太明白。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这就是老师所谓的“好习惯”。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你所谓的“休息”，其实是玩手机。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们所谓的“大餐”，只是一碗面。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些就是书上所谓的“古代文化”。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓的“新方法”，其实很早就有了。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这就是现代人所谓的“慢生活”。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她所谓的“一会儿”，是两个小时。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所謂", "label": "繁体"}], "register": "书面", "sense_fingerprint": "放在名词前，引出大家这样叫的说法，所谓的……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd32340c-cb3c-465f-9316-a2d78f46c512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86793, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所谓", "is_correct": true, "explanation": "正确。“大家所谓的幸福”，引出大家这样叫的说法。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”与“幸福”的常见说法不搭，不是大家都这样叫的说法。"}, {"text": "木制", "is_correct": false, "explanation": "搭配：“木制”说的是材质，不能修饰“幸福”。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”说的是味道，不能修饰“幸福”。"}], "explanations": {"所谓": "正确。“大家所谓的幸福”，引出大家这样叫的说法。", "陌生": "语义：“陌生”与“幸福”的常见说法不搭，不是大家都这样叫的说法。", "木制": "搭配：“木制”说的是材质，不能修饰“幸福”。", "辣": "搭配：“辣”说的是味道，不能修饰“幸福”。"}, "sentence_index": 0, "correct_answer": "所谓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "所谓人都想去那里。", "explanation": "这里应该用〈所有〉。所谓表示引出要解释的说法，不表示“全部”。"}, {"text": "他所谓说了很多意见。", "explanation": "这里不能用〈所谓〉接动词。“所谓”后应接名词性说法，直接说“他说了很多意见”即可。"}, {"text": "这个小区所谓很安静。", "explanation": "这里不能用〈所谓〉作谓语。“所谓”只修饰名词，不能单独作谓语；直接说“这个小区很安静”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86793, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所谓", "is_correct": true, "explanation": "正确。“书上所谓的古代文化”，引出书上这样叫的说法。"}, {"text": "现代", "is_correct": false, "explanation": "语义：“现代”与“古代文化”矛盾，书上说的不可能是现代的古代文化。"}, {"text": "新式", "is_correct": false, "explanation": "语义：“新式”与“古代”的说法相矛盾，句意不通。"}, {"text": "电动", "is_correct": false, "explanation": "搭配：“电动”说的是动力方式，不能修饰“文化”。"}], "explanations": {"所谓": "正确。“书上所谓的古代文化”，引出书上这样叫的说法。", "现代": "语义：“现代”与“古代文化”矛盾，书上说的不可能是现代的古代文化。", "新式": "语义：“新式”与“古代”的说法相矛盾，句意不通。", "电动": "搭配：“电动”说的是动力方式，不能修饰“文化”。"}, "sentence_index": 6, "correct_answer": "所谓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天下雨了，所谓比赛取消了。", "explanation": "这里应该用〈所以〉。所谓用于引出大家这样叫的说法，不表示因果；表示结果要用“所以”。"}, {"text": "这个景色所谓很美，我们都去看了。", "explanation": "这里不能用〈所谓〉作谓语。“所谓”只修饰名词，不能单独作谓语；直接说“这个景色很美”即可。"}, {"text": "他所谓收入了很多钱，他全都存了起来。", "explanation": "这里不能用〈所谓〉接动词。“所谓”后应接名词性说法；直接说“他收入了很多钱”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86793, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这就是人们所谓地“好运气”。", "corrected_sentence": "这就是人们所谓的“好运气”。", "error_description": "错误：“所谓”后引出名词性的说法时应用“的”，“地”用于修饰动词；应说“人们所谓的‘好运气’”，“所谓地”用词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86793, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这就是大家所谓了的“好日子”。", "corrected_sentence": "这就是大家所谓的“好日子”。", "error_description": "错误：“所谓”后不能直接加“了”，应去掉“了”，说“大家所谓的‘好日子’”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
