INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86794, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用在句首，引出要加以说明的词语。", "primary_collocate": null, "pronunciation": "suǒ wèi", "ipa": "swɔ˨˩˦ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "所谓朋友，就是在你难过时陪着你的人。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓“早餐”，就是早上吃的饭。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓好习惯，就是每天都坚持做的事。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓健康，不只是身体没有病。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓“一日三餐”，指早饭、午饭和晚饭。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓成功，就是做成自己想做的事。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓安静，是指周围没有吵闹的声音。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓礼貌，就是对别人说话要客气。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓“近视”，是看不清远处的东西。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "所谓幸福，每个人的看法都不一样。", "target_word": "所谓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所謂", "label": "繁体"}], "register": "书面", "sense_fingerprint": "放在句首引出要解释的词语，所谓……就是……", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 三餐 (Zipf 3.23), 早饭 (Zipf 3.75), 午饭 (Zipf 3.85)','sentence 8 above tier T1: 3 words above tier T1 (max 2): 近视 (Zipf 3.47), 看不清 (Zipf 3.17), 远处 (Zipf 3.84)']::text[], 'cd32340c-cb3c-465f-9316-a2d78f46c512') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所谓", "is_correct": true, "explanation": "正确。“所谓”引出要解释的词语，“所谓朋友，就是……”。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”与“在你难过时陪着你”的朋友说法相矛盾，陌生人不会这样做。"}, {"text": "木制", "is_correct": false, "explanation": "搭配：“木制”说的是材质，不能修饰“朋友”。"}, {"text": "电子", "is_correct": false, "explanation": "语义：“电子”指电器类，与后文“陪着你的人”的解释不符。"}], "explanations": {"所谓": "正确。“所谓”引出要解释的词语，“所谓朋友，就是……”。", "陌生": "语义：“陌生”与“在你难过时陪着你”的朋友说法相矛盾，陌生人不会这样做。", "木制": "搭配：“木制”说的是材质，不能修饰“朋友”。", "电子": "语义：“电子”指电器类，与后文“陪着你的人”的解释不符。"}, "sentence_index": 0, "correct_answer": "所谓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到了，所谓老师生气了。", "explanation": "这里应该用〈所以〉。所谓用于引出要解释的词语，不表示因果；表示结果要用“所以”。"}, {"text": "老师所谓说话很有道理。", "explanation": "这里不能用〈所谓〉接动词。“所谓”后应接名词性说法；应说“老师所说的话很有道理”。"}, {"text": "所谓人都来了。", "explanation": "这里应该用〈所有〉。所谓表示引出要解释的说法，不表示“全部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所谓", "is_correct": true, "explanation": "正确。“所谓安静”引出对“安静”的说明，即“周围没有吵闹的声音”。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”与“安静”相反，与“没有吵闹的声音”的解释矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”与“没有吵闹”的解释矛盾，句意不通。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”说的是味道，不能修饰“安静”。"}], "explanations": {"所谓": "正确。“所谓安静”引出对“安静”的说明，即“周围没有吵闹的声音”。", "嘈杂": "语义：“嘈杂”与“安静”相反，与“没有吵闹的声音”的解释矛盾。", "热闹": "语义：“热闹”与“没有吵闹”的解释矛盾，句意不通。", "辣": "搭配：“辣”说的是味道，不能修饰“安静”。"}, "sentence_index": 6, "correct_answer": "所谓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校所谓很大。", "explanation": "这里不能用〈所谓〉作谓语。“所谓”只用于引出要解释的词语，不能单独作谓语；应说“学校很大”。"}, {"text": "他所谓交了税，钱全部没了。", "explanation": "这里不能用〈所谓〉接动词。“所谓”后应接名词性说法；应说“他交了税”。"}, {"text": "我所谓喜欢看书，家里的书很多。", "explanation": "这里不能用〈所谓〉接动词。指我喜欢的书应说“我所喜欢的书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "所谓地快乐，就是和家人在一起。", "corrected_sentence": "所谓的快乐，就是和家人在一起。", "error_description": "错误：“所谓”后引出名词性的词语时应用“的”，“地”用于修饰动词；应说“所谓的快乐”，“所谓地快乐”用词错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "所谓诚实的，就是说真话。", "corrected_sentence": "所谓诚实，就是说真话。", "error_description": "错误：“的”误加在“所谓”所引出的“诚实”之后，应说“所谓诚实”（或“所谓的诚实”）；“所谓诚实的”语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7497736d-c1fa-4d89-850c-aaac63459cff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
