INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目前；眼前。", "primary_collocate": null, "pronunciation": "dāng qián", "ipa": "tɑŋ˥ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "当前的情况很好。", "target_word": "当前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当前最重要的是休息。", "target_word": "当前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要先解决当前的问题。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当前的天气不适合出去玩。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司当前最大的困难是没有钱。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "就当前来说，这个办法最好。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当前的工作太多了，我没有时间休息。", "target_word": "当前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，当前的目标是学好每天的新词。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据当前的价格，我们买不起这个房子。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当前的网络很慢，所以视频一直打不开。", "target_word": "当前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "當前", "label": "繁体"}], "register": "书面", "sense_fingerprint": "当前：目前、眼前，多修饰情况、问题、任务等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd61e82f-c8bb-4094-ae5d-76f242f3d821') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当前", "is_correct": true, "explanation": "正确：“当前”修饰“情况”，表示目前的状况。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是可以“有情况”的对象，“名字的情况很好”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不指可以好坏的状况，句子说不清是什么的情况。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“情况”通常指人、事或状态，“饼干的情况”不是常用搭配。"}], "explanations": {"当前": "正确：“当前”修饰“情况”，表示目前的状况。", "名字": "语义：“名字”不是可以“有情况”的对象，“名字的情况很好”说不通。", "颜色": "语义：“颜色”不指可以好坏的状况，句子说不清是什么的情况。", "饼干": "搭配：“情况”通常指人、事或状态，“饼干的情况”不是常用搭配。"}, "sentence_index": 0, "correct_answer": "当前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当前他不同意，现在却又同意了。", "explanation": "这里应该用〈当初〉。“当初”指过去的某个时候，与“现在却又同意了”形成对比；“当前”指现在，两个时间词都指现在，自相矛盾。"}, {"text": "当前我们住在上海，那时候很热闹。", "explanation": "这里应该用〈以前〉。“以前”指过去的一段时期，与“那时候”呼应；“当前”指现在，不能用来说过去的时期。"}, {"text": "那次事故当前发生在夜里，大家都吓坏了。", "explanation": "这里应该用〈当时〉。“当时”指过去的某个时候，与“那次事故”搭配；“当前”指现在，不能用来说过去发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当前", "is_correct": true, "explanation": "正确：“当前”修饰“工作”，表示现在正在做的工作。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”没有“工作”可言，“天空的工作太多了”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能有工作，句子不成立。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“工作”指人或机构的职责，“窗户”不说“工作”，搭配不成立。"}], "explanations": {"当前": "正确：“当前”修饰“工作”，表示现在正在做的工作。", "天空": "语义：“天空”没有“工作”可言，“天空的工作太多了”说不通。", "石头": "语义：“石头”不能有工作，句子不成立。", "窗户": "搭配：“工作”指人或机构的职责，“窗户”不说“工作”，搭配不成立。"}, "sentence_index": 6, "correct_answer": "当前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "当前这里会建一座公园，以后大家都能来玩。", "explanation": "这里应该用〈将来〉。“将来”指以后的时间，与“会建”的未来搭配；“当前”指现在，不能用来说未来的事。"}, {"text": "我们当前下个月就要搬家了。", "explanation": "这里的“当前”指现在这个时候，与“下个月”的未来时间矛盾；指未来的时间要用“将来”或“到时”。"}, {"text": "他当前去过三次北京。", "explanation": "这里应该用〈以前〉。“当前”指现在，不能与表示经历的“去过三次”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当前地最需要的是耐心。", "corrected_sentence": "当前最需要的是耐心。", "error_description": "错误：“当前地最需要的是耐心”。正确：“当前最需要的是耐心”。“当前”作状语修饰“最需要”时直接放在前面，不能用结构助词“地”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当前地价格比去年高。", "corrected_sentence": "当前的价格比去年高。", "error_description": "错误：“当前地价格比去年高”。正确：“当前的价格比去年高”。“当前”作定语修饰“价格”，要用结构助词“的”；“地”用于状语，不能用在定语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
