INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "口语中表示不满、责怪，或感叹的说法。", "primary_collocate": null, "pronunciation": "zhēn shì", "ipa": "ʈʂən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "你真是，怎么又忘了带钥匙？", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他真是，也不打个电话就走了。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真是，下雨天还要我出去买东西！", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你们真是，这么晚才告诉我。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟真是，又把水洒在地上了。", "target_word": "真是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板真是，周末还让大家来加班。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "真是，我说了多少遍，你还不听！", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你真是，开会的时候怎么玩手机？", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王真是，约好了又不来。", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说：“你真是，衣服又乱放！”", "target_word": "真是", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语中用来抱怨、责怪别人的插入语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'beeee686-f06b-4e13-8a82-9ad38d0c3894') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真是", "is_correct": true, "explanation": "“真是”读作 zhēn shì，是口语中表示责怪或感叹的说法，是目标词。"}, {"text": "真实", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，“真实”指符合事实的，意思不同。"}, {"text": "阵势", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn（第四声）声调不同，阵势指队列或局势，意思不同。"}, {"text": "正是", "is_correct": false, "explanation": "zhēn 与 zhèng 韵母不同（en 与 eng），“正是”表示恰好、确定，不表示责怪。"}], "explanations": {"真是": "“真是”读作 zhēn shì，是口语中表示责怪或感叹的说法，是目标词。", "真实": "shì（第四声）与 shí（第二声）声调不同，“真实”指符合事实的，意思不同。", "阵势": "zhēn（第一声）与 zhèn（第四声）声调不同，阵势指队列或局势，意思不同。", "正是": "zhēn 与 zhèng 韵母不同（en 与 eng），“正是”表示恰好、确定，不表示责怪。"}, "sentence_index": null, "correct_answer": "真是"}, "level_3": {"options": [{"text": "哈哈", "is_correct": false, "explanation": "语义：“哈哈”是笑声，与句子中责怪的语气相矛盾。"}, {"text": "真是", "is_correct": true, "explanation": "“真是”是口语叹词，用来表示责怪，与后面“怎么又忘了带钥匙”的语气一致。"}, {"text": "谢谢", "is_correct": false, "explanation": "搭配：“谢谢”是表示感谢的固定用语，不能用来开头责备别人。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹或赞赏，不表示责怪，与句子语气不合。"}], "explanations": {"哈哈": "语义：“哈哈”是笑声，与句子中责怪的语气相矛盾。", "真是": "“真是”是口语叹词，用来表示责怪，与后面“怎么又忘了带钥匙”的语气一致。", "谢谢": "搭配：“谢谢”是表示感谢的固定用语，不能用来开头责备别人。", "哇": "语义：“哇”表示惊叹或赞赏，不表示责怪，与句子语气不合。"}, "sentence_index": 0, "correct_answer": "真是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天真是，要去上海出差。", "explanation": "这里应该删去〈真是〉。叹词真是表示对已发生情况的不满或感叹，不能引出将来的安排。"}, {"text": "这个真是孩子又乱放东西。", "explanation": "语序错误：真是应放在主语之后，写作“这个孩子真是又乱放东西”。"}, {"text": "真是，我们班一共三十个人。", "explanation": "这里应该删去〈真是〉。叹词真是带有责怪或感叹，客观陈述人数时多余。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86810, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "真是", "is_correct": true, "explanation": "“真是”读作 zhēn shì，是口语中表示责怪的说法，是目标词。"}, {"text": "展示", "is_correct": false, "explanation": "zhēn（第一声）与 zhǎn（第三声）声调不同，“展示”指把东西呈现出来，意思不同。"}, {"text": "战士", "is_correct": false, "explanation": "zhēn（第一声）与 zhàn（第四声）声调不同，“战士”指军人，意思不同。"}, {"text": "战时", "is_correct": false, "explanation": "zhēn 与 zhàn 声调不同，shì（第四声）与 shí（第二声）也不同，“战时”指战争期间，意思不同。"}], "explanations": {"真是": "“真是”读作 zhēn shì，是口语中表示责怪的说法，是目标词。", "展示": "zhēn（第一声）与 zhǎn（第三声）声调不同，“展示”指把东西呈现出来，意思不同。", "战士": "zhēn（第一声）与 zhàn（第四声）声调不同，“战士”指军人，意思不同。", "战时": "zhēn 与 zhàn 声调不同，shì（第四声）与 shí（第二声）也不同，“战时”指战争期间，意思不同。"}, "sentence_index": null, "correct_answer": "真是"}, "level_3": {"options": [{"text": "谢谢", "is_correct": false, "explanation": "语义：“谢谢”表示感谢，与责备对方的语气相反。"}, {"text": "真是", "is_correct": true, "explanation": "“真是”放在句首表示责备，与后面“我说了多少遍，你还不听”的抱怨语气一致。"}, {"text": "嗨", "is_correct": false, "explanation": "语义：“嗨”是打招呼的用语，不能表示责备。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：“嘻嘻”是笑声，与句子中责备的语气相矛盾。"}], "explanations": {"谢谢": "语义：“谢谢”表示感谢，与责备对方的语气相反。", "真是": "“真是”放在句首表示责备，与后面“我说了多少遍，你还不听”的抱怨语气一致。", "嗨": "语义：“嗨”是打招呼的用语，不能表示责备。", "嘻嘻": "语义：“嘻嘻”是笑声，与句子中责备的语气相矛盾。"}, "sentence_index": 6, "correct_answer": "真是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的真是书包很重。", "explanation": "语序错误：真是不能插在定语“我的”与中心语“书包”之间；应写作“我的书包真是很重”。"}, {"text": "这些书真是，一共三本。", "explanation": "这里应该删去〈真是〉。叹词真是带有责怪或感叹，客观陈述数量时多余。"}, {"text": "真是，他昨天在图书馆借了三本书。", "explanation": "这里应该删去〈真是〉。叹词真是带有不满或感叹，叙述中性的已发生事实时多余。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a26ae39-df72-4ca6-8a68-7999819b31cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXC