INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86819, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "队是很多人站在一起排成的一行或一伙人。", "primary_collocate": null, "pronunciation": "duì", "ipa": "tweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "学生们站成一队，走进教室。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口排着一队人。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你站到那一队后面去。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们排成两队做游戏。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一队人走得很慢。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家排成一队，不要挤。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面有一队小朋友在唱歌。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在这一队的最后。", "target_word": "队", "complexity_tier": "T3", "furigana": "tā zhàn zài zhè yí duì de zuìhòu", "sentence_source": "generated"}, {"text": "一队士兵从街上走过。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们排成三队，每队五个人。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隊", "label": "繁体"}, {"form": "队伍", "label": "复合"}, {"form": "排队", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们站成的一行队列，或一伙走在一起的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a666923a-00f0-43ce-9ee1-f1406e0ad8d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86819, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "队", "is_correct": true, "explanation": "队：duì（第四声），意思是排成的行列或一伙人，是正确答案。"}, {"text": "堆", "is_correct": false, "explanation": "duī（第一声）与 duì（第四声）声调不同，意思是堆积。"}, {"text": "退", "is_correct": false, "explanation": "tuì 与 duì 声母不同（t 与 d），意思是后退。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 duì 声母不同（g 与 d），意思是价格高。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 duì 声母不同（s 与 d），意思是破碎。"}], "explanations": {"队": "队：duì（第四声），意思是排成的行列或一伙人，是正确答案。", "堆": "duī（第一声）与 duì（第四声）声调不同，意思是堆积。", "退": "tuì 与 duì 声母不同（t 与 d），意思是后退。", "贵": "guì 与 duì 声母不同（g 与 d），意思是价格高。", "碎": "suì 与 duì 声母不同（s 与 d），意思是破碎。"}, "sentence_index": null, "correct_answer": "队"}, "level_3": {"options": [{"text": "队", "is_correct": true, "explanation": "队：学生们站成一队，是排成的行列，是正确答案。"}, {"text": "盒", "is_correct": false, "explanation": "语义：“站成一盒”不通，盒子不能指排成行的人。"}, {"text": "瓶", "is_correct": false, "explanation": "搭配：“一瓶”不与“站成”搭配，不能指排成行的人。"}, {"text": "碗", "is_correct": false, "explanation": "语义：“站成一碗”不通，碗不能指排成行的人。"}], "explanations": {"队": "队：学生们站成一队，是排成的行列，是正确答案。", "盒": "语义：“站成一盒”不通，盒子不能指排成行的人。", "瓶": "搭配：“一瓶”不与“站成”搭配，不能指排成行的人。", "碗": "语义：“站成一碗”不通，碗不能指排成行的人。"}, "sentence_index": 0, "correct_answer": "队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一队字很长。", "explanation": "这里应该用〈行〉。队指成组站立的人或有组织的集体，不能用于一行字，应说这一行字。"}, {"text": "这一队葡萄很甜。", "explanation": "这里应该用〈串〉。队指排成行列的人或有组织的集体，不用于葡萄，应说这一串葡萄。"}, {"text": "这一队火车很长。", "explanation": "这里应该用〈列〉。队不用于火车这类排成长串的东西，应说这一列火车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86819, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "队", "is_correct": true, "explanation": "队：duì（第四声），意思是排成的行列或一伙人，是正确答案。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 duì 声母不同（h 与 d），意思是会议或会。"}, {"text": "愧", "is_correct": false, "explanation": "kuì 与 duì 声母不同（k 与 d），意思是惭愧。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 duì 声母不同（z 与 d），意思是最。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 duì 声母不同（s 与 d），意思是岁数。"}], "explanations": {"队": "队：duì（第四声），意思是排成的行列或一伙人，是正确答案。", "会": "huì 与 duì 声母不同（h 与 d），意思是会议或会。", "愧": "kuì 与 duì 声母不同（k 与 d），意思是惭愧。", "最": "zuì 与 duì 声母不同（z 与 d），意思是最。", "岁": "suì 与 duì 声母不同（s 与 d），意思是岁数。"}, "sentence_index": null, "correct_answer": "队"}, "level_3": {"options": [{"text": "队", "is_correct": true, "explanation": "队：前面有一队小朋友，指一伙人，是正确答案。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“一本”是书的量词，不能用于一群小朋友，句子不通。"}, {"text": "块", "is_correct": false, "explanation": "语义：“一块小朋友”不通，块不能指一群人。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“一把”多用于有柄的器具，不能用于小朋友，句子不通。"}], "explanations": {"队": "队：前面有一队小朋友，指一伙人，是正确答案。", "本": "搭配：“一本”是书的量词，不能用于一群小朋友，句子不通。", "块": "语义：“一块小朋友”不通，块不能指一群人。", "把": "搭配：“一把”多用于有柄的器具，不能用于小朋友，句子不通。"}, "sentence_index": 6, "correct_answer": "队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一队树很整齐。", "explanation": "这里应该用〈排〉。队不能用于树，应说这一排树很整齐。"}, {"text": "这一队歌很好听。", "explanation": "这里应该用〈首〉。队不用于歌曲，应说这一首歌很好听。"}, {"text": "这一队路很长。", "explanation": "这里应该用〈段〉。队不能用于路，应说这一段路很长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
