INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "前面走过了一把队士兵。", "corrected_sentence": "前面走过了一队士兵。", "error_description": "错误在于量词。''把''多用于有柄的器具，不能用于队伍，应说''一队士兵''。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
