INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为比赛或工作等组成的有组织的集体。", "primary_collocate": null, "pronunciation": "duì", "ipa": "tweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我们队今天赢了比赛。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红队和蓝队明天比赛。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想选哪个队？", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队只输了一分。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把我分到了黄队。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队有十个人。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队每天都练习。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个队的人都穿着白衣服。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很高兴，因为他们队赢了。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队的人比你们队多。", "target_word": "队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隊", "label": "繁体"}, {"form": "队员", "label": "复合"}, {"form": "队长", "label": "复合"}, {"form": "队伍", "label": "复合"}], "register": "中性", "sense_fingerprint": "为比赛或工作组成的有组织的集体，如我们队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a666923a-00f0-43ce-9ee1-f1406e0ad8d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "队", "is_correct": true, "explanation": "队：duì（第四声），意思是为比赛组成的有组织的集体，是正确答案。"}, {"text": "堆", "is_correct": false, "explanation": "duī（第一声）与 duì（第四声）声调不同，意思是堆积。"}, {"text": "退", "is_correct": false, "explanation": "tuì 与 duì 声母不同（t 与 d），意思是后退。"}, {"text": "贵", "is_correct": false, "explanation": "guì 与 duì 声母不同（g 与 d），意思是价格高。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 duì 声母不同（s 与 d），意思是破碎。"}], "explanations": {"队": "队：duì（第四声），意思是为比赛组成的有组织的集体，是正确答案。", "堆": "duī（第一声）与 duì（第四声）声调不同，意思是堆积。", "退": "tuì 与 duì 声母不同（t 与 d），意思是后退。", "贵": "guì 与 duì 声母不同（g 与 d），意思是价格高。", "碎": "suì 与 duì 声母不同（s 与 d），意思是破碎。"}, "sentence_index": null, "correct_answer": "队"}, "level_3": {"options": [{"text": "队", "is_correct": true, "explanation": "队：我们队今天赢了比赛，指有组织的团队，是正确答案。"}, {"text": "桌", "is_correct": false, "explanation": "语义：“桌子”不能赢得比赛，句子不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不能作为赢的主体，句子不通。"}, {"text": "椅", "is_correct": false, "explanation": "语义：椅子不能参加比赛，句子不通。"}], "explanations": {"队": "队：我们队今天赢了比赛，指有组织的团队，是正确答案。", "桌": "语义：“桌子”不能赢得比赛，句子不通。", "书": "语义：“书”不能作为赢的主体，句子不通。", "椅": "语义：椅子不能参加比赛，句子不通。"}, "sentence_index": 0, "correct_answer": "队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一队电脑很快。", "explanation": "这里应该用〈台〉。队指人或有组织的集体，不用于电脑，应说这一台电脑很快。"}, {"text": "这一队火车很长。", "explanation": "这里应该用〈列〉。队不用于火车这类排成长串的东西，应说这一列火车。"}, {"text": "这一队课很长。", "explanation": "这里应该用〈节〉。队不能用于课程，应说这一节课很长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86820, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "队", "is_correct": true, "explanation": "队：duì（第四声），意思是为比赛组成的有组织的集体，是正确答案。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 duì 声母不同（h 与 d），意思是会议或会。"}, {"text": "愧", "is_correct": false, "explanation": "kuì 与 duì 声母不同（k 与 d），意思是惭愧。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 duì 声母不同（z 与 d），意思是最。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 duì 声母不同（s 与 d），意思是岁数。"}], "explanations": {"队": "队：duì（第四声），意思是为比赛组成的有组织的集体，是正确答案。", "会": "huì 与 duì 声母不同（h 与 d），意思是会议或会。", "愧": "kuì 与 duì 声母不同（k 与 d），意思是惭愧。", "最": "zuì 与 duì 声母不同（z 与 d），意思是最。", "岁": "suì 与 duì 声母不同（s 与 d），意思是岁数。"}, "sentence_index": null, "correct_answer": "队"}, "level_3": {"options": [{"text": "队", "is_correct": true, "explanation": "队：这个队每天都练习，指有组织的团队，是正确答案。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯不会练习，句子不通。"}, {"text": "布", "is_correct": false, "explanation": "配价：“练习”需要有生命的主体，“布”不能作主语。"}, {"text": "盆", "is_correct": false, "explanation": "语义：盆不能练习，句子不通。"}], "explanations": {"队": "队：这个队每天都练习，指有组织的团队，是正确答案。", "灯": "语义：灯不会练习，句子不通。", "布": "配价：“练习”需要有生命的主体，“布”不能作主语。", "盆": "语义：盆不能练习，句子不通。"}, "sentence_index": 6, "correct_answer": "队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一队树很整齐。", "explanation": "这里应该用〈排〉。队不能用于树，应说这一排树很整齐。"}, {"text": "这一队花很漂亮。", "explanation": "这里应该用〈朵〉。队指人或有组织的集体，不用于花，应说这一朵花很漂亮。"}, {"text": "这一队路很长。", "explanation": "这里应该用〈段〉。队不能用于路，应说这一段路很长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们有一条很强的队。", "corrected_sentence": "我们有一支很强的队。", "error_description": "错误在于量词。作''球队''讲时，''队''的量词用''支''或''个''，''条''用于狭长之物，不用于球队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一把队参加了比赛。", "corrected_sentence": "我们一支队参加了比赛。", "error_description": "错误在于量词。''把''多用于有柄的器具，不能用于球队，应说''一支队''。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d9819ae-3470-4917-9d2d-1441aada02da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
