INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高中是十五六岁到十八岁的学生上的学校。", "primary_collocate": null, "pronunciation": "gāo zhōng", "ipa": "kaʊ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我哥哥在这所高中上学。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐的高中离家很近。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这所高中有一个大操场。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天骑车去高中。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的高中在山边。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那所高中的老师都很好。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐在高中里认识了好朋友。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校旁边新建了一所高中。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥带着书包走进高中。", "target_word": "高中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所高中有一千多个学生。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一所高中", "label": "量词"}, {"form": "高中生", "label": "复合"}], "register": "中性", "sense_fingerprint": "十五六岁到十八岁的学生上的学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高中", "is_correct": true, "explanation": "高中：指学校，“在这所高中上学”与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：量词“所”用于学校、医院等机构，不能与“汽车”搭配。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，不是上学的场所。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是购物场所，不能在此上学。"}], "explanations": {"高中": "高中：指学校，“在这所高中上学”与句意相符。", "汽车": "搭配：量词“所”用于学校、医院等机构，不能与“汽车”搭配。", "医院": "语义：医院是治病的地方，不是上学的场所。", "超市": "语义：超市是购物场所，不能在此上学。"}, "sentence_index": 0, "correct_answer": "高中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坐高中去上学。", "explanation": "这里应该用〈校车〉。高中指学校，不是交通工具；乘车上学要说“坐校车”。"}, {"text": "这所高中今年十八岁了。", "explanation": "这里应该用〈建校〉。学校说年数要用“建校……年”，“岁”只用于人。"}, {"text": "他拿到了高中学位。", "explanation": "这里应该用〈学历〉。高中指学校，不是学位；学位是大学及以上的学术称号，应说“高中学历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高中", "is_correct": true, "explanation": "高中：指学校，“在高中里认识了好朋友”与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是人与人交往的场所，与“认识好朋友”矛盾。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是认识朋友的地方。"}, {"text": "草莓", "is_correct": false, "explanation": "搭配：“里”后的处所须能供人交往，“草莓”不能与“认识好朋友”搭配。"}], "explanations": {"高中": "高中：指学校，“在高中里认识了好朋友”与句意相符。", "冰箱": "语义：冰箱不是人与人交往的场所，与“认识好朋友”矛盾。", "书包": "语义：书包是装东西的袋子，不是认识朋友的地方。", "草莓": "搭配：“里”后的处所须能供人交往，“草莓”不能与“认识好朋友”搭配。"}, "sentence_index": 6, "correct_answer": "高中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名高中，每天骑车上学。", "explanation": "这里应该用〈学生〉。高中指学校时不指人，不能用“一名”计量。"}, {"text": "这位高中很努力。", "explanation": "这里应该用〈高中生〉。学校不能“努力”，指人要用高中生。"}, {"text": "那个高中很聪明。", "explanation": "这里应该用〈高中生〉。高中指学校，不指人；形容人的聪明要说高中生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹这所高中读书。", "corrected_sentence": "我妹妹在这所高中读书。", "error_description": "介词缺失：表示地点的“在”不能省略，应说“在这所高中读书”，不说“这所高中读书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "县里新办了一个高中。", "corrected_sentence": "县里新办了一所高中。", "error_description": "量词错误：学校机构用量词“所”，应说“一所高中”，不说“一个高中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
