INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "初中之上的中学阶段，一般三年。", "primary_collocate": null, "pronunciation": "gāo zhōng", "ipa": "kaʊ˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "高中一般要读三年。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他初中毕业后上了高中。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高中的课比初中多。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她高中的时候喜欢画画。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "读完高中，我想去北京上大学。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高中三年过得很快。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在高中学过法语。", "target_word": "高中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高中毕业后她去工作了。", "target_word": "高中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上高中以后，我住在学校。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "高中阶段的学习很重要。", "target_word": "高中", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "高中生", "label": "复合"}, {"form": "高中毕业", "label": "复合"}], "register": "中性", "sense_fingerprint": "初中之后、一般三年的中学教育阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7ff3108-def9-4a18-b93a-70244681d64f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高中", "is_correct": true, "explanation": "高中：初中之上的学段，一般三年，与“一般要读三年”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“读”不能以“汽车”为主语，“汽车一般要读三年”不成立。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不是学习阶段，与“读三年”矛盾。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期通常只有几个月，与“三年”的时长矛盾。"}], "explanations": {"高中": "高中：初中之上的学段，一般三年，与“一般要读三年”相符。", "汽车": "搭配：“读”不能以“汽车”为主语，“汽车一般要读三年”不成立。", "春天": "语义：春天是季节，不是学习阶段，与“读三年”矛盾。", "学期": "语义：学期通常只有几个月，与“三年”的时长矛盾。"}, "sentence_index": 0, "correct_answer": "高中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名高中，每天认真学习。", "explanation": "这里应该用〈学生〉。高中指学段，不指人，不能用“一名”计量。"}, {"text": "这位高中很努力。", "explanation": "这里应该用〈高中生〉。高中指学段，不能指人，也不能作“努力”的主语。"}, {"text": "那个高中很聪明。", "explanation": "这里应该用〈高中生〉。高中指学段，不指人；形容人的聪明要说高中生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高中", "is_correct": true, "explanation": "高中：学段，“在高中学过法语”指在这一阶段学习，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是学习的场所，“在冰箱学过法语”说不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是饮品，不能作为学习的地点。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“在……学”要求场所或阶段作状语，“眼镜”不能与“学过法语”搭配。"}], "explanations": {"高中": "高中：学段，“在高中学过法语”指在这一阶段学习，与句意相符。", "冰箱": "语义：冰箱不是学习的场所，“在冰箱学过法语”说不通。", "牛奶": "语义：牛奶是饮品，不能作为学习的地点。", "眼镜": "搭配：“在……学”要求场所或阶段作状语，“眼镜”不能与“学过法语”搭配。"}, "sentence_index": 6, "correct_answer": "高中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿到了高中学位。", "explanation": "这里应该用〈学历〉。高中是学段，不是学位；学位指大学及以上的学术称号，高中毕业只说“高中学历”。"}, {"text": "他是公司的高中经理。", "explanation": "这里应该用〈高级〉。高中是学段，不表示职务等级；职务的级别要说“高级经理”。"}, {"text": "他每天高中两个小时。", "explanation": "这里应该用〈上学〉。高中是名词，指学段，不能当动词用；表示在校学习要说“上学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把高中毕业后去了上海。", "corrected_sentence": "我高中毕业后去了上海。", "error_description": "把字句误用：“毕业”是不及物动词，不能用“把”引出“高中”，应直接说“高中毕业后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他高中三个年一直住在学校。", "corrected_sentence": "他高中三年一直住在学校。", "error_description": "量词错误：“三年”作时长时中间不加量词“个”，应说“高中三年”，不说“高中三个年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabca4c6-7cc0-4a5f-9fbd-a60324832225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
