INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86825, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "且是“而且”的意思，说还有别的。", "primary_collocate": null, "pronunciation": "qiě", "ipa": "tɕʰjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这件衣服好看且舒服。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他工作认真且负责。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地方安全且干净，大家都愿意来。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲得慢且清楚，我们都听懂了。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份工作轻松且稳定。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的想法新且实用。", "target_word": "且", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个手机小且轻，带着很方便。", "target_word": "且", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年轻且有经验，大家都信她。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动有趣且有意义。", "target_word": "且", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院环境安静且干净，病人很多。", "target_word": "且", "complexity_tier": "T3", "furigana": "zhè jiā yī yuàn huán jìng ān jìng qiě gān jìng, bìng rén hěn duō.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "且：等于而且，表示还有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab628bc3-ddad-4bad-aa8a-0184cfa7bf3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：且（qiě）是连词，等于“而且”，表示还有别的意思。"}, {"text": "切", "is_correct": false, "explanation": "切（qiē，第一声）与 qiě（第三声）声调不同，意思是“切开”。"}, {"text": "写", "is_correct": false, "explanation": "写（xiě）与 qiě 声母不同（x 与 q），声调相同，意思是“写字”。"}, {"text": "企", "is_correct": false, "explanation": "企（qǐ，第三声）与 qiě 仅韵母不同（i 与 ie），声调相同，意思是“踮起脚”。"}, {"text": "解", "is_correct": false, "explanation": "解（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“了解”。"}], "explanations": {"且": "正确：且（qiě）是连词，等于“而且”，表示还有别的意思。", "切": "切（qiē，第一声）与 qiě（第三声）声调不同，意思是“切开”。", "写": "写（xiě）与 qiě 声母不同（x 与 q），声调相同，意思是“写字”。", "企": "企（qǐ，第三声）与 qiě 仅韵母不同（i 与 ie），声调相同，意思是“踮起脚”。", "解": "解（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“了解”。"}, "sentence_index": null, "correct_answer": "且"}, "level_3": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：“且”是连词，等于“而且”，连接并列的形容词“好看”和“舒服”。"}, {"text": "而是", "is_correct": false, "explanation": "语义：“而是”表示对比、否定前者，“好看”与“舒服”并不对立。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示因果，衣服好看不能推出舒服。"}, {"text": "还是", "is_correct": false, "explanation": "搭配：“还是”多用于选择式疑问句，不能连接陈述句中并列的形容词。"}], "explanations": {"且": "正确：“且”是连词，等于“而且”，连接并列的形容词“好看”和“舒服”。", "而是": "语义：“而是”表示对比、否定前者，“好看”与“舒服”并不对立。", "因而": "语义：“因而”表示因果，衣服好看不能推出舒服。", "还是": "搭配：“还是”多用于选择式疑问句，不能连接陈述句中并列的形容词。"}, "sentence_index": 0, "correct_answer": "且"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书且他借走了。", "explanation": "这里应该用〈被〉。且表示并列或递进，不能用来表示被动关系。"}, {"text": "我买了苹果，香蕉且橘子。", "explanation": "这里应该用〈和〉。且一般连接形容词或动词短语，不用来连接并列的名词。"}, {"text": "天很冷，且我穿了很多衣服。", "explanation": "这里应该用〈所以〉。且不能表示因果；“天冷”是“穿很多衣服”的原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86825, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：且（qiě）是连词，等于“而且”，表示还有别的意思。"}, {"text": "茄", "is_correct": false, "explanation": "茄（qié，第二声）与 qiě（第三声）声调不同，意思是“茄子”。"}, {"text": "怯", "is_correct": false, "explanation": "怯（qiè，第四声）与 qiě（第三声）声调不同，意思是“胆怯”。"}, {"text": "姐", "is_correct": false, "explanation": "姐（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“姐姐”。"}, {"text": "启", "is_correct": false, "explanation": "启（qǐ，第三声）与 qiě 仅韵母不同（i 与 ie），声调相同，意思是“开启”。"}], "explanations": {"且": "正确：且（qiě）是连词，等于“而且”，表示还有别的意思。", "茄": "茄（qié，第二声）与 qiě（第三声）声调不同，意思是“茄子”。", "怯": "怯（qiè，第四声）与 qiě（第三声）声调不同，意思是“胆怯”。", "姐": "姐（jiě）与 qiě 声母不同（j 与 q），声调相同，意思是“姐姐”。", "启": "启（qǐ，第三声）与 qiě 仅韵母不同（i 与 ie），声调相同，意思是“开启”。"}, "sentence_index": null, "correct_answer": "且"}, "level_3": {"options": [{"text": "且", "is_correct": true, "explanation": "正确：“且”是连词，等于“而且”，连接并列的形容词“小”和“轻”，符合语境。"}, {"text": "或", "is_correct": false, "explanation": "语义：“或”表示选择，“手机小”与“手机轻”不是二选一的关系。"}, {"text": "况且", "is_correct": false, "explanation": "搭配：“况且”用于补充理由，连接分句，不直接连接并列的形容词。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，手机小不能推出轻。"}], "explanations": {"且": "正确：“且”是连词，等于“而且”，连接并列的形容词“小”和“轻”，符合语境。", "或": "语义：“或”表示选择，“手机小”与“手机轻”不是二选一的关系。", "况且": "搭配：“况且”用于补充理由，连接分句，不直接连接并列的形容词。", "所以": "语义：“所以”表示因果，手机小不能推出轻。"}, "sentence_index": 6, "correct_answer": "且"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不是老板，且是经理。", "explanation": "这里应该用〈而是〉。且只表示递进，不能表示否定前者、转而肯定后者的对比关系。"}, {"text": "天黑了，且我们回家了。", "explanation": "这里应该用〈所以〉。且不能表示因果；“天黑”是“回家”的原因。"}, {"text": "如果明天下雨，我们且取消野餐。", "explanation": "这里应该用〈就〉。且不能用于假设条件的结果句，“如果……就……”的结果要用〈就〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子干净的且明亮。", "corrected_sentence": "这间屋子干净且明亮。", "error_description": "错误形式：“且”前多加了“的”。正确形式：“且”直接连接并列的形容词“干净”和“明亮”，中间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包便宜且都结实。", "corrected_sentence": "这个包便宜且结实。", "error_description": "错误形式：“且都”。正确形式：“且”直接连接并列的形容词“便宜”和“结实”，中间不能加副词“都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
