INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可怕是让人心里害怕。", "primary_collocate": null, "pronunciation": "kě pà", "ipa": "kʰɤ˨˩˦ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影太可怕了，我看了一半就关了。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚黑得可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一个可怕的鬼故事。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别怕，那只狗其实不可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震是一件非常可怕的事。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的战争让人觉得可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最可怕的不是黑夜，而是一个人。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到可怕的画面，她马上闭上了眼睛。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路上车很多，开起来真可怕。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个老人的眼神很可怕，我不敢看他。", "target_word": "可怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "可怕：形容词，让人心里害怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd61e82f-c8bb-4094-ae5d-76f242f3d821') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好看", "is_correct": false, "explanation": "语义：“好看”说影片精彩，与后一句“看了一半就关了”的意思相矛盾。"}, {"text": "可怕", "is_correct": true, "explanation": "“可怕”说电影让人害怕，正好解释了为什么看了一半就关了，是原句的词。"}, {"text": "体贴", "is_correct": false, "explanation": "搭配：“体贴”形容人待人细心周到，不能用来形容电影。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材体形，电影没有身材，不能这样说。"}], "explanations": {"好看": "语义：“好看”说影片精彩，与后一句“看了一半就关了”的意思相矛盾。", "可怕": "“可怕”说电影让人害怕，正好解释了为什么看了一半就关了，是原句的词。", "体贴": "搭配：“体贴”形容人待人细心周到，不能用来形容电影。", "高大": "体貌：“高大”形容人或物的身材体形，电影没有身材，不能这样说。"}, "sentence_index": 0, "correct_answer": "可怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到雷声，我很可怕。", "explanation": "这里应该用〈害怕〉。“可怕”说事物让人害怕，不能用来说“我”心里害怕。"}, {"text": "这碗面很可怕，我吃了两碗。", "explanation": "这里应该用〈可口〉。面条不会令人害怕，形容味道好要用“可口”。"}, {"text": "这个笑话很可怕，大家都笑了。", "explanation": "这里应该用〈可笑〉。笑话不会令人害怕，引人发笑的要说“可笑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”说光线充足，与“最……的不是黑夜”的语境正好相反。"}, {"text": "可怕", "is_correct": true, "explanation": "“可怕”指令人害怕，与“黑夜”和“一个人”的语境相符，是原句的词。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说排列或衣着有条理，不能用来形容黑夜。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：“精致”说器物或工艺做得细巧，不能用来形容黑夜。"}], "explanations": {"明亮": "语义：“明亮”说光线充足，与“最……的不是黑夜”的语境正好相反。", "可怕": "“可怕”指令人害怕，与“黑夜”和“一个人”的语境相符，是原句的词。", "整齐": "搭配：“整齐”说排列或衣着有条理，不能用来形容黑夜。", "精致": "搭配：“精致”说器物或工艺做得细巧，不能用来形容黑夜。"}, "sentence_index": 6, "correct_answer": "可怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份友谊很可怕，我一直很珍惜。", "explanation": "这里应该用〈可贵〉。友谊不会令人害怕，值得珍惜要说“可贵”。"}, {"text": "这个做法很可怕，值得大家学习。", "explanation": "这里应该用〈可取〉。做法不会令人害怕，值得采用、效仿要说“可取”。"}, {"text": "那个生病的孩子真可怕，我很同情他。", "explanation": "这里应该用〈可怜〉。“可怕”指令人害怕，生病的孩子只让人同情，应说“可怜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那次地震太可怕的，大家都跑出了房子。", "corrected_sentence": "那次地震太可怕了，大家都跑出了房子。", "error_description": "“太……了”的“了”不能换成“的”。错误写法是“太可怕的”，后面没有被修饰的名词，正确写法是“太可怕了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里那片可怕地树林，我们绕着走了。", "corrected_sentence": "夜里那片可怕的树林，我们绕着走了。", "error_description": "“可怕”修饰名词“树林”时要用“的”，不能用“地”。“地”只用在动词前。错误写法是“可怕地树林”，正确写法是“可怕的树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
