INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "女生是在学校里读书的女孩。", "primary_collocate": null, "pronunciation": "nǚ shēng", "ipa": "nɥy˨˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "我妹妹是一名高中女生。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女生的成绩总是全班第一。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，女生都很认真。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的女生坐在我前面。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个女生背着一个红色的书包。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是个女生，今年才十五岁。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球场上有几个女生在打球。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女生很爱笑，同学们都喜欢她。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女生比男生早到教室。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让女生站在左边，男生站在右边。", "target_word": "女生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女生们", "label": "复数"}], "register": "中性", "sense_fingerprint": "女生：在学校里读书的女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46f86a8e-c93b-4cfe-95df-f413bcbe6177') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女生", "is_correct": true, "explanation": "女生指在学校里读书的女孩，与“我妹妹是一名高中”相符。"}, {"text": "女护士", "is_correct": false, "explanation": "语义：护士在医院工作，“高中女护士”与学校的语境不符。"}, {"text": "女同志", "is_correct": false, "explanation": "语域：“女同志”是较旧的称呼，不用来介绍高中在读的妹妹。"}, {"text": "女工", "is_correct": false, "explanation": "语义：女工指女性工人，“高中女工”与在校读书的语境不符。"}], "explanations": {"女生": "女生指在学校里读书的女孩，与“我妹妹是一名高中”相符。", "女护士": "语义：护士在医院工作，“高中女护士”与学校的语境不符。", "女同志": "语域：“女同志”是较旧的称呼，不用来介绍高中在读的妹妹。", "女工": "语义：女工指女性工人，“高中女工”与在校读书的语境不符。"}, "sentence_index": 0, "correct_answer": "女生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位女生教授在会上做了报告。", "explanation": "这里应该用〈女性〉。女生只指在校读书的女孩，不能用于执教的成年女教授。"}, {"text": "尊敬的女生们，先生们，大家好！", "explanation": "这里应该用〈女士〉。正式场合称呼在场的成年女性用“女士”，“女生”只指在校读书的女性。"}, {"text": "这家工厂的女生大多四十多岁，手艺都很好。", "explanation": "这里应该用〈女工〉。女生指在校读书的女孩，不能用来指在工厂工作的成年女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女生", "is_correct": true, "explanation": "女生指在学校读书的女孩，与“篮球场上有几个……在打球”相符。"}, {"text": "女观众", "is_correct": false, "explanation": "配价：“打球”需要参与者作主语，观众不参与打球，不能说“几个女观众在打球”。"}, {"text": "女裁判", "is_correct": false, "explanation": "语义：裁判负责执法，不在场上打球，“几个女裁判在打球”与语境不符。"}, {"text": "女粉丝", "is_correct": false, "explanation": "语义：粉丝是支持者，不会上场打球，与“篮球场”的语境不符。"}], "explanations": {"女生": "女生指在学校读书的女孩，与“篮球场上有几个……在打球”相符。", "女观众": "配价：“打球”需要参与者作主语，观众不参与打球，不能说“几个女观众在打球”。", "女裁判": "语义：裁判负责执法，不在场上打球，“几个女裁判在打球”与语境不符。", "女粉丝": "语义：粉丝是支持者，不会上场打球，与“篮球场”的语境不符。"}, "sentence_index": 6, "correct_answer": "女生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的表姐是一个三十岁的女生，已经结婚了。", "explanation": "这里应该用〈女人〉。“女生”只指在校读书的女孩，不能用于已婚的成年女性。"}, {"text": "这位女生五十多岁，已经拍了三十年电影。", "explanation": "这里应该用〈女演员〉。女生指在校读书的女孩，不能用来指拍了三十年电影的成年女演员。"}, {"text": "我家的女生刚满两岁，还不会说话。", "explanation": "这里应该用〈女孩〉。两岁幼儿不在学校读书，“女生”只指在校读书的女孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个女生们正在操场上踢毽子。", "corrected_sentence": "两个女生正在操场上踢毽子。", "error_description": "错误在“们”：“们”表示复数，不能与“两个”这样的数量词同用。错误形式是“两个女生们”，正确形式是“两个女生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三只女生在走廊里聊天。", "corrected_sentence": "三名女生在走廊里聊天。", "error_description": "错误在量词：“只”用于动物等，指人的女生应用“名”（或“个”“位”）。错误形式是“三只女生”，正确形式是“三名女生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '491bcf82-a5b3-404e-b5b2-c49d94b80e18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
