INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86847, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "现场是事情正在发生的那个地方。", "primary_collocate": null, "pronunciation": "xiàn chǎng", "ipa": "ɕjɛn˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察很快到了现场。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾现场有很多人。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在现场做了报道。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家不要进入事故现场。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生到现场以后马上检查了他。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是第一个到现场的人。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场很乱，到处都是水。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在现场找到了一把刀。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有去现场，只是在电视上看了。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场的声音很大，我听不清。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "事故现场", "label": "复合"}, {"form": "現場", "label": "繁体"}], "register": "通用", "sense_fingerprint": "事情发生的地方，多指事故、案件的现场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86847, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现场", "is_correct": true, "explanation": "现场（xiàn chǎng）指事情正在发生的地方。"}, {"text": "县长", "is_correct": false, "explanation": "zhǎng（第三声）与 chǎng（第三声）声母不同（zh 与 ch），意思是县的行政长官。"}, {"text": "限产", "is_correct": false, "explanation": "chǎn 与 chǎng 韵母不同（-n 与 -ng），意思是限制产量。"}, {"text": "线长", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是线的长度。"}, {"text": "献唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，意思是献上歌声。"}], "explanations": {"现场": "现场（xiàn chǎng）指事情正在发生的地方。", "县长": "zhǎng（第三声）与 chǎng（第三声）声母不同（zh 与 ch），意思是县的行政长官。", "限产": "chǎn 与 chǎng 韵母不同（-n 与 -ng），意思是限制产量。", "线长": "cháng（第二声）与 chǎng（第三声）声调不同，意思是线的长度。", "献唱": "chàng（第四声）与 chǎng（第三声）声调不同，意思是献上歌声。"}, "sentence_index": null, "correct_answer": "现场"}, "level_3": {"options": [{"text": "现场", "is_correct": true, "explanation": "正确：警察前往的是事故或案件的发生地，“现场”符合句意。"}, {"text": "证据", "is_correct": false, "explanation": "语义：“到”后接的应是地点或人，“证据”不是可以到达的地方，句子不通。"}, {"text": "办法", "is_correct": false, "explanation": "搭配：“到”不与“办法”搭配，应说“想到办法”。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以被到达的地点，与“到了”矛盾。"}], "explanations": {"现场": "正确：警察前往的是事故或案件的发生地，“现场”符合句意。", "证据": "语义：“到”后接的应是地点或人，“证据”不是可以到达的地方，句子不通。", "办法": "搭配：“到”不与“办法”搭配，应说“想到办法”。", "声音": "语义：“声音”不是可以被到达的地点，与“到了”矛盾。"}, "sentence_index": 0, "correct_answer": "现场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个体育馆的现场很大，适合打篮球。", "explanation": "这里应该用〈场地〉。现场指事情正在发生的地方，体育活动的空间要用〈场地〉。"}, {"text": "这台电脑的现场很好看。", "explanation": "这里应该用〈外观〉。现场指事情正在发生的地方，不指物品的外形。"}, {"text": "这部电影里有一个很长的现场。", "explanation": "这里应该用〈场景〉。现场指事情正在发生的地方，电影里的一段情节画面要用〈场景〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现场", "is_correct": true, "explanation": "正确：“现场很乱，到处都是水”指事故或灾害的发生地，符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是抽象的感受，与“到处都是水”的具体画面矛盾。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”不是可以有水的地方，后半句与前半句无法衔接。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“乱”一般用于地方或情况，“工资很乱”不是常用搭配。"}], "explanations": {"现场": "正确：“现场很乱，到处都是水”指事故或灾害的发生地，符合句意。", "心情": "语义：“心情”是抽象的感受，与“到处都是水”的具体画面矛盾。", "性格": "语义：“性格”不是可以有水的地方，后半句与前半句无法衔接。", "工资": "搭配：“乱”一般用于地方或情况，“工资很乱”不是常用搭配。"}, "sentence_index": 6, "correct_answer": "现场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆是一个很安静的现场，适合学习。", "explanation": "这里应该用〈场所〉。现场指事情正在发生的地方，泛指学习、休息的地方要用〈场所〉。"}, {"text": "这个现场的人口很多，经济也发展得很快。", "explanation": "这里应该用〈地区〉。现场指小范围的事发地点，不能指一个地区。"}, {"text": "书的现场在桌子上。", "explanation": "这里应该用〈位置〉。现场指事情正在发生的地方，不指物品的摆放位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察到了一条现场。", "corrected_sentence": "警察到了一处现场。", "error_description": "错误形式“一条现场”，正确形式“一处现场”。“条”用于细长的东西，现场不能用“条”，应用“处”或“个”作量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前去过在现场，那里很乱。", "corrected_sentence": "我以前去过现场，那里很乱。", "error_description": "错误形式“去过在现场”，正确形式“去过现场”。“去”后直接带处所宾语，不能在“现场”前加介词“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
