INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "事情发生或正在进行的地点。", "primary_collocate": null, "pronunciation": "xiàn chǎng", "ipa": "ɕjɛn˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想去现场看这场比赛。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场有五千个球迷。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手在现场唱了三首歌。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目是在现场录的。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次在现场听音乐会，很激动。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场的气氛特别热闹。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众在现场一直拍手。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去工地现场学习。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛现场来了很多记者。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在现场听音乐，比在家听好。", "target_word": "现场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "比赛现场", "label": "复合"}, {"form": "現場", "label": "繁体"}], "register": "通用", "sense_fingerprint": "活动、比赛、演出正在进行的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86848, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "现场", "is_correct": true, "explanation": "现场（xiàn chǎng）指活动、比赛、演出正在进行的地方。"}, {"text": "县长", "is_correct": false, "explanation": "zhǎng（第三声）与 chǎng（第三声）声母不同（zh 与 ch），意思是县的行政长官。"}, {"text": "限产", "is_correct": false, "explanation": "chǎn 与 chǎng 韵母不同（-n 与 -ng），意思是限制产量。"}, {"text": "线长", "is_correct": false, "explanation": "cháng（第二声）与 chǎng（第三声）声调不同，意思是线的长度。"}, {"text": "献唱", "is_correct": false, "explanation": "chàng（第四声）与 chǎng（第三声）声调不同，意思是献上歌声。"}], "explanations": {"现场": "现场（xiàn chǎng）指活动、比赛、演出正在进行的地方。", "县长": "zhǎng（第三声）与 chǎng（第三声）声母不同（zh 与 ch），意思是县的行政长官。", "限产": "chǎn 与 chǎng 韵母不同（-n 与 -ng），意思是限制产量。", "线长": "cháng（第二声）与 chǎng（第三声）声调不同，意思是线的长度。", "献唱": "chàng（第四声）与 chǎng（第三声）声调不同，意思是献上歌声。"}, "sentence_index": null, "correct_answer": "现场"}, "level_3": {"options": [{"text": "现场", "is_correct": true, "explanation": "正确：“我想去现场看这场比赛”指比赛进行的地点，符合句意。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：“报纸”不是可以“去”的地方，与“去……看比赛”矛盾。"}, {"text": "门票", "is_correct": false, "explanation": "语义：“门票”不是可以“去”的地点，句子不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“去”后接地点时不说“去电视”，应说“在电视上看”。"}], "explanations": {"现场": "正确：“我想去现场看这场比赛”指比赛进行的地点，符合句意。", "报纸": "语义：“报纸”不是可以“去”的地方，与“去……看比赛”矛盾。", "门票": "语义：“门票”不是可以“去”的地点，句子不通。", "电视": "搭配：“去”后接地点时不说“去电视”，应说“在电视上看”。"}, "sentence_index": 0, "correct_answer": "现场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的现场很好，交通也方便。", "explanation": "这里应该用〈地点〉。现场指活动、比赛正在进行的地方，店铺的位置要用〈地点〉。"}, {"text": "他是个好现场，很会做饭。", "explanation": "这里应该用〈厨师〉。现场指活动正在进行的地点，不指人。"}, {"text": "这块草坪现场很大，适合野餐。", "explanation": "这里应该用〈场地〉。现场指活动正在进行的地点，供野餐的空地要用〈场地〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现场", "is_correct": true, "explanation": "正确：“观众在现场一直拍手”指比赛或演出进行的地点，符合句意。"}, {"text": "屏幕", "is_correct": false, "explanation": "配价：“在”后接处所时要加方位词，应说“在屏幕前”或“在屏幕上”，“在屏幕”不完整。"}, {"text": "比分", "is_correct": false, "explanation": "语义：“比分”不是可以“在”其中拍手的地方，与句意矛盾。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”不是拍手的场所，“在音乐一直拍手”不通。"}], "explanations": {"现场": "正确：“观众在现场一直拍手”指比赛或演出进行的地点，符合句意。", "屏幕": "配价：“在”后接处所时要加方位词，应说“在屏幕前”或“在屏幕上”，“在屏幕”不完整。", "比分": "语义：“比分”不是可以“在”其中拍手的地方，与句意矛盾。", "音乐": "语义：“音乐”不是拍手的场所，“在音乐一直拍手”不通。"}, "sentence_index": 6, "correct_answer": "现场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架的现场在门口，很好找。", "explanation": "这里应该用〈位置〉。现场指活动正在进行的地方，不指物品的摆放位置。"}, {"text": "这个现场的人口很多，经济也发展得很快。", "explanation": "这里应该用〈地区〉。现场指活动正在进行的小范围地点，不能指一个区域。"}, {"text": "我的新现场在北京。", "explanation": "这里应该用〈地址〉。现场指事情正在进行的地点，住所的位置要用〈地址〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "观众在现场了欢呼了三次。", "corrected_sentence": "观众在现场欢呼了三次。", "error_description": "错误形式“在现场了欢呼”，正确形式“在现场欢呼了三次”。多出的“了”放在动词“欢呼”之前，“了”只应放在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "现场人的很多，很热闹。", "corrected_sentence": "现场的人很多，很热闹。", "error_description": "错误形式“现场人的很多”，正确形式“现场的人很多”。修饰语“现场”后应接“的”，“的”放错位置后句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
