INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86852, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示事情真实可靠；的确。", "primary_collocate": null, "pronunciation": "què shí", "ipa": "tɕʰɥɛ˥˩ ʂʅ˧˥", "syllable_count": 2, "sentences": [{"text": "确实，你说的话很有道理。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息确实可靠。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他确实是我们班最高的人。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的东西确实不贵。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我确实看见他进去了。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试确实有点难。", "target_word": "确实", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她确实已经走了。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语确实进步了很多。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市确实变了不少。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药吃了以后，我确实好多了。", "target_word": "确实", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "確實", "label": "繁体"}, {"form": "确确实实", "label": "重叠"}], "register": "中性", "sense_fingerprint": "确实：副词，的确，事情真实可靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a694cc8-f902-4891-9c84-c2b01ecc1500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86852, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "确实", "is_correct": true, "explanation": "正确答案：确实（què shí），副词，表示事情真实可靠，即“的确”。"}, {"text": "缺失", "is_correct": false, "explanation": "quē（第一声）与 què（第四声）声调不同，shī 与 shí 声调也不同，缺失指缺少，与“的确”无关。"}, {"text": "绝食", "is_correct": false, "explanation": "jué 与 què 声母不同（j 与 q），绝食指不吃饭，与“的确”无关。"}, {"text": "却是", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，“却是”表示转折，意思是“不过”，不表示“的确”。"}], "explanations": {"确实": "正确答案：确实（què shí），副词，表示事情真实可靠，即“的确”。", "缺失": "quē（第一声）与 què（第四声）声调不同，shī 与 shí 声调也不同，缺失指缺少，与“的确”无关。", "绝食": "jué 与 què 声母不同（j 与 q），绝食指不吃饭，与“的确”无关。", "却是": "shì（第四声）与 shí（第二声）声调不同，“却是”表示转折，意思是“不过”，不表示“的确”。"}, "sentence_index": null, "correct_answer": "确实"}, "level_3": {"options": [{"text": "确实", "is_correct": true, "explanation": "正确：确实表示事情真实可靠，放在句首引出“你说的话很有道理”，符合句意。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示事情突然发生，与“说的话很有道理”的判断不相符。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同，不能放在句首引出对对方话语的判断。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间很快，与对对方话语的肯定判断无关，句子意思不通。"}], "explanations": {"确实": "正确：确实表示事情真实可靠，放在句首引出“你说的话很有道理”，符合句意。", "忽然": "语义：“忽然”表示事情突然发生，与“说的话很有道理”的判断不相符。", "一起": "搭配：“一起”表示共同，不能放在句首引出对对方话语的判断。", "马上": "语义：“马上”表示时间很快，与对对方话语的肯定判断无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "确实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的东西确实据说不贵。", "explanation": "这里应该用〈听说〉。确实表示亲眼所见或已确定的事实，转述传闻要说“听说”。"}, {"text": "这里的东西确实也许不贵。", "explanation": "这里应该用〈估计〉。确实表示肯定的事实，对没有把握的价格只能说“估计”。"}, {"text": "这里的东西确实大概不贵。", "explanation": "这里应该用〈大概〉。确实表示肯定，与“大概”的推测相矛盾；对价格没有把握时要说“大概”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "确实", "is_correct": true, "explanation": "正确：确实表示事情真实可靠，与“已经走了”搭配，句子通顺。"}, {"text": "亲自", "is_correct": false, "explanation": "搭配：“亲自”要修饰人的动作，不能接“已经走了”这样的状态。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同，与“她”的离开这一动作搭配不当，句子不通。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“已经走了”的完成状态相矛盾。"}], "explanations": {"确实": "正确：确实表示事情真实可靠，与“已经走了”搭配，句子通顺。", "亲自": "搭配：“亲自”要修饰人的动作，不能接“已经走了”这样的状态。", "一起": "搭配：“一起”表示共同，与“她”的离开这一动作搭配不当，句子不通。", "立刻": "语义：“立刻”表示马上发生，与“已经走了”的完成状态相矛盾。"}, "sentence_index": 6, "correct_answer": "确实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你确实别再吃药了。", "explanation": "这里应该用〈一定〉。确实用于肯定已经成立的事实，不能直接用于对别人的命令或要求。"}, {"text": "药吃了以后，我确实或许好多了。", "explanation": "这里应该用〈也许〉。确实表示肯定，与“或许”的不确定相矛盾；对自己的感觉没有把握时要说“也许”。"}, {"text": "明天我确实会好多了。", "explanation": "这里应该用〈估计〉。确实只用于已经成立或看得见的事实，对还没发生的变化只能说“估计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他确实了不知道这件事。", "corrected_sentence": "他确实不知道这件事。", "error_description": "“确实”后面不能直接加“了”，应说成“他确实不知道这件事”。“确实了不知道”中的“了”是多余的，错在“确实”的体标。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86852, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题确实得很难。", "corrected_sentence": "这个问题确实很难。", "error_description": "“确实”后面不能直接加“得”，应说成“这个问题确实很难”。“确实得很难”中的“得”是多余的，错在“确实”的补语形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9884cfa0-9a08-47ab-a104-92125ae6cbdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
