INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86853, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妹妹是比你小的女孩，和你有同一个爸爸妈妈。", "primary_collocate": null, "pronunciation": "mèi mei", "ipa": "meɪ˥˩ meɪ", "syllable_count": 2, "sentences": [{"text": "我有一个妹妹。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹今年八岁。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的妹妹很爱笑。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹在家看电视。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹比我小三岁。", "target_word": "妹妹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和妹妹都喜欢吃苹果。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我带妹妹去公园玩了。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给妹妹买了一件红色的衣服。", "target_word": "妹妹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的妹妹喜欢画画，她画的小狗很可爱。", "target_word": "妹妹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，我都和妹妹一起走路去学校。", "target_word": "妹妹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "亲妹妹", "label": "复合"}], "register": "中性", "sense_fingerprint": "妹妹：同一对父母所生、比自己小的女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd61e82f-c8bb-4094-ae5d-76f242f3d821') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "妹妹", "is_correct": true, "explanation": "正确：「妹妹」指同父母、比自己小的女孩，可以放在「我有一个___」中。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：「鞋」的量词是「双」，不能说「一个鞋」。"}, {"text": "水", "is_correct": false, "explanation": "搭配：「水」是不可数的物质名词，应说「一杯水」，不说「一个水」。"}, {"text": "白天", "is_correct": false, "explanation": "语义：「白天」指时段，不是可以被「有」的人或物，「我有一个白天」不成立。"}], "explanations": {"妹妹": "正确：「妹妹」指同父母、比自己小的女孩，可以放在「我有一个___」中。", "鞋": "搭配：「鞋」的量词是「双」，不能说「一个鞋」。", "水": "搭配：「水」是不可数的物质名词，应说「一杯水」，不说「一个水」。", "白天": "语义：「白天」指时段，不是可以被「有」的人或物，「我有一个白天」不成立。"}, "sentence_index": 0, "correct_answer": "妹妹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妹妹比我大两岁。", "explanation": "这里应该用〈姐姐〉。妹妹指比自己小的同胞女性，比自己大的要说姐姐。"}, {"text": "他是我的妹妹。", "explanation": "这里应该用〈弟弟〉。妹妹指女性，男性的同胞晚辈要说弟弟。"}, {"text": "我妈妈的妹妹是我的妹妹。", "explanation": "这里应该用〈阿姨〉。妈妈的妹妹是我的阿姨，不是同父母的妹妹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妹妹", "is_correct": true, "explanation": "正确：「妹妹」是人，可以被「带」去公园，句中「昨天我带___去公园玩了」正合适。"}, {"text": "天空", "is_correct": false, "explanation": "语义：「天空」不能被人带去公园，「带天空去公园」不合常理。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「数学」是抽象的学科，不能被带到公园去玩。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：「花瓶」易碎，一般不说「带花瓶去公园玩」，这里的同伴应是人或宠物。"}], "explanations": {"妹妹": "正确：「妹妹」是人，可以被「带」去公园，句中「昨天我带___去公园玩了」正合适。", "天空": "语义：「天空」不能被人带去公园，「带天空去公园」不合常理。", "数学": "语义：「数学」是抽象的学科，不能被带到公园去玩。", "花瓶": "搭配：「花瓶」易碎，一般不说「带花瓶去公园玩」，这里的同伴应是人或宠物。"}, "sentence_index": 6, "correct_answer": "妹妹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一只妹妹。", "explanation": "这里应该用〈个〉。「只」多用于动物，指人要用「个」。"}, {"text": "我家有一张妹妹。", "explanation": "这里应该用〈个〉。「张」用于平面的东西，指人要用「个」。"}, {"text": "我家有一台妹妹。", "explanation": "这里应该用〈个〉。「台」用于机器等物件，指人要用「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一妹妹。", "corrected_sentence": "我有一个妹妹。", "error_description": "量词缺失。「一」后面必须接量词，「一妹妹」不成立，应说「一个妹妹」。", "correct_sentence_indices": [1, 2, 4]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有一只妹妹。", "corrected_sentence": "我家有一个妹妹。", "error_description": "量词用错。错误形式是「一只妹妹」，「只」用于动物；妹妹是人，正确形式是「一个妹妹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b31153-5d67-48d8-98b5-444beb9a94f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
