INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家为了保卫国家安全而设立的武装力量。", "primary_collocate": null, "pronunciation": "jūn duì", "ipa": "tɕyn˥ twei˥˩", "syllable_count": 2, "sentences": [{"text": "国家需要一支强大的军队。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队要听国家的命令。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的军队人数很少。", "target_word": "军队", "complexity_tier": "T3", "furigana": "zhè ge guó jiā de jūn duì rén shù hěn shǎo", "sentence_source": "generated"}, {"text": "军队的任务是保卫国家。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队有自己的学校和医院。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，军队也来帮忙。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的军队在边境见面了。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家每年给军队很多钱。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的军队有最新的飞机。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队不能随便进城。", "target_word": "军队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "軍隊", "label": "繁体"}], "register": "通用", "sense_fingerprint": "国家设立的、用来保卫安全的武装力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dabb8dab-b90b-4c44-8fec-11f552bb446a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "军队", "is_correct": true, "explanation": "正确：“国家需要一支强大的军队”指国家设立的武装力量，符合句意。"}, {"text": "烟", "is_correct": false, "explanation": "语义：“烟”不是国家需要的武装力量，句子不通。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“歌”不能作为保卫国家的力量，与“国家需要”矛盾。"}, {"text": "箭", "is_correct": false, "explanation": "搭配：“强大的”修饰“箭”不搭配，国家需要的是武装力量。"}], "explanations": {"军队": "正确：“国家需要一支强大的军队”指国家设立的武装力量，符合句意。", "烟": "语义：“烟”不是国家需要的武装力量，句子不通。", "歌": "语义：“歌”不能作为保卫国家的力量，与“国家需要”矛盾。", "箭": "搭配：“强大的”修饰“箭”不搭配，国家需要的是武装力量。"}, "sentence_index": 0, "correct_answer": "军队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军队的任务是教育学生。", "explanation": "这里应该用〈学校〉。军队指武装力量，教育学生是〈学校〉的任务。"}, {"text": "军队的任务是寄信。", "explanation": "这里应该用〈邮局〉。军队指武装力量，寄信是〈邮局〉的工作。"}, {"text": "军队的任务是存钱和贷款。", "explanation": "这里应该用〈银行〉。军队指武装力量，存钱和贷款的是〈银行〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军队", "is_correct": true, "explanation": "正确：“两国的军队在边境见面了”指两国的武装力量相遇，符合句意。"}, {"text": "货物", "is_correct": false, "explanation": "配价：“见面”要求有意志的人或机构作主体，“货物”不能见面。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不会“见面”，与句意矛盾。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能“见面”，句子不通。"}], "explanations": {"军队": "正确：“两国的军队在边境见面了”指两国的武装力量相遇，符合句意。", "货物": "配价：“见面”要求有意志的人或机构作主体，“货物”不能见面。", "电脑": "语义：“电脑”不会“见面”，与句意矛盾。", "天气": "语义：“天气”不能“见面”，句子不通。"}, "sentence_index": 6, "correct_answer": "军队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军队在理发店里给人理发。", "explanation": "这里应该用〈理发师〉。军队指武装力量，给人理发的是〈理发师〉。"}, {"text": "军队在街上卖衣服。", "explanation": "这里应该用〈商店〉。卖东西的是〈商店〉，军队不做买卖。"}, {"text": "军队每天卖很多书。", "explanation": "这里应该用〈书店〉。军队指武装力量，卖书的是〈书店〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "军队驻守着边境着。", "corrected_sentence": "军队驻守着边境。", "error_description": "错误形式“驻守着边境着”，多出的“着”放在宾语“边境”之后，“着”只应紧跟动词“驻守”。正确形式“驻守着边境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条强大的军队保卫着国家。", "corrected_sentence": "一支强大的军队保卫着国家。", "error_description": "错误形式“一条强大的军队”，正确形式“一支强大的军队”。“条”用于细长的东西，“军队”的量词应为“支”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3bb0a1a-67c0-4958-ba6c-f5cef83a1758') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
