INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86865, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "门是房子上进进出出的地方。", "primary_collocate": null, "pronunciation": "mén", "ipa": "mən˧˥", "syllable_count": 1, "sentences": [{"text": "我们家的门朝南，阳光很好。", "target_word": "门", "complexity_tier": "T3", "furigana": "mén", "sentence_source": "generated"}, {"text": "他从门里走了出来。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从这个门进去。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子有两扇门，一扇在前面，一扇在后面。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子站在门旁边等妈妈。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们一个个从门进来，屋里很热闹。", "target_word": "门", "complexity_tier": "T3", "furigana": "mén", "sentence_source": "generated"}, {"text": "这个门太小，大桌子进不去。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们挤在门那儿，谁也不肯先走。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的门只有一个人那么宽。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在门中间，挡住了所有人的路。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扇", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "門", "label": "繁体"}, {"form": "大门", "label": "复合词"}, {"form": "门口", "label": "复合词"}, {"form": "后门", "label": "复合词"}], "register": "中性", "sense_fingerprint": "房子上进出的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7a1d248-553b-4926-a225-0466394be207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "门", "is_correct": true, "explanation": "门（mén，第二声）指房子上进出的地方，是本题的正确答案。"}, {"text": "闷", "is_correct": false, "explanation": "mèn（第四声）与 mén（第二声）声调不同，意思是烦闷。"}, {"text": "盟", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是结盟。"}, {"text": "民", "is_correct": false, "explanation": "mín 与 mén 韵母不同（in 与 en），意思是人民。"}], "explanations": {"门": "门（mén，第二声）指房子上进出的地方，是本题的正确答案。", "闷": "mèn（第四声）与 mén（第二声）声调不同，意思是烦闷。", "盟": "méng 与 mén 韵母不同（eng 与 en），意思是结盟。", "民": "mín 与 mén 韵母不同（in 与 en），意思是人民。"}, "sentence_index": null, "correct_answer": "门"}, "level_3": {"options": [{"text": "门", "is_correct": true, "explanation": "门：房子上进出的地方，“朝南”可用于门，是本句正确的词。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“朝南”只用于房屋、门窗等，不能说“饭朝南”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有朝向，不能说“朝南”，句子不通。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“朝南”不用来描述鞋，句子不通。"}], "explanations": {"门": "门：房子上进出的地方，“朝南”可用于门，是本句正确的词。", "饭": "搭配：“朝南”只用于房屋、门窗等，不能说“饭朝南”。", "书": "语义：书没有朝向，不能说“朝南”，句子不通。", "鞋": "搭配：“朝南”不用来描述鞋，句子不通。"}, "sentence_index": 0, "correct_answer": "门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的房子有两张门，一张在前面，一张在后面。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“张”用于桌子、纸等，不用于门。"}, {"text": "这栋房子有三条门，一条在前面，一条在后面。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“条”用于细长的东西，不用于门。"}, {"text": "这间门很大，车都开不进去。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“间”用于房屋，不用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86865, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "门", "is_correct": true, "explanation": "门（mén，第二声）指房子上进出的地方，是本题的正确答案。"}, {"text": "蒙", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是遮盖或蒙骗。"}, {"text": "闻", "is_correct": false, "explanation": "wén 与 mén 声母不同（w 与 m），意思是听闻或闻嗅。"}, {"text": "们", "is_correct": false, "explanation": "men（轻声）与 mén（第二声）声调不同，意思是表示复数。"}], "explanations": {"门": "门（mén，第二声）指房子上进出的地方，是本题的正确答案。", "蒙": "méng 与 mén 韵母不同（eng 与 en），意思是遮盖或蒙骗。", "闻": "wén 与 mén 声母不同（w 与 m），意思是听闻或闻嗅。", "们": "men（轻声）与 mén（第二声）声调不同，意思是表示复数。"}, "sentence_index": null, "correct_answer": "门"}, "level_3": {"options": [{"text": "门", "is_correct": true, "explanation": "门：房子上进出的地方，“门太小”指出入口太窄，是本句正确的词。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸是薄片，不能作为可以进出的通道，与“大桌子进不去”不合。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“进不去”要求有出入口作主语，“花”不能与之搭配，“这个花太小”也说不出通道的大小。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不是出入口，句中需要的是一个可以让大桌子通过的地方，笔不合。"}], "explanations": {"门": "门：房子上进出的地方，“门太小”指出入口太窄，是本句正确的词。", "纸": "语义：纸是薄片，不能作为可以进出的通道，与“大桌子进不去”不合。", "花": "搭配：“进不去”要求有出入口作主语，“花”不能与之搭配，“这个花太小”也说不出通道的大小。", "笔": "语义：笔不是出入口，句中需要的是一个可以让大桌子通过的地方，笔不合。"}, "sentence_index": 6, "correct_answer": "门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所房子有两块门，一块在前面，一块在后面。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“块”用于块状的东西，不用于门。"}, {"text": "我家的门有两根，一根朝南，一根朝北。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“根”用于细长的东西，不用于门。"}, {"text": "我家的门有两顶，一顶朝南，一顶朝北。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“顶”用于帽子、帐篷等，不用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他关门上，出去了。", "corrected_sentence": "他关上门，出去了。", "error_description": "结果补语“上”应紧跟动词。应说“关上门”，不说“关门上”。错在“上”的位置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈一直开着一辆门等我回家。", "corrected_sentence": "妈妈一直开着门等我回家。", "error_description": "“辆”是车辆的量词，门不用“辆”。应说“开着门”，不说“开着一辆门”。错在门的量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
