INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物或器物的出入口；也指安在出入口可开关的装置。", "primary_collocate": null, "pronunciation": "mén", "ipa": "mən˧˥", "syllable_count": 1, "sentences": [{"text": "请把门关上。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人在敲门。", "target_word": "门", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他拉开门，看见外面下雪了。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门没有锁，你直接进来吧。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门是红色的。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，门就开了。", "target_word": "门", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出去的时候，别忘了锁门。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室的门坏了，打不开。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的门没关好，里面的菜坏了。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他推开门，走进了房间。", "target_word": "门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扇", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "門", "label": "繁体"}, {"form": "大门", "label": "复合词"}, {"form": "门口", "label": "复合词"}, {"form": "前门", "label": "复合词"}], "register": "中性", "sense_fingerprint": "建筑物或器物的出入口及可开关的门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7a1d248-553b-4926-a225-0466394be207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "门", "is_correct": true, "explanation": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。"}, {"text": "闷", "is_correct": false, "explanation": "mèn（第四声）与 mén（第二声）声调不同，意思是烦闷。"}, {"text": "盟", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是结盟。"}, {"text": "民", "is_correct": false, "explanation": "mín 与 mén 韵母不同（in 与 en），意思是人民。"}], "explanations": {"门": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。", "闷": "mèn（第四声）与 mén（第二声）声调不同，意思是烦闷。", "盟": "méng 与 mén 韵母不同（eng 与 en），意思是结盟。", "民": "mín 与 mén 韵母不同（in 与 en），意思是人民。"}, "sentence_index": null, "correct_answer": "门"}, "level_3": {"options": [{"text": "门", "is_correct": true, "explanation": "门：出入口，“关上”可用于门，是本句正确的词。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“关上”不能用于饭，“请把饭关上”不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能被“关上”，与句意不符。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能被“关上”，与句意不符。"}], "explanations": {"门": "门：出入口，“关上”可用于门，是本句正确的词。", "饭": "搭配：“关上”不能用于饭，“请把饭关上”不通。", "树": "语义：树不能被“关上”，与句意不符。", "河": "语义：河不能被“关上”，与句意不符。"}, "sentence_index": 0, "correct_answer": "门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块门是红色的。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“块”用于块状的东西，不用于门。"}, {"text": "这条门很高，要用力才能推开。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“条”用于细长的东西，不用于门。"}, {"text": "这辆门很结实，是木头做的。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“辆”用于车辆，不用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "门", "is_correct": true, "explanation": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。"}, {"text": "蒙", "is_correct": false, "explanation": "méng 与 mén 韵母不同（eng 与 en），意思是遮盖或蒙骗。"}, {"text": "闻", "is_correct": false, "explanation": "wén 与 mén 声母不同（w 与 m），意思是听闻或闻嗅。"}, {"text": "们", "is_correct": false, "explanation": "men（轻声）与 mén（第二声）声调不同，意思是表示复数。"}], "explanations": {"门": "门（mén，第二声）指建筑物或器物的出入口，是本题的正确答案。", "蒙": "méng 与 mén 韵母不同（eng 与 en），意思是遮盖或蒙骗。", "闻": "wén 与 mén 声母不同（w 与 m），意思是听闻或闻嗅。", "们": "men（轻声）与 mén（第二声）声调不同，意思是表示复数。"}, "sentence_index": null, "correct_answer": "门"}, "level_3": {"options": [{"text": "门", "is_correct": true, "explanation": "门：出入口，“锁门”指锁上门，是本句正确的词。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“锁”的对象不能是钥匙，说“锁钥匙”不通。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不能被锁，与句意不符。"}, {"text": "灯", "is_correct": false, "explanation": "搭配：“锁”不用于灯，应说“关灯”，说“锁灯”不通。"}], "explanations": {"门": "门：出入口，“锁门”指锁上门，是本句正确的词。", "钥匙": "搭配：“锁”的对象不能是钥匙，说“锁钥匙”不通。", "饭": "语义：饭不能被锁，与句意不符。", "灯": "搭配：“锁”不用于灯，应说“关灯”，说“锁灯”不通。"}, "sentence_index": 6, "correct_answer": "门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家新买了一张门，今天刚装好。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“张”用于桌子、纸等平面的东西，不用于门。"}, {"text": "这根门太窄，大家都进不去。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“根”用于细长的东西，不用于门。"}, {"text": "这顶门很旧了，该换新的了。", "explanation": "这里应该用〈扇〉。门的量词是“扇”，“顶”用于帽子、帐篷等，不用于门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一只门打开了。", "corrected_sentence": "他把一扇门打开了。", "error_description": "门的量词应用“扇”。“只”多用于动物等，不用于门。应说“一扇门”，不说“一只门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一直开门着等客人。", "corrected_sentence": "他们一直开着门等客人。", "error_description": "“着”应紧跟动词“开”，说“开着门”，不说“开门着”。错在“着”的位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不可以是说这样做不行，大人不让做。", "primary_collocate": null, "pronunciation": "bù kě yǐ", "ipa": "pu˥˩ kʰɤ˨˩ i˨˩", "syllable_count": 3, "sentences": [{"text": "妈妈说，晚上不可以一个人出去玩。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸告诉我，不可以在家里踢球。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，上课的时候不可以吃东西。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说小孩子不可以喝太多可乐。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈对弟弟说，你不可以玩她的手机。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大人说过，小孩不可以靠近河边。", "target_word": "不可以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不让我吃糖，说不可以吃太多。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，没写完作业不可以看电视。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，不可以随便拿别人的东西。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说，我不可以一个人去游泳。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "大人对小孩说不许做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7a1d248-553b-4926-a225-0466394be207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示大人不允许晚上一个人出去，与“妈妈说”的禁止语气一致。"}, {"text": "不会", "is_correct": false, "explanation": "语义：「不会」表示预测或能力，不能表示妈妈的禁止。"}, {"text": "不敢", "is_correct": false, "explanation": "语义：「不敢」说的是人心里害怕，句子里没有这种意思，也不表示被禁止外出。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示许可，说“晚上能一个人出去玩”与妈妈的禁止意思相反。"}], "explanations": {"不可以": "正确：表示大人不允许晚上一个人出去，与“妈妈说”的禁止语气一致。", "不会": "语义：「不会」表示预测或能力，不能表示妈妈的禁止。", "不敢": "语义：「不敢」说的是人心里害怕，句子里没有这种意思，也不表示被禁止外出。", "能": "语义：「能」表示许可，说“晚上能一个人出去玩”与妈妈的禁止意思相反。"}, "sentence_index": 0, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机坏了，所以不可以拍照。", "explanation": "这里应该用〈拍不了〉。〈不可以〉表示不被允许，手机坏了是客观条件，不能用许可词来说明。"}, {"text": "这块冰太滑了，我不可以站稳。", "explanation": "这里应该用〈站不稳〉。〈不可以〉表示许可，冰面太滑使身体无法保持平衡是条件所致，要用〈站不稳〉。"}, {"text": "这个字太小了，我不可以看清。", "explanation": "这里应该用〈看不清〉。〈不可以〉不能表示视力或距离造成的看不见结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示不允许吃太多，与“爷爷不让我吃糖”的语境一致。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示应当，说“应该吃太多”与“不让我吃糖”的意思相反。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示许可或能力，说“能吃太多”与爷爷不让吃的语境冲突。"}, {"text": "得", "is_correct": false, "explanation": "语义：「得」作能愿动词表示必要，“说得吃太多”是“必须多吃”，与爷爷不让吃的语境相反。"}], "explanations": {"不可以": "正确：表示不允许吃太多，与“爷爷不让我吃糖”的语境一致。", "应该": "语义：「应该」表示应当，说“应该吃太多”与“不让我吃糖”的意思相反。", "能": "语义：「能」表示许可或能力，说“能吃太多”与爷爷不让吃的语境冲突。", "得": "语义：「得」作能愿动词表示必要，“说得吃太多”是“必须多吃”，与爷爷不让吃的语境相反。"}, "sentence_index": 6, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌太难了，我不可以唱完。", "explanation": "这里应该用〈唱不完〉。〈不可以〉表示不被允许，唱不完是难度或能力的问题。"}, {"text": "他耳朵聋了，所以不可以听见声音。", "explanation": "这里应该用〈听不见〉。〈不可以〉不能表示感官无法接收声音的结果。"}, {"text": "窗户太高了，我不可以够到。", "explanation": "这里应该用〈够不到〉。〈不可以〉表示许可，身高或距离造成的够不到要用〈够不到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说，你不可以了喝酒。", "corrected_sentence": "妈妈说，你不可以喝酒。", "error_description": "错误形式：「不可以」后面直接加了「了」。正确形式：「不可以喝酒」。「不可以」后面应直接接动词，不能插入「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校规定，学生很不可以带手机进教室。", "corrected_sentence": "学校规定，学生不可以带手机进教室。", "error_description": "错误形式：「很不可以」，在「不可以」前加了程度副词「很」。正确形式：「不可以带手机」。「不可以」表示禁止，不能再用「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
