INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "表示不被允许、不行。", "primary_collocate": null, "pronunciation": "bù kě yǐ", "ipa": "pu˥˩ kʰɤ˨˩ i˨˩", "syllable_count": 3, "sentences": [{"text": "这里不可以停车。", "target_word": "不可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "图书馆里不可以大声说话。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里不可以抽烟。", "target_word": "不可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试的时候不可以看手机。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有票的人不可以进去。", "target_word": "不可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机起飞前，手机不可以开机。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家民宿规定，不可以住三个人。", "target_word": "不可以", "complexity_tier": "T3", "furigana": "bù kě yǐ", "sentence_source": "generated"}, {"text": "游泳池里不可以带食物进来。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这家店里，不可以拍照。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "规定说，开车时不可以打电话。", "target_word": "不可以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "规定或场合不允许做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7a1d248-553b-4926-a225-0466394be207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示这个场所规定不允许停车。"}, {"text": "不会", "is_correct": false, "explanation": "语义：「不会」表示预测，不能表示场所的禁止规定。"}, {"text": "不敢", "is_correct": false, "explanation": "搭配：「不敢」要求人主动胆怯，「这里」作为地点不能作「不敢」的主语。"}, {"text": "应该", "is_correct": false, "explanation": "语义：「应该」表示应当，说“这里应该停车”与禁止停车的语境相反。"}], "explanations": {"不可以": "正确：表示这个场所规定不允许停车。", "不会": "语义：「不会」表示预测，不能表示场所的禁止规定。", "不敢": "搭配：「不敢」要求人主动胆怯，「这里」作为地点不能作「不敢」的主语。", "应该": "语义：「应该」表示应当，说“这里应该停车”与禁止停车的语境相反。"}, "sentence_index": 0, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题太难了，我不可以做出来。", "explanation": "这里应该用〈做不出来〉。〈不可以〉表示不被允许，做不出来是能力不足，不能用它。"}, {"text": "我的手机没电了，所以不可以打电话。", "explanation": "这里应该用〈打不了〉。〈不可以〉表示许可，没电是客观条件，不能用它来说明。"}, {"text": "这件衣服太大了，我不可以穿。", "explanation": "这里应该用〈穿不了〉。〈不可以〉不能表示尺码不合适造成的无法穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不可以", "is_correct": true, "explanation": "正确：表示规定不允许住三个人，与“规定”的禁止语气一致。"}, {"text": "能", "is_correct": false, "explanation": "语义：「能」表示许可，说“规定能住三个人”与“规定”的限制意思相反。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示要求，“规定必须住三个人”与民宿限制人数的语境相反。"}, {"text": "得", "is_correct": false, "explanation": "语义：「得」作能愿动词表示必要，“规定得住三个人”是“必须住三个人”，与限制的意思相反。"}], "explanations": {"不可以": "正确：表示规定不允许住三个人，与“规定”的禁止语气一致。", "能": "语义：「能」表示许可，说“规定能住三个人”与“规定”的限制意思相反。", "必须": "语义：「必须」表示要求，“规定必须住三个人”与民宿限制人数的语境相反。", "得": "语义：「得」作能愿动词表示必要，“规定得住三个人”是“必须住三个人”，与限制的意思相反。"}, "sentence_index": 6, "correct_answer": "不可以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的电脑坏了，不可以上网。", "explanation": "这里应该用〈上不了网〉。〈不可以〉表示许可，电脑坏了是客观条件，不能用它表达。"}, {"text": "我没有钥匙，所以不可以开门。", "explanation": "这里应该用〈开不了门〉。〈不可以〉不能说明没有钥匙造成的无法开门。"}, {"text": "我的嗓子太哑了，我不可以唱到高音。", "explanation": "这里应该用〈唱不上去〉。〈不可以〉表示许可，嗓音条件造成的唱不到高音要用〈唱不上去〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆里不可以了吃东西。", "corrected_sentence": "图书馆里不可以吃东西。", "error_description": "错误形式：「不可以」后面加了「了」。正确形式：「不可以吃东西」。「不可以」后直接接动词，不能插入「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家酒店规定，宠物很不可以进房间。", "corrected_sentence": "这家酒店规定，宠物不可以进房间。", "error_description": "错误形式：「很不可以」，在「不可以」前加了「很」。正确形式：「不可以进房间」。「不可以」表示禁止，不能被「很」修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
