INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86879, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "成果是努力做事以后得到的好东西。", "primary_collocate": null, "pronunciation": "chéng guǒ", "ipa": "tʂʰɤŋ˧˥ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是我们努力的成果。", "target_word": "成果", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经过三年学习，他有了很好的成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起看看今天的成果吧。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好成果不是一天得到的。", "target_word": "成果", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次比赛，我们得到了好成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让学生看看自己的学习成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把工作成果给大家看了。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多年的努力，终于有了成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要保护好农民的劳动成果。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个成果让全家人都很高兴。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "研究成果", "label": "复合"}], "register": "中性", "sense_fingerprint": "成果·努力做事以后得到的好东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "正确：成果指努力做事后得到的好东西，与“努力的”搭配自然。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不是努力做事后得到的好东西。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“努力的”后面一般接抽象的结果，不说“努力的鞋子”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能是努力得到的成果。"}], "explanations": {"成果": "正确：成果指努力做事后得到的好东西，与“努力的”搭配自然。", "石头": "语义：石头是矿物，不是努力做事后得到的好东西。", "鞋子": "搭配：“努力的”后面一般接抽象的结果，不说“努力的鞋子”。", "桌子": "语义：桌子是家具，不能是努力得到的成果。"}, "sentence_index": 0, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，他的成果很好。", "explanation": "这里应该用〈成绩〉。考试分数要用成绩，成果指努力做事后得到的好东西。"}, {"text": "这次旅行的成果很长。", "explanation": "这里应该用〈路程〉。行程的远近要用路程，成果指努力做事后得到的好东西，不能用来说旅行的长短。"}, {"text": "这款面膜的成果很好。", "explanation": "这里应该用〈效果〉。护肤品的作用要用效果，成果指努力做事后得到的好东西，不能用来评价面膜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "正确：“工作成果”指努力工作后得到的好东西，可以拿给大家看。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“工作”不修饰窗户，“给大家看”也不说窗户。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不是工作取得的成绩。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不能作为工作成果展示给大家。"}], "explanations": {"成果": "正确：“工作成果”指努力工作后得到的好东西，可以拿给大家看。", "窗户": "搭配：“工作”不修饰窗户，“给大家看”也不说窗户。", "蛋糕": "语义：蛋糕是食物，不是工作取得的成绩。", "雨伞": "语义：雨伞是日用品，不能作为工作成果展示给大家。"}, "sentence_index": 6, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的成果很好。", "explanation": "这里应该用〈味道〉。菜的口感要用味道，成果指努力做事后得到的好东西，不能用来评价一道菜。"}, {"text": "我的手机成果只剩一格了。", "explanation": "这里应该用〈电量〉。手机剩余的电能要用电量，成果指努力做事后得到的好东西，不能说“只剩一格”。"}, {"text": "这件衣服的成果很贵。", "explanation": "这里应该用〈价格〉。商品的钱数要用价格，成果指努力做事后得到的好东西，不能用来说衣服贵不贵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，我们取得了一座成果。", "corrected_sentence": "这次比赛，我们取得了一项成果。", "error_description": "量词错误：成果应用量词“项”。“座”用于山、房屋等大型建筑，不能用于成果，应改为“一项成果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他取得了过重要的成果。", "corrected_sentence": "他取得过重要的成果。", "error_description": "体标错误：“了”与“过”不能同时用在同一动词后，“了”多余，应说“取得过重要的成果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
