INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作或学习中取得的成绩。", "primary_collocate": null, "pronunciation": "chéng guǒ", "ipa": "tʂʰɤŋ˧˥ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的研究成果很重要。", "target_word": "成果", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司今年的工作成果不错。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家有很多研究成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请学生们展示学习成果。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的第一项科研成果是去年发表的。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在工作中取得了不少成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师看了我们的学习成果，很满意。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项成果会帮助很多病人。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把三年的研究成果写成了一本书。", "target_word": "成果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想听听你们这个月的工作成果。", "target_word": "成果", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "科研成果", "label": "复合"}], "register": "中性", "sense_fingerprint": "成果·工作或学习中取得的成绩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "正确：“研究成果”指研究中取得的成绩，与“他的”搭配自然。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能是研究取得的成果。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“研究”修饰的一般是抽象的成果或报告，不能修饰鞋子。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，与“研究”的意思不符。"}], "explanations": {"成果": "正确：“研究成果”指研究中取得的成绩，与“他的”搭配自然。", "椅子": "语义：椅子是家具，不能是研究取得的成果。", "鞋子": "搭配：“研究”修饰的一般是抽象的成果或报告，不能修饰鞋子。", "鸡蛋": "语义：鸡蛋是食物，与“研究”的意思不符。"}, "sentence_index": 0, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次失败让我得到了很多成果。", "explanation": "这里应该用〈收获〉。收获指从经历中得到的东西，可以是教训；成果指工作或学习中取得的成绩，不能用于失败的经历。"}, {"text": "这种护肤品的成果很好。", "explanation": "这里应该用〈效果〉。护肤品的作用要用效果，成果指工作或学习中取得的成绩，不能用来形容护肤品。"}, {"text": "这种清洁剂的成果很好。", "explanation": "这里应该用〈成效〉。成效指作用的效果，多用于措施、方法；成果指工作或学习中取得的成绩，不能用来形容清洁剂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成果", "is_correct": true, "explanation": "正确：“学习成果”指学习中取得的成绩，老师可以看，也可以满意。"}, {"text": "水壶", "is_correct": false, "explanation": "语义：水壶是用具，不是学习取得的成绩。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“学习”不修饰沙发，“学习沙发”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不能作为学习的成果被老师看。"}], "explanations": {"成果": "正确：“学习成果”指学习中取得的成绩，老师可以看，也可以满意。", "水壶": "语义：水壶是用具，不是学习取得的成绩。", "沙发": "搭配：“学习”不修饰沙发，“学习沙发”说不通。", "冰箱": "语义：冰箱是家电，不能作为学习的成果被老师看。"}, "sentence_index": 6, "correct_answer": "成果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成果增加了三公斤。", "explanation": "这里应该用〈体重〉。体重是人的重量，成果指工作或学习中取得的成绩，不能用来说重量增加。"}, {"text": "这块布的成果很软。", "explanation": "这里应该用〈质地〉。布料的软硬要用质地，成果指工作或学习中取得的成绩，不能用来形容布料。"}, {"text": "这种药的成果很好。", "explanation": "这里应该用〈效果〉。药物的作用要用效果，成果指工作或学习中取得的成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把研究成果很重要。", "corrected_sentence": "这项研究成果很重要。", "error_description": "量词错误：“研究成果”应用量词“项”。“把”用于有柄的器具，不能用于成果，应改为“这项研究成果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们取得了一座不错的成果。", "corrected_sentence": "他们取得了一项不错的成果。", "error_description": "量词错误：“成果”应用量词“项”。“座”用于山、楼房等大型建筑，不能用于成果，应改为“一项成果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
