INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "掌握是学会了，会用了。", "primary_collocate": null, "pronunciation": "zhǎng wò", "ipa": "tʂaŋ˨˩˦ uo˥˩", "syllable_count": 2, "sentences": [{"text": "他已经掌握了这个方法。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好汉语要掌握很多词。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子慢慢掌握了骑车的方法。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想掌握一门新技术。", "target_word": "掌握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你掌握这些语法了吗？", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要多练习，才能掌握这个技术。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用三个月掌握了做饭的办法。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这些新词都掌握了。", "target_word": "掌握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们正在掌握新学的知识。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她已经掌握了三门外语。", "target_word": "掌握", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掌握了", "label": "体标"}, {"form": "掌握着", "label": "体标"}, {"form": "掌握过", "label": "体标"}], "register": "中性", "sense_fingerprint": "掌握·学会并会用知识或技能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86885, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掌握", "is_correct": true, "explanation": "正确：“掌握”表示学会并会用，与“这个方法”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“方法”不能被“吃”，学会一个方法不能说“吃了”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦是擦拭的意思，与学会并会用的方法不符。"}, {"text": "喂", "is_correct": false, "explanation": "语义：喂是给人或动物吃东西，与“方法”不相关。"}], "explanations": {"掌握": "正确：“掌握”表示学会并会用，与“这个方法”搭配自然。", "吃": "搭配：“方法”不能被“吃”，学会一个方法不能说“吃了”。", "擦": "语义：擦是擦拭的意思，与学会并会用的方法不符。", "喂": "语义：喂是给人或动物吃东西，与“方法”不相关。"}, "sentence_index": 0, "correct_answer": "掌握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他紧紧掌握着手里的那把伞。", "explanation": "这里应该用〈握〉。“掌握”指学会或能熟练运用、控制，不能用来形容用手拿着一把伞。"}, {"text": "我想掌握一个温暖的微笑。", "explanation": "这里应该用〈露出〉。“掌握”的对象应是知识或技能，“微笑”不能被学会。"}, {"text": "她掌握了一大块蛋糕。", "explanation": "这里应该用〈吃〉。“掌握”不能以食物为对象，“蛋糕”不是知识或技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌握", "is_correct": true, "explanation": "正确：“掌握”表示学会并会用，与“做饭的办法”搭配自然。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不能用来指学会做饭的办法。"}, {"text": "扫", "is_correct": false, "explanation": "语义：扫是打扫，与“做饭的办法”不相关。"}, {"text": "关", "is_correct": false, "explanation": "搭配：“办法”不能被“关”，学会一个办法不能说“关了”。"}], "explanations": {"掌握": "正确：“掌握”表示学会并会用，与“做饭的办法”搭配自然。", "唱": "语义：唱是唱歌，不能用来指学会做饭的办法。", "扫": "语义：扫是打扫，与“做饭的办法”不相关。", "关": "搭配：“办法”不能被“关”，学会一个办法不能说“关了”。"}, "sentence_index": 6, "correct_answer": "掌握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她掌握着一只小猫。", "explanation": "这里应该用〈养〉。“掌握”的对象应是知识或技能，不能是小动物。"}, {"text": "她掌握了一扇窗户。", "explanation": "这里应该用〈打开〉。“掌握”不能以窗户为对象。"}, {"text": "她掌握了一场雨。", "explanation": "这里应该用〈下〉。“掌握”不能以天气现象为对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生要掌握很好这门课。", "corrected_sentence": "学生要掌握好这门课。", "error_description": "补语错误：结果补语“好”前不能加“很”，应说“掌握好这门课”，不能说“掌握很好这门课”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她掌握很好。", "corrected_sentence": "她掌握得很好。", "error_description": "补语错误：表示程度的补语前需要“得”，应说“掌握得很好”，不能说“掌握很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
