INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "了解并能熟练运用；控制。", "primary_collocate": null, "pronunciation": "zhǎng wò", "ipa": "tʂaŋ˨˩˦ uo˥˩", "syllable_count": 2, "sentences": [{"text": "司机要掌握好方向。", "target_word": "掌握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你要掌握好时间，别迟到。", "target_word": "掌握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "年轻人要自己掌握自己的命运。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他熟练掌握了三种电脑语言。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭时要掌握好火候。", "target_word": "掌握", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生必须掌握病人的情况。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司掌握着最新的技术。", "target_word": "掌握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的情况，警察已经掌握了。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没掌握好力气，把杯子打破了。", "target_word": "掌握", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要掌握学习的主动权。", "target_word": "掌握", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "掌握了", "label": "体标"}, {"form": "掌握着", "label": "体标"}, {"form": "掌握过", "label": "体标"}], "register": "中性", "sense_fingerprint": "掌握·了解情况、熟练运用或控制住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043aa009-a719-4f20-b3b2-bdf490915713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掌握", "is_correct": true, "explanation": "正确：“掌握好方向”指控制住方向，与“司机”搭配自然。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，与驾驶方向无关。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“方向”不能被烧，“烧好方向”说不通。"}, {"text": "扫", "is_correct": false, "explanation": "语义：扫是打扫，不能用于驾驶时控制的方向。"}], "explanations": {"掌握": "正确：“掌握好方向”指控制住方向，与“司机”搭配自然。", "唱": "语义：唱是唱歌，与驾驶方向无关。", "烧": "搭配：“方向”不能被烧，“烧好方向”说不通。", "扫": "语义：扫是打扫，不能用于驾驶时控制的方向。"}, "sentence_index": 0, "correct_answer": "掌握"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他掌握了一篮水果。", "explanation": "这里应该用〈提〉。“掌握”的对象是局面、权力或技术，一篮水果不能被掌握，应说“提”。"}, {"text": "她掌握了一颗糖。", "explanation": "这里应该用〈吃〉。“掌握”不能跟糖搭配，糖不是可以控制的对象。"}, {"text": "他掌握了这块石头。", "explanation": "这里应该用〈搬〉。“掌握”指了解并能熟练运用或控制，石头不是可以掌握的对象，应说“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌握", "is_correct": true, "explanation": "正确：“掌握着最新的技术”指拥有并控制这项技术，与“公司”搭配自然。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬是用牙齿夹住，不能用于拥有技术。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“技术”不能被剪，“剪着技术”说不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹调，与“最新的技术”不相关。"}], "explanations": {"掌握": "正确：“掌握着最新的技术”指拥有并控制这项技术，与“公司”搭配自然。", "咬": "语义：咬是用牙齿夹住，不能用于拥有技术。", "剪": "搭配：“技术”不能被剪，“剪着技术”说不通。", "煮": "语义：煮是烹调，与“最新的技术”不相关。"}, "sentence_index": 6, "correct_answer": "掌握"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈掌握了一顿晚餐。", "explanation": "这里应该用〈做〉。“掌握”的对象是局面、技术或知识，一顿晚餐不能被掌握，应说“做”。"}, {"text": "孩子掌握了一双鞋。", "explanation": "这里应该用〈穿〉。“掌握”的对象是局面或权力，不能是鞋子。"}, {"text": "他掌握了一杯牛奶。", "explanation": "这里应该用〈喝〉。“掌握”的对象是局面、权力或技术，一杯牛奶不能被掌握，应说“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机要掌握很好车速。", "corrected_sentence": "司机要掌握好车速。", "error_description": "补语错误：结果补语“好”前不能加“很”，应说“掌握好车速”，不能说“掌握很好车速”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司掌握了着核心技术。", "corrected_sentence": "公司掌握着核心技术。", "error_description": "体标错误：“着”表示持续状态，与“了”不能同时用，“了”多余，应说“掌握着核心技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a01baeb-4c4d-4efc-b7c5-f345ae78b6b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
