INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86899, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东部是太阳出来的那一边的地方。", "primary_collocate": null, "pronunciation": "dōng bù", "ipa": "tʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "我家在城市的东部。", "target_word": "东部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太阳从东部的山后面出来。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的东部有一个很大的公园。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校在小镇的东部，离河很近。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖的东部水很浅，孩子们常去玩。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们从西部走到东部，用了三个小时。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子在城市的东部，早上阳光很好。", "target_word": "东部", "complexity_tier": "T3", "furigana": "fáng zi zài chéng shì de dōng bù, zǎo shang yáng guāng hěn hǎo.", "sentence_source": "generated"}, {"text": "公园东部种着很多花。", "target_word": "东部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在村子的东部，每天走路去上班。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山的东部比西部高，雪也更多。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "东部地区", "label": "复合"}, {"form": "东南部", "label": "复合"}], "register": "中性", "sense_fingerprint": "某个地方或城市靠太阳升起那一边的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab628bc3-ddad-4bad-aa8a-0184cfa7bf3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东部", "is_correct": true, "explanation": "正确：“东部”是方位名词，指城市偏东的地区，符合“城市的东部”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不是地点，不能说“城市的桌子”表示位置。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“名字”不能表示处所，与“在城市的……”引出的地点不搭配。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”是抽象概念，不能表示城市中的位置。"}], "explanations": {"东部": "正确：“东部”是方位名词，指城市偏东的地区，符合“城市的东部”。", "桌子": "语义：“桌子”是家具，不是地点，不能说“城市的桌子”表示位置。", "名字": "搭配：“名字”不能表示处所，与“在城市的……”引出的地点不搭配。", "感情": "语义：“感情”是抽象概念，不能表示城市中的位置。"}, "sentence_index": 0, "correct_answer": "东部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的东部很好听。", "explanation": "这里应该用〈旋律〉。东部指地方，不能用来指歌曲的组成部分。"}, {"text": "我喝了一杯东部。", "explanation": "这里应该用〈果汁〉。东部指东边的地方，不能作为饮品。"}, {"text": "他的东部很痛。", "explanation": "这里应该用〈胸部〉。东部指地方，不能用来指身体的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东部", "is_correct": true, "explanation": "正确：“东部”是方位名词，指城市偏东的地区，符合“房子在城市的东部”。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：“口袋”是物品，不能作为城市中的位置，与“房子在……”不符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来描述房子的位置。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是小物件，不表示地点，与“城市的……”的语义冲突。"}], "explanations": {"东部": "正确：“东部”是方位名词，指城市偏东的地区，符合“房子在城市的东部”。", "口袋": "语义：“口袋”是物品，不能作为城市中的位置，与“房子在……”不符。", "身材": "体貌：“身材”指人的体形，不能用来描述房子的位置。", "钥匙": "语义：“钥匙”是小物件，不表示地点，与“城市的……”的语义冲突。"}, "sentence_index": 6, "correct_answer": "东部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把东部放进了书包。", "explanation": "这里应该用〈地图〉。东部指东边的地方，不能被装进书包。"}, {"text": "我的同学是东部。", "explanation": "这里应该用〈住在〉。东部是地方，不能直接作“是”的宾语，应说“住在东部”。"}, {"text": "他用东部写了一封信。", "explanation": "这里应该用〈钢笔〉。东部指地区，不能作为书写工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的学校在城市一东部。", "corrected_sentence": "他的学校在城市的东部。", "error_description": "错误形式：“城市一东部”。正确形式：“城市的东部”。方位名词“东部”作定语时须用“的”连接，不能直接与数词“一”组合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港口在岛的很东部。", "corrected_sentence": "港口在岛的东部。", "error_description": "错误形式：“很东部”。正确形式：“东部”是方位名词，不能被副词“很”修饰，应说“岛的东部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
