INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东边的地区。", "primary_collocate": null, "pronunciation": "dōng bù", "ipa": "tʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "中国东部有很多大城市。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "美国东部的冬天很冷。", "target_word": "东部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "东部地区的人比西部多。", "target_word": "东部", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个国家的东部雨水很多。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去过东部的海边，那里很美。", "target_word": "东部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东部的火车比西部多，坐车很方便。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在东部上大学，毕业后回了家。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天，东部很多地方都下大雨。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东部的经济比西部发展得快。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家公司在东部开了十家新店。", "target_word": "东部", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "东部地区", "label": "复合"}, {"form": "东北部", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家或大范围区域中偏东的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab628bc3-ddad-4bad-aa8a-0184cfa7bf3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东部", "is_correct": true, "explanation": "正确：“东部”指国家内偏东的地区，符合“中国东部有很多大城市”。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：“沙发”是家具，不能指国家中的地区，与“有很多大城市”的语义冲突。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的身体，不能用来指地区。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象现象，不能作为地区，无法与“有很多大城市”搭配。"}], "explanations": {"东部": "正确：“东部”指国家内偏东的地区，符合“中国东部有很多大城市”。", "沙发": "语义：“沙发”是家具，不能指国家中的地区，与“有很多大城市”的语义冲突。", "身高": "体貌：“身高”描述人的身体，不能用来指地区。", "天气": "语义：“天气”是气象现象，不能作为地区，无法与“有很多大城市”搭配。"}, "sentence_index": 0, "correct_answer": "东部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上用东部刷牙。", "explanation": "这里应该用〈牙膏〉。东部指地区，不能用来刷牙。"}, {"text": "我们把东部都收拾好了。", "explanation": "这里应该用〈东西〉。东部指地区，不能被当作可以收拾的物品。"}, {"text": "他的东部伤得很厉害。", "explanation": "这里应该用〈腿部〉。东部指地区，不能用来指身体的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东部", "is_correct": true, "explanation": "正确：“东部”指国家内偏东的地区，符合“他在东部上大学”。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是场所，不是地区，“上大学”需要学校或地区的语境，“食堂”不符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”描述人的体形，不能用来表示上学的地点。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不能作为“在……上大学”的地点。"}], "explanations": {"东部": "正确：“东部”指国家内偏东的地区，符合“他在东部上大学”。", "食堂": "语义：“食堂”是场所，不是地区，“上大学”需要学校或地区的语境，“食堂”不符。", "身材": "体貌：“身材”描述人的体形，不能用来表示上学的地点。", "书包": "语义：“书包”是物品，不能作为“在……上大学”的地点。"}, "sentence_index": 6, "correct_answer": "东部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈煮了一锅东部。", "explanation": "这里应该用〈汤〉。东部指地区，不能被煮。"}, {"text": "我的哥哥是东部。", "explanation": "这里应该用〈东部人〉。“东部”是地区名，指人须加“人”，不能直接作“是”的宾语。"}, {"text": "她用东部画了一幅画。", "explanation": "这里应该用〈画笔〉。东部指地区，不能作为绘画工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市的很东部很热闹。", "corrected_sentence": "这座城市的东部很热闹。", "error_description": "错误形式：“很东部”。正确形式：“东部”是名词，不能被副词“很”修饰，应说“城市的东部很热闹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司把东部开了三家分店。", "corrected_sentence": "这家公司在东部开了三家分店。", "error_description": "错误形式：“把东部”。正确形式：“在东部”。“东部”是表示地区的名词，不能作“把”的宾语，地点要用“在”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f4d9a8-94a8-45a0-b85f-25d39fce93ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
