INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "西是太阳落下去的那一边。", "primary_collocate": null, "pronunciation": "xī", "ipa": "ɕi˥", "syllable_count": 1, "sentences": [{"text": "太阳从东边出来，要往西落下去。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你面向北，右手是东，左手是西。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东、西、南、北，你分得清吗？", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园的大门朝西，早上不太亮。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他骑车往西去了，我往东走。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这列火车从东往西开。", "target_word": "西", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "向东走是学校，向西走是医院。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风从东吹到西，树叶都动了。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一直往西，你会看到一座大桥。", "target_word": "西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上我看着太阳向西慢慢落下。", "target_word": "西", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "西边", "label": "复合词"}, {"form": "西方", "label": "复合词"}, {"form": "西部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "太阳落下去的那一边，用来指路辨方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7a1d248-553b-4926-a225-0466394be207') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (86923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "西", "is_correct": true, "explanation": "正确：表示太阳落下的方向，与“从东边出来”相对。"}, {"text": "东", "is_correct": false, "explanation": "语义：「往东落下去」与“从东边出来”冲突，太阳不会向东落下。"}, {"text": "西餐", "is_correct": false, "explanation": "搭配：「西餐」是食物，不能表示太阳落下的方向。"}, {"text": "西服", "is_correct": false, "explanation": "搭配：「西服」是衣服，不能表示太阳落下的方向。"}], "explanations": {"西": "正确：表示太阳落下的方向，与“从东边出来”相对。", "东": "语义：「往东落下去」与“从东边出来”冲突，太阳不会向东落下。", "西餐": "搭配：「西餐」是食物，不能表示太阳落下的方向。", "西服": "搭配：「西服」是衣服，不能表示太阳落下的方向。"}, "sentence_index": 0, "correct_answer": "西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家书店的装修很西，我常去。", "explanation": "这里应该用〈西式〉。〈西〉不能直接修饰装修表示西式风格，要说〈西式〉。"}, {"text": "这家饭店很西，我最爱吃。", "explanation": "这里应该用〈西式〉。〈西〉作形容词修饰饭店不规范，表示西式风格要说〈西式〉。"}, {"text": "他是西人，说话很幽默。", "explanation": "这里应该用〈西方人〉。〈西〉在此指“西方”，不是太阳落下的方向，与本义不符；〈西人〉也不是常用说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70e18ada-3134-4ff9-8ed5-f024c8f396f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
